        InputFile *file = (InputFile *)malloc(sizeof(InputFile));
        file->filename = filename;
        file->fd = open(file->filename, O_RDONLY);
        if (file->fd == -1) {
            fprintf(stderr, "Error opening input file: %s\n", strerror(errno));
