        pthread_join(threads[i], &status);
    }

    // Aggregate the results across all files
    barrier = (pthread_barrier_t *)malloc(sizeof(pthread_barrier_t));
    pthread_barrier_init(barrier, NULL, num_threads + 1);
    for (int i = 0; i < num_threads; i++) {
