// Function to aggregate the results across all files
int aggregate_results(InputFile *file, int threadid) {
    // Initialize the root node of the JSON document in the file
    file->root = json_parse_file(file->filename);
    if (file->root == NULL) {
        fprintf(stderr, "Error parsing input file: %s\n", strerror(errno));
        cleanup();
