    if (strcmp(key_size, "1024") == 0) {
        return 1024;
    } else if (strcmp(key_size, "2048") == 0) {
        return 2048;
    } else if (strcmp(key_size, "3072") == 0) {
        return 3072;
    } else if (strcmp(key_size, "4096") == 0) {
        return 4096;
    } else {
        // Fallback to 256-bit key by default
        return DEFAULT_KEY_SIZE;
    }
}

int get_iv_size(const char* iv_size) {
    if (strcmp(iv_size, "16") == 0) {
        return 16;
    } else if (strcmp(iv_size, "32") == 0) {
        return 32;
    } else {
        // Fallback to 16-byte IV by default
        return DEFAULT_IV_SIZE;
    }
}

int generate_key(encryption_context_t* ctx) {
    // Generate a new key and initialize the context
    RSA* rsa = NULL;
    unsigned char* key = NULL;
    size_t key_size = 0;
    int retval = -1;

    // Create a new RSA key
    if ((rsa = RSA_new()) == NULL) {
        goto error;
    }

    // Set the key size and generate the key pair
    if (RSA_generate_key_ex(rsa, get_key_size(ctx->key_size), 65537, NULL) != 1) {
        goto error;
    }

    // Extract the public key from the RSA object
    if ((key = RSA_get0_key(rsa)) == NULL) {
        goto error;
    }

    // Allocate memory for the key
    if ((ctx->key = OPENSSL_malloc(RSA_size(rsa))) == NULL) {
        goto error;
    }

    // Copy the public key to the context
    memcpy(ctx->key, key, RSA_size(rsa));

    // Update the key size
    ctx->key_size = RSA_size(rsa);

    // Free the memory allocated for the RSA object
    RSA_free(rsa);

    return 0;

error:
    if (rsa != NULL) {
        RSA_free(rsa);
    }
    if (key != NULL) {
        OPENSSL_free(key);
    }
    return retval;
}

int encrypt(encryption_context_t* ctx, const unsigned char* input, size_t input_size, unsigned char** output, size_t* output_size) {
    // Allocate memory for the encrypted data
    *output = OPENSSL_malloc(input_size);
    if (*output == NULL) {
        return -1;
    }

    // Set the algorithm and key size
    EVP_CIPHER_CTX* ctx_encrypt = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx_encrypt, get_algorithm(ctx->algorithm), NULL, NULL, NULL) != 1) {
        goto error;
    }
    if (EVP_CIPHER_CTX_set_key_length(ctx_encrypt, ctx->key_size) != 1) {
        goto error;
    }
    if (EVP_EncryptInit_ex(ctx_encrypt, NULL, NULL, ctx->key, ctx->iv) != 1) {
        goto error;
    }

    // Encrypt the data
    int outlen = 0;
    if (EVP_EncryptUpdate(ctx_encrypt, *output, &outlen, input, input_size) != 1) {
        goto error;
    }

    // Set the output size and clean up
    *output_size = outlen;
    EVP_CIPHER_CTX_free(ctx_encrypt);

    return 0;

error:
    if (ctx_encrypt != NULL) {
        EVP_CIPHER_CTX_free(ctx_encrypt);
    }
    if (*output != NULL) {
        OPENSSL_free(*output);
    }
    return -1;
}

int decrypt(encryption_context_t* ctx, const unsigned char* input, size_t input_size, unsigned char** output, size_t* output_size) {
    // Allocate memory for the decrypted data
    *output = OPENSSL_malloc(input_size);
    if (*output == NULL) {
        return -1;
    }

    // Set the algorithm and key size
    EVP_CIPHER_CTX* ctx_decrypt = EVP_CIPHER_CTX_new();
    if (EVP_DecryptInit_ex(ctx_decrypt, get_algorithm(ctx->algorithm), NULL, NULL, NULL) != 1) {
        goto error;
    }
    if (EVP_CIPHER_CTX_set_key_length(ctx_decrypt, ctx->key_size) != 1) {
        goto error;
    }
    if (EVP_DecryptInit_ex(ctx_decrypt, NULL, NULL, ctx->key, ctx->iv) != 1) {
        goto error;
    }

    // Decrypt the data
    int outlen = 0;
    if (EVP_DecryptUpdate(ctx_decrypt, *output, &outlen, input, input_size) != 1) {
        goto error;
    }

    // Set the output size and clean up
    *output_size = outlen;
    EVP_CIPHER_CTX_free(ctx_decrypt);

    return 0;

error:
    if (ctx_decrypt != NULL) {
        EVP_CIPHER_CTX_free(ctx_decrypt);
    }
    if (*output != NULL) {
        OPENSSL_free(*output);
    }
    return -1;
}
```
The code above defines a `encryption_context_t` structure that contains the necessary fields for generating and using an RSA key, as well as functions for encrypting and decrypting data. The `generate_key()` function creates a new RSA key pair and stores it in the context structure. The `encrypt()` and `decrypt()` functions use the OpenSSL library to perform encryption and decryption of data using the provided context structure.

The code above also defines some global variables that are used to store the path to the RSA private key file, as well as a flag indicating whether the private key should be generated or not. This allows the user to specify either a pre-existing private key file or to have the script generate a new one.

The `main()` function of the script takes three arguments: the input data, the path to the RSA private key file (or "generate" if a new private key should be generated), and the output file name. The code first initializes an `encryption_context_t` structure and sets up the OpenSSL library. If the user specified to generate a new private key, the script generates a new one using the `generate_key()` function. Then it reads in the input data from the specified file, encrypts it using the encryption function, and writes the output data to the specified output file. Finally, the script cleans up and exits.
