int main(int argc, char* argv[]) {
    encryption_context_t ctx;
    FILE* input_file = NULL;
    unsigned char* input = NULL;
    size_t input_size = 0;
    unsigned char* output = NULL;
    size_t output_size = 0;
    int retval = -1;

    // Initialize the encryption context and OpenSSL library
    if ((retval = init_encryption_context(&ctx)) != 0) {
        goto error;
    }

    // If the user specified to generate a new private key, do so
    if (strcmp(argv[1], "generate") == 0) {
        if ((retval = generate_key(&ctx)) != 0) {
            goto error;
        }
    } else {
