    input_size = ftell(input_file);
    rewind(input_file);
    input = malloc(sizeof(unsigned char) * input_size);
    if (!input) {
        retval = -1;
        goto error;
    }
    fread(input, sizeof(unsigned char), input_size, input_file);

    // Encrypt the data using the specified algorithm and key size
    if ((retval = encrypt(&ctx, input, input_size, &output, &output_size)) != 0) {
        goto error;
    }

    // Write the encrypted output to the specified file
    FILE* output_file = fopen(argv[4], "w");
    if (!output_file) {
        retval = -1;
        goto error;
    }
    fwrite(output, sizeof(unsigned char), output_size, output_file);
    fclose(output_file);

error:
    // Clean up and exit
    if (input) {
        free(input);
    }
    if (output) {
        free(output);
    }
    if (input_file) {
        fclose(input_file);
    }
    return retval;
}
