// Global semaphore instance limit (10,000)
#define SEMAPHORE_INSTANCE_LIMIT 10000

// Maximum number of available permits for each semaphore
#define MAX_AVAILABLE_PERMITS 10

// Semaphore structure to hold information about each semaphore instance
struct semaphore {
    char* name;                     // Name of the semaphore
    int initial_value;              // Initial value of the semaphore
    int current_value;              // Current value of the semaphore
    pthread_mutex_t mutex;          // Mutex to protect concurrent access
    sem_t* sem;                     // Semaphore handle
    struct timespec created_at;     // Timestamp when the semaphore was created
    struct timespec updated_at;     // Timestamp when the semaphore was last modified
};

// Linked list to hold all semaphore instances
struct semaphore* semaphore_list = NULL;

// Function to create a new semaphore instance
int create_semaphore(char* name, int initial_value) {
    // Check if the maximum number of instances has been reached
    if (semaphore_count() >= SEMAPHORE_INSTANCE_LIMIT) {
        return -1;
    }

    // Allocate memory for the semaphore structure
    struct semaphore* new_semaphore = malloc(sizeof(struct semaphore));
    if (new_semaphore == NULL) {
        perror("malloc");
        return -1;
    }

    // Initialize the mutex and semaphore handles
    pthread_mutex_init(&new_semaphore->mutex, NULL);
    new_semaphore->sem = malloc(sizeof(sem_t));
    if (new_semaphore->sem == NULL) {
        perror("malloc");
        return -1;
    }

    // Initialize the semaphore with the given initial value
    sem_init(new_semaphore->sem, 0, initial_value);

    // Set the name and timestamp for the new semaphore instance
    new_semaphore->name = strdup(name);
    clock_gettime(CLOCK_REALTIME, &new_semaphore->created_at);
    new_semaphore->updated_at = new_semaphore->created_at;

    // Add the new semaphore instance to the linked list
    new_semaphore->next = semaphore_list;
    semaphore_list = new_semaphore;

    return 0;
}

// Function to delete a semaphore instance
int delete_semaphore(char* name) {
    // Find the semaphore instance with the given name
    struct semaphore* current = semaphore_list;
    while (current != NULL && strcmp(current->name, name) != 0) {
        current = current->next;
    }

    // Check if the semaphore instance was found
    if (current == NULL) {
        return -1;
    }

    // Release the mutex and delete the semaphore handle
    pthread_mutex_destroy(&current->mutex);
    free(current->sem);

    // Remove the semaphore instance from the linked list
    struct semaphore** previous = &semaphore_list;
    while (*previous != NULL && *previous != current) {
        previous = &(*previous)->next;
    }
    *previous = current->next;

    // Free the memory used by the semaphore instance
    free(current->name);
    free(current);

    return 0;
}

// Function to acquire a semaphore instance
int acquire_semaphore(char* name) {
    // Find the semaphore instance with the given name
    struct semaphore* current = semaphore_list;
    while (current != NULL && strcmp(current->name, name) != 0) {
        current = current->next;
    }

    // Check if the semaphore instance was found
    if (current == NULL) {
        return -1;
    }

    // Acquire the mutex and decrease the available permits
    pthread_mutex_lock(&current->mutex);
    current->current_value--;

    // Check if the semaphore is already acquired by another thread
    if (current->current_value < 0) {
        return -1;
    }

    // Log the acquisition and update the timestamp
    log_acquisition(name);
    clock_gettime(CLOCK_REALTIME, &current->updated_at);

    return 0;
}

// Function to release a semaphore instance
int release_semaphore(char* name) {
    // Find the semaphore instance with the given name
    struct semaphore* current = semaphore_list;
    while (current != NULL && strcmp(current->name, name) != 0) {
        current = current->next;
    }

    // Check if the semaphore instance was found
    if (current == NULL) {
        return -1;
    }

    // Release the mutex and increase the available permits
    pthread_mutex_unlock(&current->mutex);
    current->current_value++;

    // Check if the semaphore is already released by another thread
    if (current->current_value > MAX_AVAILABLE_PERMITS) {
        return -1;
    }

    // Log the release and update the timestamp
    log_release(name);
    clock_gettime(CLOCK_REALTIME, &current->updated_at);

    return 0;
}

// Function to get the current number of available permits for a semaphore instance
int get_available_permits(char* name) {
    // Find the semaphore instance with the given name
    struct semaphore* current = semaphore_list;
    while (current != NULL && strcmp(current->name, name) != 0) {
        current = current->next;
    }

    // Check if the semaphore instance was found
    if (current == NULL) {
        return -1;
    }

    // Get the current value of the semaphore and add the available permits
    int available_permits = current->current_value + MAX_AVAILABLE_PERMITS;

    return available_permits;
}

// Function to get the number of semaphore instances
int get_semaphore_count() {
    int count = 0;
    struct semaphore* current = semaphore_list;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    return count;
}

// Function to get the names of all semaphore instances
char** get_semaphore_names() {
    int count = get_semaphore_count();
    char** names = malloc(sizeof(char*) * count);
    struct semaphore* current = semaphore_list;
    for (int i = 0; i < count; i++) {
        names[i] = strdup(current->name);
        current = current->next;
    }

    return names;
}

