## Solution 3 - Semaphore Manager with a Hash Table

The `SemaphoreManager` class with a hash table implementation is shown below:

```java
import java.util.HashMap;
import java.util.Map;

public class SemaphoreManager {
    private Map<String, Integer> semaphores = new HashMap<>();

    public void createSemaphore(String name, int value) {
        semaphores.put(name, value);
    }

    public void deleteSemaphore(String name) {
        semaphores.remove(name);
    }

    public boolean acquireSemaphore(String name) {
        if (semaphores.containsKey(name)) {
            int value = semaphores.get(name);
            if (value > 0) {
                semaphores.put(name, value - 1);
                return true;
            } else {
                return false;
            }
        } else {
            return false;
        }
    }

    public boolean releaseSemaphore(String name) {
        if (semaphores.containsKey(name)) {
            int value = semaphores.get(name);
            if (value < 0) {
                return false;
            } else {
                semaphores.put(name, value + 1);
                return true;
            }
        } else {
            return false;
        }
    }

    public int getAvailablePermits(String name) {
        if (semaphores.containsKey(name)) {
            int value = semaphores.get(name);
            return value + 5;
        } else {
            return -1;
        }
    }

    public int getSemaphoreCount() {
        return semaphores.size();
    }

    public String[] getSemaphoreNames() {
        String[] names = new String[semaphores.size()];
        int i = 0;
        for (String name : semaphores.keySet()) {
            names[i++] = name;
        }
        return names;
    }
}
