void appendOrInsertAfter(DistributedStringList& list, const std::string& target, const std::string& value) {
    std::unique_lock<std::mutex> lock(list.getMutex());
    auto it = std::find(list.begin(), list.end(), target);
    if (it != list.end()) {
        // found the target, insert the new value after it
        list.insertAfter(*it, value);
