    std::condition_variable cv;

    void addVm(const std::string& ip, const std::string& uuid) {
        std::lock_guard<std::mutex> lock(mutex);
        vmUuidMap[ip] = uuid;
        cv.notify_all();
    }

    void removeVm(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mutex);
        vmUuidMap.erase(ip);
        cv.notify_all();
    }

    bool findVmUuidFromMetadataIp(const std::string& ip, std::string& uuid) {
        std::unique_lock<std::mutex> lock(mutex);
        while (vmUuidMap.find(ip) == vmUuidMap.end()) {
            cv.wait(lock);
        }
        uuid = vmUuidMap[ip];
        return true;
    }
};

