using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Text.Json;
using System.Xml.Serialization;
using System.Net.Http;
using Newtonsoft.Json;
using RestSharp;
using Newtonsoft.Json.Linq;

namespace MultiPlatformGameEngineConfigService
{
    public class ConfigService : IConfigService
    {
        private static readonly HttpClient _httpClient = new HttpClient();
        private static readonly JsonSerializerOptions _jsonSerializerOptions = new JsonSerializerOptions();
        private static readonly XmlSerializer _xmlSerializer = new XmlSerializer();
        private static readonly ConcurrentDictionary<string, Config> _configCache = new ConcurrentDictionary<string, Config>();
        private static readonly IConfigProvider _configProvider;

        static ConfigService()
        {
            // Setup JSON serializer options
            _jsonSerializerOptions.PropertyNamingPolicy = JsonNamingPolicy.CamelCase;
            _jsonSerializerOptions.ReadCommentHandling = JsonCommentHandling.Skip;
            _jsonSerializerOptions.WriteIndented = true;

            // Setup XML serializer
            var xmlSerializer = new XmlSerializer(typeof(Config));

            // Setup config provider based on environment variable
            if (Environment.GetEnvironmentVariable("GAME_ENGINE_CONFIG_PROVIDER") == "REST")
            {
                _configProvider = new RestConfigProvider();
            }
            else if (Environment.GetEnvironmentVariable("GAME_ENGINE_CONFIG_PROVIDER") == "FILE")
            {
                _configProvider = new FileConfigProvider();
            }
        }

        public async Task<Config> GetConfigAsync(string configName)
        {
            // Check if config is in cache
            if (_configCache.TryGetValue(configName, out Config config))
            {
                return config;
            }

            // Fetch config from provider
            var fetchedConfig = await _configProvider.FetchConfigAsync(configName);

            // Deserialize config based on content type
            if (fetchedConfig.ContentType == "application/json")
            {
                config = JsonSerializer.Deserialize<Config>(fetchedConfig.Body, _jsonSerializerOptions);
            }
            else if (fetchedConfig.ContentType == "application/xml")
            {
                config = XmlSerializer.Deserialize<Config>(fetchedConfig.Body, _xmlSerializer);
            }
            else
            {
                throw new NotSupportedException($"Unsupported content type '{fetchedConfig.ContentType}'");
            }

            // Cache config and return it
            _configCache.TryAdd(configName, config);
            return config;
        }
    }
}
