    public class XMLService : IDisposable
    {
        private readonly XmlSchema _schema;
        private readonly MemoryCache _cache;
        private readonly List<string> _apiEndpoints;
        private int _rateLimit;
        private int _retryCount;
        private TimeSpan _timeout;

        public XMLService(XmlSchema schema, MemoryCache cache, List<string> apiEndpoints)
        {
            _schema = schema;
            _cache = cache;
            _apiEndpoints = apiEndpoints;
            _rateLimit = 10;
            _retryCount = 3;
            _timeout = TimeSpan.FromSeconds(5);
        }

        public async Task<XDocument> GetXMLDataAsync(string xPathQuery)
        {
            XDocument document = null;

            if (_cache.Contains(xPathQuery))
            {
                document = (XDocument)_cache[xPathQuery];
            }
            else
            {
                var apiEndpoint = _apiEndpoints[_apiEndpoints.Count - 1];
                document = await GetXMLDataFromAPIAsync(apiEndpoint, xPathQuery);
            }

            return document;
        }

        private async Task<XDocument> GetXMLDataFromAPIAsync(string apiEndpoint, string xPathQuery)
        {
            XDocument document = null;

            for (var i = 0; i < _retryCount; i++)
            {
                try
                {
                    var client = new HttpClient();
                    var response = await client.GetAsync(apiEndpoint);

                    if (response.IsSuccessStatusCode)
                    {
                        document = XDocument.Parse(await response.Content.ReadAsStringAsync());
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error retrieving data from API: {ex}");
                }
            }

            if (_rateLimit > 0 && i >= _retryCount)
            {
                var delay = TimeSpan.FromSeconds(_rateLimit);
                await Task.Delay(delay);
            }

            return document;
        }

        public void AddXPathQueryToCache(string xPathQuery, XDocument document)
        {
            if (!_cache.Contains(xPathQuery))
            {
                _cache.Add(xPathQuery, document);
            }
        }

        public XDocument GetCachedDocument(string xPathQuery)
        {
            return (XDocument)_cache[xPathQuery];
        }

        public void Dispose()
        {
            if (_cache != null)
            {
                _cache.Dispose();
            }
        }
    }
}
