class Octree {
public:
    Octree() {}

    ~Octree() {}

    void insert(int pageSectionID, int elementID, std::string htmlContent) {
        std::lock_guard<std::mutex> lock(mMutex);
        mData[pageSectionID][elementID] = htmlContent;
        mCapacity.emplace(pageSectionID, std::make_pair(elementID, htmlContent));
    }

    void update(int pageSectionID, int elementID, std::string htmlContent) {
        std::lock_guard<std::mutex> lock(mMutex);
        mData[pageSectionID][elementID] = htmlContent;
        mCapacity.emplace(pageSectionID, std::make_pair(elementID, htmlContent));
    }

    void delete(int pageSectionID, int elementID) {
        std::lock_guard<std::mutex> lock(mMutex);
        mData[pageSectionID].erase(elementID);
        mCapacity.erase(pageSectionID);
    }

    std::string get(int pageSectionID, int elementID) {
        std::lock_guard<std::mutex> lock(mMutex);
        return mData[pageSectionID][elementID];
