function getModuleMetadata(moduleName) {
  let url = `${config.apiUrl}/modules/${moduleName}`;
  return http.get(url, (res) => {
    res.setEncoding('utf8');
    let data = '';
    res.on('data', (chunk) => {
      data += chunk;
    });
    res.on('end', () => {
      return JSON.parse(data);
    });
  }).on('error', (err) => {
    console.log(`Error retrieving module metadata: ${err}`);
  });
}

// Define a function to load and execute a JavaScript module
function loadModule(moduleName, callback) {
  let modulePath = path.join(config.modulesDir, `${moduleName}.js`);
  fs.access(modulePath, (err) => {
    if (err) {
      console.log(`Error loading module: ${moduleName}`);
      return callback(err);
    }
    let child = child_process.fork(modulePath, [], { silent: true });
    child.on('message', (data) => {
      if (data.type === 'error') {
        console.log(`Error executing module: ${moduleName}`);
        return callback(new Error(data.error));
      } else {
        console.log(`Module executed successfully: ${moduleName}`);
        return callback(null, data);
