// Library code for disjoint pair identification in a large integer array with concurrent modifications from multiple threads
package com.example.disjointpairs;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DisjointPairs {
    private static final int BATCH_SIZE = 10000;
    private static final Map<Integer, Integer> unionFind = new ConcurrentHashMap<>(); // Union-Find data structure for efficient disjoint pair identification
    private static final List<Integer> processedElements = new ArrayList<>(); // List to store processed elements
    private static final long startTime = System.currentTimeMillis(); // Start time of the program

    public static void main(String[] args) {
        int[] inputArray = new int[args.length]; // Input array from the user
        for (int i = 0; i < args.length; i++) {
            inputArray[i] = Integer.parseInt(args[i]);
        }

        // Initialize Union-Find data structure with each element as its own set
        for (int i : inputArray) {
            unionFind.put(i, i);
        }

        // Process the input array in batches of 10,000 elements
        long processingTime;
        int startIndex = 0;
        while (startIndex < inputArray.length) {
            int endIndex = Math.min(inputArray.length, startIndex + BATCH_SIZE);
            processingTime = System.currentTimeMillis();
            findDisjointPairs(inputArray, startIndex, endIndex);
            processedElements.add(endIndex - startIndex);
            System.out.println("Processed " + (endIndex - startIndex) + " elements in " + (System.currentTimeMillis() - processingTime) + " milliseconds");
            startIndex = endIndex;
        }

        // Log the time taken to process the input array
        System.out.println("Total time taken: " + (System.currentTimeMillis() - startTime) + " milliseconds");
    }

    private static void findDisjointPairs(int[] inputArray, int startIndex, int endIndex) {
        for (int i = startIndex; i < endIndex; i++) {
            for (int j = i + 1; j < endIndex; j++) {
                // Check if elements are part of the same set using Union-Find data structure
                if (unionFind.get(inputArray[i]) == unionFind.get(inputArray[j])) {
                    // If they are part of the same set, update their parent sets to create a new set with a larger size
                    int parent1 = findParent(inputArray[i]);
                    int parent2 = findParent(inputArray[j]);
                    unionFind.put(parent1, parent2);
                }
            }
        }
    }

    private static int findParent(int element) {
        // Find the parent of an element using Union-Find data structure
        while (unionFind.get(element) != element) {
            element = unionFind.get(element);
        }
        return element;
    }
}']

