public class CommunicationService {
  private static final Counter CONNECTION_COUNTER =
    PrometheusClient.register().counter("connection_count");
  private static final Gauge CONNECTION_GAUGE =
    PrometheusClient.register().gauge("connection_gauge", "Connections");
  private static final Summary LATENCY_SUMMARY =
    PrometheusClient.register().summary("latency_summary", "Latency in milliseconds");
  private static final ObjectMapper MAPPER = new ObjectMapper();

  private ExecutorService executor;
  private CloseableHttpAsyncClient httpClient;
  private ManagedChannel grpcChannel;
  private Function<String, Boolean> authInterceptor;
  private Function<String, Integer> rateLimiter;

  public CommunicationService() {
    executor = Executors.newFixedThreadPool(10);
    httpClient = HttpAsyncClients.custom().build();
    grpcChannel = ManagedChannelBuilder.forTarget("localhost:9000").usePlaintext().build();
  }

