// Define a function for handling external system interactions in a thread-safe manner
void handleExternalSystemInteractions() {
    // Create a mutex and condition variable for synchronizing concurrent access to the external API endpoint
    mutex mtx;
    condition_variable cv;

    // Initialize a vector of futures for storing the results of external system interactions
    vector<future<void>> futures;

    // Iterate over each transaction in the input vector
    for (const auto &transaction : transactions) {
        // Create a future for handling an individual external system interaction
