            }
        }));
    }

    // Wait for all futures to complete
    for (auto &future : futures) {
        future.wait();
    }
}

// Define a function for updating metrics in a thread-safe manner
void updateMetrics() {
    lock_guard<mutex> lg(mtx);

    // Update the maximum weighted sum and historical transaction metrics based on the input vector of transactions
    max_weighted_sum = 0.0;
    histogram.clear();
