    if (!file.is_open()) {
        cerr << "Error: File not found" << endl;
        return false;
    }

    // Check if the path conforms to standard Unix or Windows conventions
    string separator = "/";
    if (path.find(separator) == string::npos) {
        separator = "\\";
    }
    if (path.find_last_of(separator) != path.length() - 1) {
        cerr << "Error: Invalid file path" << endl;
        return false;
    }

    return true;
}

// Define a function to dynamically generate a new file name based on predefined rules
string generateNewFileName(const string& oldName, const string& metadata) {
    // Parse the old file name and extract the extension
    regex extensionRegex("\\.([a-zA-Z0-9]+)$");
    smatch extensionMatch;
    if (regex_search(oldName, extensionMatch, extensionRegex)) {
        string extension = extensionMatch[1].str();

        // Generate a new file name based on the current timestamp and checksum of the file content
        auto now = chrono::system_clock::now();
        int64_t timeStamp = chrono::duration_cast<chrono::seconds>(now.time_since_epoch()).count();
        stringstream ss;
        ss << metadata << "-" << timeStamp;
        string newName = oldName.substr(0, oldName.length() - extension.length()) + "-" + ss.str() + "." + extension;

        // Ensure the new file name has a unique extension for all processed files
        if (filesLock.try_lock()) {
            bool found = false;
            for (const auto& [file, id] : fileNames) {
                if (id == metadata && file.find(newName) != string::npos) {
                    found = true;
                    break;
                }
            }
            filesLock.unlock();
            if (found) {
                newName += "-" + to_string(timeStamp);
            }
        } else {
            cerr << "Error: Could not acquire lock for file name generation" << endl;
        }

        return newName;
    }

    cerr << "Error: Invalid old file name format" << endl;
    return "";
}

