```csharp
using System;
using System.Xml;
using ThirdPartyLibraryForXMLParsingAndValidation; // Replace with actual library name

namespace OAuth2AccessTokenResponseService
{
    public class Service
    {
        private readonly ThirdPartyLibraryForXMLParsingAndValidation _xmlParser;

        public Service()
        {
            _xmlParser = new ThirdPartyLibraryForXMLParsingAndValidation();
        }

        public void ProcessAccessTokenResponse(string accessTokenResponse)
        {
            try
            {
                // Parse the XML response using the third-party library
                var xmlDoc = _xmlParser.ParseXml(accessTokenResponse);

                // Validate the schema of the XML document against the predefined schema
                if (!ValidateSchema(xmlDoc))
                {
                    throw new Exception("Invalid XML schema");
                }

                // Extract the access token, expiration time, and token type from the response
                var accessToken = GetAccessToken(xmlDoc);
                var expiresIn = GetExpiresIn(xmlDoc);
                var tokenType = GetTokenType(xmlDoc);

                // Check if the access token is valid and has not expired
                if (accessToken == null || expiresIn <= 0)
                {
                    throw new Exception("Invalid access token");
                }

                // Return the extracted data
                return (accessToken, expiresIn, tokenType);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing OAuth2 access token response: {ex.Message}");
                throw;
            }
        }

        private bool ValidateSchema(XmlDocument xmlDoc)
        {
            // Check if the XML document has a valid structure according to the schema
            return xmlDoc.Validate(new XmlSchemaSet());
        }

        private string GetAccessToken(XmlDocument xmlDoc)
        {
            // Extract the access token from the XML document
            var accessTokenNode = xmlDoc.SelectSingleNode("//access_token");
            return accessTokenNode?.InnerText;
        }

        private int GetExpiresIn(XmlDocument xmlDoc)
        {
            // Extract the expiration time of the access token from the XML document
            var expiresInNode = xmlDoc.SelectSingleNode("//expires_in");
            return Convert.ToInt32(expiresInNode?.InnerText);
        }

        private string GetTokenType(XmlDocument xmlDoc)
        {
            // Extract the token type from the XML document
            var tokenTypeNode = xmlDoc.SelectSingleNode("//token_type");
            return tokenTypeNode?.InnerText;
        }
    }
}
