Here is a sample implementation of the C# console application that integrates with an external REST API to fetch a list of integers encoded in JSON format from a public endpoint, stores them in a thread-safe data structure, and determines the largest integer concurrently using multiple threads:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;

namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            // Initialize the data structure for storing the integers
            var integerList = new List<int>();

            // Set up a task for fetching the integers from the external API
            Task.Run(() => FetchIntegersAsync(integerList));

            // Set up tasks for determining the largest integer concurrently using multiple threads
            var largestIntegerTask = Task.Factory.StartNew(() => DetermineLargestIntegerAsync(integerList));

            // Wait for all tasks to complete
            Task.WaitAll(largestIntegerTask);

            Console.WriteLine("The largest integer is: {0}", largestIntegerTask.Result);
        }

        private static async Task FetchIntegersAsync(List<int> integerList)
        {
            try
            {
                // Create an HTTP client for making API calls
                var httpClient = new HttpClient();

                // Set the URL of the external API endpoint
                var url = "https://api.example.com/integers";

                // Make a GET request to the API endpoint and retrieve the response
                var response = await httpClient.GetAsync(url);

                // Check if the response was successful
                if (response.IsSuccessStatusCode)
                {
                    // Deserialize the JSON response into a list of integers
                    integerList = JsonConvert.DeserializeObject<List<int>>(await response.Content.ReadAsStringAsync());
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error fetching integers: {0}", ex.Message);
            }
        }

        private static async Task DetermineLargestIntegerAsync(List<int> integerList)
        {
            try
            {
                // Use a lock to ensure that only one thread can access the data structure at a time
                using (var @lock = new Object())
                {
                    // Initialize the largest integer variable
                    var largestInteger = int.MinValue;

                    // Iterate over the integers in the data structure and determine the largest integer concurrently
                    foreach (var integer in integerList)
                    {
                        if (integer > largestInteger)
                        {
                            lock (@lock)
                            {
                                largestInteger = integer;
                            }
                        }
                    }
                }

                // Return the largest integer from the data structure
                return Task.FromResult(largestInteger);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error determining largest integer: {0}", ex.Message);
            }
        }
    }
}
```
