Here is an example of how you could implement a modular C# library that provides robust serialization and deserialization capabilities for custom data structures:
```csharp
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using Newtonsoft.Json;
using Newtonsoft.Json.Schema;

namespace CustomDataStructureSerializer
{
    public static class Serializer
    {
        private const string BinaryFileExtension = ".bin";
        private const string JsonFileExtension = ".json";

        public static void Serialize<T>(string path, T data) where T : class
        {
            if (data == null)
                throw new ArgumentNullException(nameof(data));

            var serializer = GetSerializer(path);
            using (var stream = File.OpenWrite(path))
            {
                serializer.Serialize(stream, data);
            }
        }

        public static T Deserialize<T>(string path) where T : class
        {
            if (!File.Exists(path))
                throw new FileNotFoundException("Cannot deserialize from a non-existent file", path);

            var serializer = GetSerializer(path);
            using (var stream = File.OpenRead(path))
            {
                return serializer.Deserialize<T>(stream);
            }
        }

        private static IFormatter GetSerializer(string path)
        {
            switch (Path.GetExtension(path))
            {
                case BinaryFileExtension:
                    return new BinaryFormatter();
                case JsonFileExtension:
                    return new Newtonsoft.Json.JsonSerializer();
                default:
                    throw new NotSupportedException($"Unsupported file extension: {Path.GetExtension(path)}");
            }
        }
    }
}
```
