Here is an example of how you could implement a modular JavaScript library for managing file uploads to cloud storage services using the concepts outlined in the programming task:
```
// Import necessary libraries and dependencies
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const FormData = require('form-data');

// Define configuration object for cloud storage provider, bucket name, file path, etc.
const config = {
  provider: 'AWS S3',
  bucketName: 'my-bucket',
  filePath: 'path/to/file.txt',
  accessKeyId: 'YOUR_ACCESS_KEY_ID',
  secretAccessKey: 'YOUR_SECRET_ACCESS_KEY',
};

// Validate input parameters and ensure compliance with cloud provider requirements
function validateInput(config) {
  if (!config.provider || !config.bucketName || !config.filePath) {
    throw new Error('Invalid configuration: missing required parameters');
  }
  if (config.fileSize > config.maxFileSize) {
    throw new Error(`File size exceeds maximum allowed of ${config.maxFileSize} bytes`);
  }
  if (!config.accessKeyId || !config.secretAccessKey) {
    throw new Error('Invalid credentials: missing access key ID or secret access key');
  }
}

// Implement asynchronous file upload with support for chunked uploads to optimize for large files and improve performance over slow networks
function asyncFileUpload(filePath, config) {
  return new Promise((resolve, reject) => {
    // Validate input parameters
    validateInput(config);

    // Set up request headers and form data
    const headers = {
      'Content-Type': 'application/octet-stream',
    };
    const formData = new FormData();
    formData.append('file', fs.createReadStream(filePath));

    // Set up authentication token refresh mechanisms for long-running applications
    const authToken = getAuthToken(config);
    headers['Authorization'] = `Bearer ${authToken}`;

    // Set up retry logic with exponential backoff for transient errors
    let retriesRemaining = config.maxRetries;
    let backoffDelay = 0;
    const uploadFile = () => {
      axios({
        method: 'post',
        url: `https://${config.provider}/${config.bucketName}/${config.filePath}`,
        headers,
        data: formData,
      }).then(response => {
        retriesRemaining = 0;
        resolve(response);
      }).catch(error => {
        if (retriesRemaining > 0 && error.code === 'ETIMEDOUT') {
          retriesRemaining -= 1;
          backoffDelay += Math.min(backoffDelay * 2, config.maxBackoffDelay);
          setTimeout(() => uploadFile(), backoffDelay);
        } else {
          reject(error);
        }
      });
    };

    // Initiate file upload
    uploadFile();
  });
}

// Implement secure integration with each cloud provider's API, handling authentication via OAuth tokens or API keys and ensuring token refresh mechanisms are in place for long-running applications
function getAuthToken(config) {
  const authToken = {};
  if (config.provider === 'AWS S3') {
    // Implement AWS S3 authentication using OAuth tokens
    axios({
      method: 'post',
      url: `https://${config.provider}/oauth/token`,
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      params: {
        client_id: config.clientId,
        client_secret: config.clientSecret,
        refresh_token: authToken['refresh_token'],
        grant_type: 'client_credentials',
      }
    }).then(response => {
      authToken['access_token'] = response.data.access_token;
      authToken['expires_in'] = response.data.expires_in;
    });
  } else if (config.provider === 'Google Cloud Storage') {
    // Implement Google Cloud Storage authentication using API keys
    axios({
      method: 'post',
      url: `https://${config.provider}/v1/upload`,
      headers: {
        'Content-Type': 'application/json',
      },
      params: {
        key: config.apiKey,
      }
    }).then(response => {
      authToken['access_token'] = response.data.access_token;
      authToken['expires_in'] = response.data.expires_in;
