    public async Task<string> CreateUserAsync(string id, string name, string email, string password) {
        var request = new RestRequest($"users/{id}", Method.POST);
        request.AddJsonBody(new { id, name, email, password });

        var response = await _httpClient.ExecuteAsync(request);
        if (response.StatusCode == System.Net.HttpStatusCode.OK) {
            return "success";
        } else {
            return "error";
        }
