    public async Task<string> UpdateUserAsync(string id, string name, string email, string password, string subAction = null) {
        var request = new RestRequest($"users/{id}", Method.PUT);

        if (subAction == "update") {
            var updateBody = new { name, email, password };
            foreach (var prop in updateBody.GetType().GetProperties()) {
                if (!string.IsNullOrEmpty(prop.GetValue(updateBody)?.ToString())) {
                    request.AddParameter(prop.Name, prop.GetValue(updateBody));
                }
            }
        } else if (subAction == "delete") {
            var deleteBody = new { name, email, password };
            foreach (var prop in deleteBody.GetType().GetProperties()) {
                if (!string.IsNullOrEmpty(prop.GetValue(deleteBody)?.ToString())) {
                    request.AddParameter(prop.Name, prop.GetValue(deleteBody));
                }
            }
        } else {
            throw new ArgumentException("Invalid subAction", nameof(subAction));
        }

        var response = await _httpClient.ExecuteAsync(request);
        if (response.StatusCode == System.Net.HttpStatusCode.OK) {
            return "success";
        } else {
            return "error";
        }
    }

