Here is an example implementation for the modular, extensible encryption service in C:
```c
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define algorithm selection strategy based on configuration and environment
enum AlgorithmSelectionStrategy {
    AES = 0,
    RSA = 1,
    ECC = 2
};

// Define encryption parameters for each supported algorithm
struct EncryptionParameters {
    int keySize;
    unsigned char *iv;
    EVP_CIPHER_CTX ctx;
};

// Initialize encryption parameters based on selected strategy
void initializeEncryptionParameters(enum AlgorithmSelectionStrategy strategy, struct EncryptionParameters *parameters) {
    switch (strategy) {
        case AES:
            parameters->keySize = 256;
            parameters->iv = NULL; // Use default IV for AES
            break;
        case RSA:
            parameters->keySize = 2048;
            parameters->iv = NULL; // No IV required for RSA
            break;
        case ECC:
            parameters->keySize = 384;
            parameters->iv = NULL; // No IV required for ECC
            break;
    }
}

// Select algorithm based on configuration and environment
enum AlgorithmSelectionStrategy selectAlgorithm(struct Configuration *configuration, struct Environment *environment) {
    // Check if AES is supported and configured for use
    if (configuration->useAes && !isAesSupported()) {
        return RSA;
    }
    // Check if RSA is supported and configured for use
    if (configuration->useRsa && !isRsaSupported()) {
        return ECC;
    }
    // Check if ECC is supported and configured for use
    if (configuration->useEcc && !isEccSupported()) {
        return AES;
    }
    // Default to AES if no supported algorithms are found
    return AES;
}

// Initialize encryption context based on selected algorithm
void initializeEncryptionContext(enum AlgorithmSelectionStrategy strategy, struct EncryptionParameters *parameters) {
    switch (strategy) {
        case AES:
            EVP_CIPHER_CTX_init(&parameters->ctx);
            EVP_EncryptInit_ex(&parameters->ctx, EVP_aes_256_cbc(), NULL, parameters->key, parameters->iv);
            break;
        case RSA:
            // Initialize RSA encryption context here
            break;
        case ECC:
            // Initialize ECC encryption context here
            break;
    }
}

// Encrypt data using selected algorithm and return encrypted data
unsigned char *encrypt(enum AlgorithmSelectionStrategy strategy, struct EncryptionParameters *parameters, unsigned char *data) {
    initializeEncryptionContext(strategy, parameters);
    EVP_EncryptUpdate(&parameters->ctx, data, 1024);
    EVP_EncryptFinal_ex(&parameters->ctx, NULL, NULL);
    return parameters->encryptedData;
}

// Decrypt data using selected algorithm and return decrypted data
unsigned char *decrypt(enum AlgorithmSelectionStrategy strategy, struct EncryptionParameters *parameters, unsigned char *data) {
    initializeEncryptionContext(strategy, parameters);
    EVP_DecryptUpdate(&parameters->ctx, data, 1024);
    EVP_DecryptFinal_ex(&parameters->ctx, NULL, NULL);
    return parameters->decryptedData;
}

// Handle memory allocation failures gracefully
void handleMemoryAllocationFailure(struct EncryptionParameters *parameters) {
    // Log error message and abort program execution
    fprintf(stderr, "Memory allocation failure: %s\n", strerror(errno));
    exit(1);
}

// Handle invalid inputs gracefully
void handleInvalidInputs(struct EncryptionParameters *parameters) {
    // Log error message and abort program execution
    fprintf(stderr, "Invalid input detected: %s\n", strerror(errno));
    exit(1);
}

// Handle OpenSSL errors gracefully
void handleOpenSslErrors(struct EncryptionParameters *parameters) {
    // Log error message and abort program execution
    fprintf(stderr, "OpenSSL error: %s\n", ERR_error_string(ERR_get_error(), NULL));
    exit(1);
}

// Main function to handle encryption/decryption operations
int main() {
    struct Configuration configuration;
    struct Environment environment;
    enum AlgorithmSelectionStrategy strategy = selectAlgorithm(&configuration, &environment);
    struct EncryptionParameters parameters;
    initializeEncryptionParameters(strategy, &parameters);

    // Handle memory allocation failures gracefully
    if (!EVP_CIPHER_CTX_init(&parameters.ctx)) {
        handleMemoryAllocationFailure(&parameters);
    }

    // Encrypt data using selected algorithm
    unsigned char *encryptedData = encrypt(strategy, &parameters, "Hello World!");
    printf("Encrypted data: %s\n", encryptedData);

    // Decrypt data using selected algorithm
    unsigned char *decryptedData = decrypt(strategy, &parameters, encryptedData);
    printf("Decrypted data: %s\n", decryptedData);

    // Handle invalid inputs gracefully
    if (!EVP_EncryptInit_ex(&parameters.ctx, EVP_aes_256_cbc(), NULL, parameters.key, parameters.iv)) {
        handleInvalidInputs(&parameters);
    }

    // Handle OpenSSL errors gracefully
    ERR_load_crypto_strings();
    if (ERR_get_error()) {
        handleOpenSslErrors(&parameters);
    }

    return 0;
}
```

In this example, we are using the OpenSSL library to perform encryption and decryption operations. We first define a `struct Configuration` that contains the configuration options for the program, such as whether AES, RSA, or ECC should be used. Then, we define a `struct Environment` that contains information about the current environment, such as the operating system and CPU architecture.

Next, we define an `enum AlgorithmSelectionStrategy` that determines which algorithm to use based on the configuration options and environment. We then define a `struct EncryptionParameters` that contains all the parameters required for encryption and decryption operations.

In the `main()` function, we first select the algorithm using the `selectAlgorithm()` function, which takes the `struct Configuration` and `struct Environment` as input and returns an `enum AlgorithmSelectionStrategy`. We then initialize the encryption context using the `initializeEncryptionContext()` function, which takes the selected strategy and parameters as input.

Next, we handle memory allocation failures gracefully by using the `handleMemoryAllocationFailure()` function, which logs an error message and aborts the program execution. We also handle invalid inputs gracefully by using the `handleInvalidInputs()` function, which logs an error message and aborts the program execution. Finally, we handle OpenSSL errors gracefully by using the `handleOpenSslErrors()` function, which logs an error message and aborts the program execution.

In summary, this example demonstrates how to use OpenSSL library to perform encryption and decryption operations in a more secure way, by handling memory allocation failures and invalid inputs gracefully.']

