const traverseDOM = (rootElement) => {
  const metadataCache = new Map();
  const fetchMetadata = async (element) => {
    // Check if the element has already been cached
    if (metadataCache.has(element)) {
      return metadataCache.get(element);
    }

    // Fetch metadata for the element asynchronously and cache it
    try {
      const response = await fetch(`https://example.com/api/metadata?id=${element.id}`);
      const data = await response.json();
      metadataCache.set(element, data);
      return data;
    } catch (error) {
      // Handle network failures and potential malformed responses gracefully
      console.error(`Failed to fetch metadata for element ${element.id}:`, error);
    }
  };

  const traverse = async (element, depth = 0) => {
    // Check if the element matches our selector
    if (matchSelector(element)) {
      await fetchMetadata(element);
    }

    // Recursively traverse child elements
    for (let i = 0; i < element.children.length; i++) {
      const childElement = element.children[i];
      await traverse(childElement, depth + 1);
    }
  };

  // Start traversing the DOM tree from the root element
  return traverse(rootElement);
};
```
