            using Payload = std::vector<unsigned char>;
            enum class Method { GET, POST };
            struct Response {
                int statusCode;
                std::string body;
            };

            // Concurrency management
            struct Worker {
                std::thread thread;
                std::mutex mutex;
                std::condition_variable cv;
                bool running = true;
            };
            using ThreadPool = std::vector<Worker>;

            // Caching strategy
            enum class CachePolicy { NONE, LRU, FIFO };
            struct CacheEntry {
                Method method;
                Payload payload;
                Response response;
            };
            struct Cache {
                std::map<std::string, CacheEntry> entries;
                CachePolicy policy = CachePolicy::NONE;
                int maxSize = 0;
            };

            // Resource management
            using Socket = std::unique_ptr<struct sockaddr, void(*)(void*)>;
            using MemAllocator = std::function<void*(size_t)>;

            // Retry logic
            struct Retry {
                int maxAttempts = 0;
                int delayInterval = 0;
            };

            // Error handling
            enum class ErrorType { NONE, TIMEOUT, SERVER, CLIENT };
            struct Error {
                ErrorType type;
                std::string message;
            };

