#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <pthread.h>
#include <semaphore.h>

#define NUM_THREADS 8
#define THRESHOLD 0.5

// Graph data structure
typedef struct {
    int id;
    double* values;
} vertex;

// Thread-safe queue for storing vertices
typedef struct {
    vertex* vertices;
    int size;
    sem_t mutex;
} queue;

// Initialize queue with given capacity
queue* init_queue(int capacity) {
    queue* q = (queue*) malloc(sizeof(queue));
    q->vertices = (vertex*) malloc(capacity * sizeof(vertex));
    q->size = 0;
    sem_init(&q->mutex, 0, 1);
    return q;
}

// Add vertex to queue
void add_vertex(queue* q, vertex v) {
    sem_wait(&q->mutex);
    if (q->size == q->capacity) {
        // Resize the queue if it's full
        int new_capacity = q->capacity * 2;
        vertex* new_vertices = (vertex*) malloc(new_capacity * sizeof(vertex));
        memcpy(new_vertices, q->vertices, q->size * sizeof(vertex));
        free(q->vertices);
        q->vertices = new_vertices;
        q->capacity = new_capacity;
    }
    q->vertices[q->size] = v;
    q->size++;
    sem_post(&q->mutex);
}

// Remove vertex from queue
vertex* remove_vertex(queue* q) {
    sem_wait(&q->mutex);
    if (q->size == 0) {
        // Return null if the queue is empty
        return NULL;
    }
    vertex v = q->vertices[--q->size];
    sem_post(&q->mutex);
    return &v;
}

// Destroy queue
void destroy_queue(queue* q) {
    free(q->vertices);
    sem_destroy(&q->mutex);
    free(q);
}

// Thread-safe hash map for storing vertex ids and their corresponding positions in the graph
typedef struct {
    int size;
    int* keys;
    int* values;
    sem_t mutex;
} hashmap;

// Initialize hashmap with given capacity
hashmap* init_hashmap(int capacity) {
    hashmap* h = (hashmap*) malloc(sizeof(hashmap));
    h->keys = (int*) malloc(capacity * sizeof(int));
    h->values = (int*) malloc(capacity * sizeof(int));
    h->size = 0;
    sem_init(&h->mutex, 0, 1);
    return h;
}

// Add key-value pair to hashmap
void add_key_value(hashmap* h, int key, int value) {
    sem_wait(&h->mutex);
    if (h->size == h->capacity) {
        // Resize the hashmap if it's full
        int new_capacity = h->capacity * 2;
        int* new_keys = (int*) malloc(new_capacity * sizeof(int));
        int* new_values = (int*) malloc(new_capacity * sizeof(int));
        memcpy(new_keys, h->keys, h->size * sizeof(int));
        memcpy(new_values, h->values, h->size * sizeof(int));
        free(h->keys);
        free(h->values);
        h->keys = new_keys;
        h->values = new_values;
        h->capacity = new_capacity;
    }
    h->keys[h->size] = key;
    h->values[h->size] = value;
    h->size++;
    sem_post(&h->mutex);
}

// Get value for given key from hashmap
int get_value(hashmap* h, int key) {
    sem_wait(&h->mutex);
    int i = 0;
    while (i < h->size && h->keys[i] != key) {
        i++;
    }
    if (i == h->size) {
        // Return -1 if the key is not found in the hashmap
        return -1;
    }
    int value = h->values[i];
    sem_post(&h->mutex);
    return value;
}

// Destroy hashmap
void destroy_hashmap(hashmap* h) {
    free(h->keys);
    free(h->values);
    sem_destroy(&h->mutex);
    free(h);
}

// Function for processing vertices in a batch
void process_vertices(queue* q, hashmap* h) {
    while (q->size > 0) {
        vertex* v = remove_vertex(q);
        int id = v->id;
        if (get_value(h, id) != -1) {
            // Skip already processed vertices
            continue;
        }
        add_key_value(h, id, q->size);
        double* values = v->values;
        int num_fields = v->num_fields;
        double avg = 0.0;
        for (int i = num_fields - 2; i >= 0; i--) {
            avg += values[i];
        }
        if (num_fields > 1) {
            avg /= (double) (num_fields - 1);
        } else {
            // Use the last value as the average for a single field vertex
            avg = values[0];
        }
        values[num_fields] = avg;
    }
}

// Function for processing a batch of vertices
void process_batch(queue* q) {
    // Create hashmap for storing vertex ids and their corresponding positions in the graph
    int capacity = 1024;
    hashmap* h = init_hashmap(capacity);
    while (q->size > 0) {
        // Process vertices in batches of size <= 1024
        process_vertices(q, h);
        destroy_hashmap(h);
        h = init_hashmap(capacity);
    }
    destroy_hashmap(h);
}

// Function for processing a single vertex
void process_vertex(int id, double* values) {
    // Create queue for storing vertices to be processed in batches
    int capacity = 1024;
    queue* q = init_queue(capacity);
    add_vertex(q, id, values);
    process_batch(q);
    destroy_queue(q);
}

int main() {
    // Example usage of the functions for processing a single vertex and a batch of vertices
    double* values = (double*) malloc(10 * sizeof(double));
    for (int i = 0; i < 10; i++) {
        values[i] = i + 1;
    }
    process_vertex(1, values);
    free(values);
    return 0;
}
```

Note that the above code is a simplified version of the real-world system we are trying to model. It assumes that all vertices in the graph have a finite number of fields and that each vertex has at least one field. Also, the `process_batch` function assumes that the hashmap will not overflow with new keys and values being added for every batch of vertices processed. In a real-world system, these assumptions may not hold true, and more robust data structures and algorithms would need to be used."]

