#include <openssl/rsa.h>
#include <openssl/ecc.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

#define MAX_KEY_SIZE 128
#define MAX_IV_SIZE 16

typedef enum {
    AES,
    RSA,
    ECC
} algorithm_t;

typedef struct {
    unsigned char key[MAX_KEY_SIZE];
    size_t key_len;
    unsigned char iv[MAX_IV_SIZE];
    size_t iv_len;
} encryption_context_t;

encryption_context_t *create_context(algorithm_t alg) {
    switch (alg) {
        case AES:
            return create_aes_context();
        case RSA:
            return create_rsa_context();
        case ECC:
            return create_ecc_context();
        default:
            return NULL;
    }
}

encryption_context_t *create_aes_context() {
    encryption_context_t *ctx = malloc(sizeof(encryption_context_t));
    if (!ctx) {
        return NULL;
    }

    // Generate a random AES key and IV using OpenSSL's RAND_bytes function
    RAND_bytes(ctx->key, MAX_KEY_SIZE);
    ctx->key_len = MAX_KEY_SIZE;
    RAND_bytes(ctx->iv, MAX_IV_SIZE);
    ctx->iv_len = MAX_IV_SIZE;

    return ctx;
}

encryption_context_t *create_rsa_context() {
    encryption_context_t *ctx = malloc(sizeof(encryption_context_t));
    if (!ctx) {
        return NULL;
    }

    // Generate a random RSA key using OpenSSL's RSA_generate_key function
    ctx->key = RSA_generate_key(MAX_KEY_SIZE, 65537, NULL, NULL);
    if (!ctx->key) {
        free(ctx);
        return NULL;
    }

    // Generate a random IV using OpenSSL's RAND_bytes function
    RAND_bytes(ctx->iv, MAX_IV_SIZE);
    ctx->iv_len = MAX_IV_SIZE;

    return ctx;
}

encryption_context_t *create_ecc_context() {
    encryption_context_t *ctx = malloc(sizeof(encryption_context_t));
    if (!ctx) {
        return NULL;
    }

    // Generate a random ECC key using OpenSSL's EC_KEY_new_by_curve_name function
    ctx->key = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
    if (!ctx->key) {
        free(ctx);
        return NULL;
    }

    // Generate a random IV using OpenSSL's RAND_bytes function
    RAND_bytes(ctx->iv, MAX_IV_SIZE);
    ctx->iv_len = MAX_IV_SIZE;

    return ctx;
}

int encrypt(encryption_context_t *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext) {
    switch (ctx->alg) {
        case AES:
            return encrypt_aes(ctx, plaintext, plaintext_len, ciphertext);
        case RSA:
            return encrypt_rsa(ctx, plaintext, plaintext_len, ciphertext);
        case ECC:
            return encrypt_ecc(ctx, plaintext, plaintext_len, ciphertext);
        default:
            return -1;
    }
}

int decrypt(encryption_context_t *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext) {
    switch (ctx->alg) {
        case AES:
            return decrypt_aes(ctx, ciphertext, ciphertext_len, plaintext);
        case RSA:
            return decrypt_rsa(ctx, ciphertext, ciphertext_len, plaintext);
        case ECC:
            return decrypt_ecc(ctx, ciphertext, ciphertext_len, plaintext);
        default:
            return -1;
    }
}

int encrypt_aes(encryption_context_t *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext) {
    // Create an EVP_CIPHER_CTX structure to hold the encryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Initialize the encryption operation using AES-GCM with a random key and IV
    if (!EVP_EncryptInit(ctx, EVP_aes_256_gcm(), NULL, NULL)) {
        return -1;
    }

    // Set the encryption key and IV
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, MAX_IV_SIZE, NULL) ||
            !EVP_EncryptInit(ctx, NULL, ctx->key, ctx->iv)) {
        return -1;
    }

    // Encrypt the plaintext data using AES-GCM
    int len = 0;
    if (!EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len) ||
            !EVP_EncryptFinal(ctx, *ciphertext + len, &len)) {
        return -1;
    }

    // Set the length of the ciphertext
    *ciphertext += len;

    return 0;
}

int decrypt_aes(encryption_context_t *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext) {
    // Create an EVP_CIPHER_CTX structure to hold the decryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Initialize the decryption operation using AES-GCM with a random key and IV
    if (!EVP_DecryptInit(ctx, EVP_aes_256_gcm(), NULL, NULL) ||
            !EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, MAX_IV_SIZE, NULL)) {
        return -1;
    }

    // Set the decryption key and IV
    if (!EVP_DecryptInit(ctx, NULL, ctx->key, ctx->iv)) {
        return -1;
    }

    // Decrypt the ciphertext using AES-GCM
    int len = 0;
    if (!EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len) ||
            !EVP_DecryptFinal(ctx, *plaintext + len, &len)) {
        return -1;
    }

    // Set the length of the plaintext
    *plaintext += len;

    return 0;
}

int encrypt_rsa(encryption_context_t *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext) {
    // Create an RSA structure to hold the encryption context
    RSA *rsa = RSA_new();

    // Set the encryption key and IV
    if (!RSA_set_key(rsa, ctx->key, NULL)) {
        return -1;
    }

    // Encrypt the plaintext using RSA-OAEP
    int len = 0;
    if (!RSA_encrypt(rsa, &len, *ciphertext, plaintext, plaintext_len, RSA_PKCS1_OAEP_PADDING)) {
        return -1;
    }

    // Set the length of the ciphertext
    *ciphertext += len;

    return 0;
}

int decrypt_rsa(encryption_context_t *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext) {
    // Create an RSA structure to hold the decryption context
    RSA *rsa = RSA_new();

    // Set the decryption key and IV
    if (!RSA_set_key(rsa, ctx->key, NULL)) {
        return -1;
    }

    // Decrypt the ciphertext using RSA-OAEP
    int len = 0;
    if (!RSA_decrypt(rsa, &len, *plaintext, ciphertext, ciphertext_len, RSA_PKCS1_OAEP_PADDING)) {
        return -1;
    }

    // Set the length of the plaintext
    *plaintext += len;

    return 0;
}

int encrypt_ecc(encryption_context_t *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext) {
    // Create an EC_KEY structure to hold the encryption context
    EC_KEY *ec = EC_KEY_new();

    // Set the encryption key and IV
    if (!EC_KEY_set_key(ec, ctx->key, NULL)) {
        return -1;
    }

    // Encrypt the plaintext using ECIES-CTR
    int len = 0;
    if (!ECIES_encrypt(ec, &len, *ciphertext, plaintext, plaintext_len, RSA_PKCS1_OAEP_PADDING)) {
        return -1;
    }

    // Set the length of the ciphertext
    *ciphertext += len;

    return 0;
}

int decrypt_ecc(encryption_context_t *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext) {
    // Create an EC_KEY structure to hold the decryption context
    EC_KEY *ec = EC_KEY_new();

    // Set the decryption key and IV
    if (!EC_KEY_set_key(ec, ctx->key, NULL)) {
        return -1;
    }

    // Decrypt the ciphertext using ECIES-CTR
    int len = 0;
    if (!ECIES_decrypt(ec, &len, *plaintext, ciphertext, ciphertext_len, RSA_PKCS1_OAEP_PADDING)) {
        return -1;
    }

    // Set the length of the plaintext
    *plaintext += len;

    return 0;
}
```
This code defines a simple encryption library that can be used to encrypt and decrypt data using different cryptographic algorithms. The `encryption_context_t` struct is defined as follows:
```c
typedef struct {
    int algorithm; // the encryption algorithm to use (0 = AES-GCM, 1 = RSA-OAEP, 2 = ECIES-CTR)
    char *key; // the encryption key
    char *iv; // the initialization vector
} encryption_context_t;
```
The `encrypt` function takes an array of bytes as input and returns an encrypted version of that data. The `decrypt` function does the opposite, taking an encrypted byte array as input and returning a decrypted version of it. Both functions use the encryption context defined above to perform the actual encryption/decryption process.

The code also defines a few helper functions for generating random keys and initialization vectors:
```c
#define KEY_SIZE 32 // size in bytes of an AES key
#define IV_SIZE 16 // size in bytes of an AES initialization vector

// generate a random encryption key
char *generate_key() {
    char *key = malloc(KEY_SIZE);
    if (!key) {
        return NULL;
    }
    for (int i = 0; i < KEY_SIZE; i++) {
        key[i] = rand() & 0xff;
    }
    return key;
}

// generate a random initialization vector
char *generate_iv() {
    char *iv = malloc(IV_SIZE);
    if (!iv) {
        return NULL;
    }
    for (int i = 0; i < IV_SIZE; i++) {
        iv[i] = rand() & 0xff;
    }
    return iv;
}
```
To use this encryption library, you first need to create an encryption context and generate a random key and initialization vector. You can then use the `encrypt` function to encrypt data and the `decrypt` function to decrypt it.

Here is an example of how you could use the encryption library:
```c
int main() {
    // create an encryption context
    encryption_context_t *ctx = malloc(sizeof(encryption_context_t));
    ctx->algorithm = 0; // AES-GCM
    ctx->key = generate_key();
    ctx->iv = generate_iv();

    // encrypt some data
    char *data = "Hello, world!";
    int len = strlen(data);
    char *encrypted = malloc(len + 16);
    if (encrypt(ctx, encrypted, data, len) < 0) {
        printf("Error encrypting data\n");
        return 1;
    }

    // decrypt the encrypted data
    char *decrypted = malloc(len + 16);
    if (decrypt(ctx, decrypted, encrypted, len) < 0) {
        printf("Error decrypting data\n");
        return 1;
    }

    // print the original and decrypted data
    printf("Original: %s\n", data);
    printf("Decrypted: %s\n", decrypted);

    // clean up
    free(ctx->key);
    free(ctx->iv);
    free(encrypted);
    free(decrypted);
    return 0;
}
