        for (int j = i + 1; j < graph->num_vertices; j++) {
            vertex_t *vertex_j = &graph->vertices[j];
            double distance = sqrt((vertex_i->x - vertex_j->x) * (vertex_i->x - vertex_j->x) + (vertex_i->y - vertex_j->y) * (vertex_i->y - vertex_j->y));
