} aes_key_t;

typedef struct {
    unsigned char modulus[RSA_KEY_SIZE];
    unsigned char public_exponent[3];
} rsa_key_t;

typedef struct {
    unsigned char prime1[ECC_KEY_SIZE / 2];
    unsigned char prime2[ECC_KEY_SIZE / 2];
    unsigned char coeff[ECC_KEY_SIZE / 2];
} ecc_key_t;

typedef enum {
    AES,
    RSA,
    ECC
} algorithm_type_t;

algorithm_type_t selected_algorithm = AES;

void init_algorithm() {
    switch (selected_algorithm) {
        case AES:
            EVP_EncryptInit();
            break;
        case RSA:
            RSA_EncryptInit();
            break;
        case ECC:
            ECC_EncryptInit();
            break;
    }
}

void encrypt(const unsigned char* plaintext, size_t plaintext_len) {
    switch (selected_algorithm) {
        case AES:
            AES_Encrypt(plaintext, plaintext_len);
            break;
        case RSA:
            RSA_Encrypt(plaintext, plaintext_len);
            break;
        case ECC:
            ECC_Encrypt(plaintext, plaintext_len);
            break;
    }
}

void decrypt(const unsigned char* ciphertext, size_t ciphertext_len) {
    switch (selected_algorithm) {
        case AES:
            AES_Decrypt(ciphertext, ciphertext_len);
            break;
        case RSA:
            RSA_Decrypt(ciphertext, ciphertext_len);
            break;
        case ECC:
            ECC_Decrypt(ciphertext, ciphertext_len);
