  constructor(sessionId, userId) {
    this.sessionId = sessionId;
    this.userId = userId;
    this.creationTime = Date.now();
    this.lastAccessed = Date.now();
  }

  setUserId(userId) {
    this.userId = userId;
  }

  getUserId() {
