// Define a message consumer for consuming messages from the queue
const sessionEventConsumer = new MessageConsumer(sessionEventQueue);

// Handle incoming messages from the queue
sessionEventConsumer.on('message', (message) => {
  const event = JSON.parse(message.content.toString());
  switch (event.type) {
