// Measures the time and resource usage of compiling a Rust program
fn measure_compile_time<F>(f: F) -> (u64, u64) where F: FnOnce() {
    let start = Instant::now();
    f();
    let end = Instant::now();

    return (end.duration_since(start).as_secs(), 0);
}

// Measures the time and resource usage of running a Rust function using the `SyncLazy` module and error handling with `rustc_driver::catch_with_exit_code`
fn measure_synclazy_compile_time<F>(f: F) -> (u64, u64) where F: FnOnce() {
    let start = Instant::now();
    let result = catch_with_exit_code(|| f());
    let end = Instant::now();

    return (end.duration_since(start).as_secs(), result.unwrap().1);
}
