  const userId = req.params.id;
  const user = await User.findById(userId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  return res.json(user);
});

@app.post('/users', @auth, async (req, res) => {
  const user = new User(req.body);
  try {
    await user.save();
    return res.status(201).json({ message: 'User created successfully' });
  } catch (error) {
    return res.status(400).json({ error: 'Error creating user' });
  }
});

@app.put('/users/:id', @auth, async (req, res) => {
  const userId = req.params.id;
  const updatedUser = new User(req.body);
  try {
    await User.findByIdAndUpdate(userId, updatedUser, { new: true });
    return res.json({ message: 'User updated successfully' });
  } catch (error) {
    return res.status(400).json({ error: 'Error updating user' });
  }
});

@app.delete('/users/:id', @auth, async (req, res) => {
  const userId = req.params.id;
  try {
    await User.findByIdAndRemove(userId);
    return res.json({ message: 'User deleted successfully' });
  } catch (error) {
    return res.status(400).json({ error: 'Error deleting user' });
  }
});

// Role-Based Permissions Middleware
@role = new RoleMiddleware();

@app.get('/users/:id/posts', @auth, @role(['admin']), async (req, res) => {
  const userId = req.params.id;
  const posts = await Post.find({ author: userId });
  return res.json(posts);
});

@app.get('/users/:id/followers', @auth, @role(['admin']), async (req, res) => {
  const userId = req.params.id;
  const followers = await Follower.find({ user: userId });
  return res.json(followers);
});
