using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace MiddlewareComponent
{
    public class DynamicContentMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger<DynamicContentMiddleware> _logger;
        private readonly IDynamicContentService _dynamicContentService;
        private readonly ICdnService _cdnService;

        public DynamicContentMiddleware(RequestDelegate next, ILogger<DynamicContentMiddleware> logger, IDynamicContentService dynamicContentService, ICdnService cdnService)
        {
            _next = next;
            _logger = logger;
            _dynamicContentService = dynamicContentService;
            _cdnService = cdnService;
        }

        public async Task Invoke(HttpContext httpContext)
        {
            var requestPath = httpContext.Request.Path.Value;
            if (IsDynamicContentPath(requestPath))
            {
                try
                {
                    var pageConfig = await _dynamicContentService.GetPageConfiguration(requestPath);
                    var elementMetadata = await _cdnService.GetElementMetadata(pageConfig.Elements);
                    var updatedContent = UpdateDynamicContent(httpContext.Request.Form, elementMetadata);
                    await _cdnService.UpdateElementMetadata(updatedContent);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to update dynamic content");
                }
            }

            await _next(httpContext);
        }

        private bool IsDynamicContentPath(string requestPath)
        {
            return requestPath.StartsWith("/dynamic-content", StringComparison.OrdinalIgnoreCase);
        }

        private Dictionary<string, string> UpdateDynamicContent(IFormCollection formData, IDictionary<string, ElementMetadata> elementMetadata)
        {
            var updatedContent = new Dictionary<string, string>();
            foreach (var element in elementMetadata)
            {
                if (formData.ContainsKey(element.Key))
                {
                    updatedContent[element.Key] = formData[element.Key];
                }
            }
            return updatedContent;
        }
    }
}
