// FileUploadService.java
```java
public class FileUploadService {
    private static final Logger logger = LoggerFactory.getLogger(FileUploadService.class);

    private final Map<String, CloudStorageProvider> providers; // map of provider names to instances
    private final ExecutorService executor; // thread pool for asynchronous processing
    private final AtomicInteger concurrentUploads; // number of concurrent uploads

    public FileUploadService(List<CloudStorageProvider> providers) {
        this.providers = new ConcurrentHashMap<>();
        providers.forEach(p -> this.providers.put(p.getName(), p));
        this.executor = Executors.newCachedThreadPool();
        this.concurrentUploads = new AtomicInteger();
    }

    public void uploadFile(String fileName, InputStream inputStream) {
        CloudStorageProvider provider = providers.get(fileName);
        if (provider == null) {
            throw new IllegalArgumentException("No such file: " + fileName);
        }

        executor.submit(() -> {
            int uploadId = concurrentUploads.incrementAndGet();
            logger.info("Starting upload #{} for {}", uploadId, fileName);

            try (InputStream inputStream = new BufferedInputStream(inputStream)) {
                // upload file to provider
                long startTime = System.currentTimeMillis();
                boolean success = provider.uploadFile(fileName, inputStream);
                if (!success) {
                    logger.error("Failed to upload {}", fileName);
                } else {
                    logger.info("Uploaded {} in {} ms", fileName, System.currentTimeMillis() - startTime);
                }
            } catch (IOException e) {
                logger.warn("Error while uploading {}", fileName, e);
            } finally {
                concurrentUploads.decrementAndGet();
                logger.info("Ending upload #{} for {}", uploadId, fileName);
            }
        });
    }

    public void cancelUpload(String fileName) {
        CloudStorageProvider provider = providers.get(fileName);
        if (provider == null) {
            throw new IllegalArgumentException("No such file: " + fileName);
        }

        // TODO: implement cancellation mechanism for uploads in progress
    }
}
