public class AWSCloudStorageProvider implements CloudStorageProvider {
    private final AmazonS3 s3Client;
    private final String bucketName;

    public AWSCloudStorageProvider(AmazonS3 s3Client, String bucketName) {
        this.s3Client = s3Client;
        this.bucketName = bucketName;
    }

    @Override
    public boolean uploadFile(String fileName, InputStream inputStream) throws IOException {
        PutObjectRequest request = new PutObjectRequest(bucketName, fileName, inputStream, null);
        return s3Client.putObject(request).isSuccessful();
    }
}
