public class GoogleCloudStorageProvider implements CloudStorageProvider {
    private final Storage storage;
    private final String bucketName;

    public GoogleCloudStorageProvider(Storage storage, String bucketName) {
        this.storage = storage;
        this.bucketName = bucketName;
    }

    @Override
    public boolean uploadFile(String fileName, InputStream inputStream) throws IOException {
        Blob blob = storage.create(BlobInfo.newBuilder(bucketName, fileName).build(), inputStream);
        return blob != null && blob.exists();
    }
}
