                print("Token expired!")
                self.refresh_token(source)
                continue
            elif response.status_code != 200:
                print(f"Error retrieving data from {source}: {response.text}")
                return None

            # Parse and process the retrieved data
            data = response.json()
            self.process_data(data)

    def refresh_token(self, source: str):
        # Send request to retrieve new token from the specified source
        response = requests.post(f"{source}/oauth/token", headers={"Authorization": f"Bearer {self.auth_tokens[source]['refresh_token']}"})

        if response.status_code == 200:
            self.auth_tokens[source] = {"access_token": response.json()["access_token"], "refresh_token": response.json()["refresh_token"]}
