import smtplib
from email.mime.text import MIMEText
from typing import List, Dict

class NotificationHandler:
    def __init__(self, notification_channels: List[str]):
        self.notification_channels = notification_channels

    def send_notifications(self, notifications: List[Dict[str, str]]):
        for channel in self.notification_channels:
            if channel == "email":
                # Send email notifications using SMTP
                server = smtplib.SMTP("smtp.gmail.com", 587)
                server.starttls()
                server.login(self.notification_channels[channel]['username'], self.notification_channels[channel]['password'])

                for notification in notifications:
                    subject = "Notification from the Cloud Infrastructure Management Platform"
                    body = f"""
                        {notification['message']}

                        Please take appropriate action to address this issue.
                        """

                    msg = MIMEText(body)
                    msg["Subject"] = subject
                    msg["From"] = self.notification_channels[channel]['username']
                    msg["To"] = notification['recipient']

                    server.sendmail(self.notification_channels[channel]['username'], [notification['recipient']], msg.as_string())

            elif channel == "sms":
                # Send SMS notifications using an SMS gateway service
                from twilio.rest import Client

                account_sid = self.notification_channels[channel]['account_sid']
                auth_token = self.notification_channels[channel]['auth_token']

                client = Client(account_sid, auth_token)

                for notification in notifications:
                    message = client.messages.create(
                        body=f"Notification from the Cloud Infrastructure Management Platform: {notification['message']}",
                        from_="+1234567890",
                        to=notification['recipient'],
                        media_url=notification['media_url']
                    )

            elif channel == "webhook":
                # Send webhook notifications using a custom service
                import requests

                url = self.notification_channels[channel]['url']

                for notification in notifications:
                    headers = {"Content-Type": "application/json"}
                    data = {"message": notification["message"]}

                    response = requests.post(url, json=data, headers=headers)

