// Octree.h
#ifndef OCTREE_H
#define OCTREE_H

#include <cstdint>
#include <memory>
#include <vector>

class Octree {
 public:
  // Constructor and destructor
  Octree();
  ~Octree();

  // Add a new point to the octree
  void addPoint(const std::vector<double>& point);

  // Remove a point from the octree
  void removePoint(const std::vector<double>& point);

  // Query the octree for points within a given radius of a given point
  std::vector<std::vector<double>> queryRadius(const std::vector<double>& center, double radius) const;

  // Serialize the octree to a file
  void serialize(const std::string& filename) const;

  // Deserialize the octree from a file
  static Octree deserialize(const std::string& filename);

 private:
  struct Node {
    // The node's position in the octree
    std::vector<double> position_;

    // The node's bounding box
    BoundingBox boundingBox_;

    // The node's points
    std::vector<std::vector<double>> points_;

    // The node's children nodes
    std::unique_ptr<Node[]> children_;
  };

  // The root node of the octree
  std::unique_ptr<Node> root_;
};

#endif // OCTREE_H
