            processingReport.push_back(e.what());
            this_thread::sleep_for(chrono::seconds(pow(2, retryCount))); // exponential backoff with jitter
        }
    }

    // Implement rate-limiting for requests to the third-party service using a token bucket algorithm
    double tokens = min(TOKEN_BUCKET_SIZE, BURST_CAPACITY);
    while (tokens < TOKEN_BUCKET_SIZE) {
        this_thread::sleep_for(chrono::seconds(1)); // refill rate
        tokens += REFILL_RATE;
    }

    // Implement caching for transaction metadata using a distributed cache system
    unordered_map<string, Transaction> cache;
    int cacheInvalidations = 0;
    for (const string& transaction : transactions) {
        auto it = cache.find(transaction);
        if (it != cache.end()) {
            // Cache hit: use the cached object and update the cache entry
