    // Process the transactions in a thread-safe manner using a producer-consumer pattern with a bounded buffer
    queue<Transaction> transactionQueue;
    mutex transactionMutex;
    condition_variable transactionCondition;
    future<void> processorFuture;
    for (const string& transaction : transactions) {
        // Enqueue the transaction and notify the processor thread if it is waiting
        transactionQueue.push(deserializedTransaction);
        transactionCondition.notify_all();

        // Process the transaction in a separate thread to avoid blocking the main thread
        if (!processorFuture.valid()) {
            processorFuture = async([&]() {
                while (true) {
                    Transaction currentTransaction;
                    bool exit = false;
                    {
                        lock_guard<mutex> lock(transactionMutex);
                        if (!transactionQueue.empty()) {
                            currentTransaction = transactionQueue.front();
                            transactionQueue.pop();
                        } else {
