        if (it != cache.end()) {
            // Cache hit: use the cached object and update the cache entry
            cache[transaction.id] = transaction;
        } else {
            // Cache miss: insert the transaction into the cache
            cache.insert({ transaction.id, transaction });
            if (cacheInvalidations < MAX_CACHE_INVALIDATIONS) {
                cacheInvalidations++;
            } else {
