```csharp
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Security.Cryptography;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.DependencyInjection;
using MyHashingLibrary.Services;

namespace MyHashingLibrary
{
    public class HashingService : IHashingService
    {
        private readonly ILogger<HashingService> _logger;
        private readonly IDictionary<string, ICryptographicAlgorithm> _algorithms;
        private readonly SettingsProvider _settingsProvider;

        public HashingService(IConfiguration configuration, ILogger<HashingService> logger)
        {
            _settingsProvider = new SettingsProvider(configuration);
            _logger = logger;
            _algorithms = new Dictionary<string, ICryptographicAlgorithm>();

            foreach (var algorithm in _settingsProvider.GetSupportedAlgorithms())
            {
                _algorithms.Add(algorithm, GetCryptographicAlgorithm(algorithm));
            }
        }

        public async Task<byte[]> HashAsync(byte[] data)
        {
            var algorithm = GetSelectedAlgorithm();
            return await algorithm.HashAsync(data);
        }

        private ICryptographicAlgorithm GetSelectedAlgorithm()
        {
            var selectedAlgorithm = _settingsProvider.GetSelectedAlgorithm();
            if (!_algorithms.ContainsKey(selectedAlgorithm))
            {
                throw new InvalidOperationException($"Unsupported algorithm: {selectedAlgorithm}");
            }

            return _algorithms[selectedAlgorithm];
        }

        private static ICryptographicAlgorithm GetCryptographicAlgorithm(string algorithm)
        {
            switch (algorithm)
            {
                case "SHA-256":
                    return new SHA256CryptoServiceProvider();
                case "SHA-384":
                    return new SHA384CryptoServiceProvider();
                default:
                    throw new NotSupportedException($"Unsupported algorithm: {algorithm}");
            }
        }
    }
}
```
