using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Collections.Generic;

// Secrets manager interface for managing encryption keys and IVs
interface ISecretsManager
{
    Task<EncryptionKey> GetEncryptionKeyAsync(string keyName);
    Task<InitializationVector> GetInitializationVectorAsync(string ivName);
}

// EncryptionKey class for storing symmetric encryption keys
class EncryptionKey
{
    public string Key { get; set; }
    public InitializationVector IV { get; set; }
}

// InitializationVector class for storing IVs used in symmetric encryption
class InitializationVector
{
    public byte[] IV { get; set; }
}

// Domain-specific model for storing decrypted data
class PayloadModel
{
    public string Data { get; set; }
}

// Encryption service for deciphering and verifying encrypted payloads
public class EncryptionService : IEncryptionService
{
    // Secrets manager instance for managing encryption keys and IVs
    private readonly ISecretsManager _secretsManager;

    // Constructor that initializes the secrets manager instance
    public EncryptionService(ISecretsManager secretsManager)
    {
        _secretsManager = secretsManager;
    }

    // Method for deciphering and verifying encrypted payloads
    public async Task<PayloadModel> DecryptAsync(string payload, string keyName, string ivName)
    {
        EncryptionKey encryptionKey = await _secretsManager.GetEncryptionKeyAsync(keyName);
        InitializationVector initializationVector = await _secretsManager.GetInitializationVectorAsync(ivName);

        // Decipher the encrypted payload using symmetric encryption
        SymmetricAlgorithm symmetricAlgorithm = new AesCryptoServiceProvider();
        symmetricAlgorithm.Key = Encoding.UTF8.GetBytes(encryptionKey.Key);
        symmetricAlgorithm.IV = initializationVector;
        ICryptoTransform decryptor = symmetricAlgorithm.CreateDecryptor();
        MemoryStream memoryStream = new MemoryStream(payload);
        CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
        BinaryReader reader = new BinaryReader(cryptoStream);
        byte[] decryptedPayload = reader.ReadBytes((int)memoryStream.Length);

        // Verify the integrity of the deciphered payload using a hash algorithm
        SHA256 sha256 = new SHA256Managed();
        byte[] hash = sha256.ComputeHash(decryptedPayload);
        if (!hash.SequenceEqual(encryptionKey.IV))
        {
            throw new InvalidOperationException("Integrity check failed for deciphered payload");
        }

        // Populate the domain-specific model with the deciphered data
        PayloadModel payloadModel = new PayloadModel();
        payloadModel.Data = Encoding.UTF8.GetString(decryptedPayload);

        return payloadModel;
    }
}

// Implementation of the IEncryptionService interface for testing purposes
public class TestEncryptionService : IEncryptionService
{
    public Task<PayloadModel> DecryptAsync(string payload, string keyName, string ivName)
    {
        return Task.FromResult(new PayloadModel() { Data = "Test data" });
    }
}
```
