['```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json.Linq;
using ServiceDiscovery.Contracts;

namespace LogProcessingTool
{
    public class LogProcessor
    {
        private readonly ILogger<LogProcessor> _logger;
        private readonly ServiceDiscoveryClient _serviceDiscoveryClient;
        private readonly HttpClient _httpClient;

        public LogProcessor(ILogger<LogProcessor> logger, ServiceDiscoveryClient serviceDiscoveryClient, HttpClient httpClient)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _serviceDiscoveryClient = serviceDiscoveryClient ?? throw new ArgumentNullException(nameof(serviceDiscoveryClient));
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        }

        public async Task ProcessLogAsync(string log)
        {
            var logParts = log.Split(',');
            if (logParts.Length != 3)
            {
                _logger.LogWarning("Invalid log message received: {message}", log);
                return;
            }

            var serviceName = logParts[0];
            var endpointUrl = $"{serviceName}/api/v1/log";
            var timeoutMillis = 5000;
            var apiKey = Environment.GetEnvironmentVariable("API_KEY");

            try
            {
                _logger.LogInformation("Sending log message to {service}...", serviceName);
                using var requestMessage = new HttpRequestMessage(HttpMethod.Post, endpointUrl);
                requestMessage.Headers.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);
                requestMessage.Content = new StringContent(log, Encoding.UTF8, "application/json");

                var response = await _httpClient.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead);
                if (response.IsSuccessStatusCode)
                {
                    _logger.LogInformation("Log message successfully sent to {service}", serviceName);
                }
                else
                {
                    _logger.LogWarning("Failed to send log message to {service} ({statusCode}). Message: {message}", serviceName, response.StatusCode, await response.Content.ReadAsStringAsync());
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred while sending log message to {service}: {exceptionMessage}", serviceName, ex.Message);
            }
        }
    }
}
