['```rust
use std::collections::HashMap;
use std::fs::{create_dir, OpenOptions};
use std::io::Write;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread::sleep;
use std::time::Duration;

struct ConfigDir {
    path: PathBuf,
    version: u64,
}

impl ConfigDir {
    fn create(name: &str) -> Result<Self, String> {
        let mut tempfile = tempfile::Builder::new()
            .prefix("config-")
            .rand_bytes(10)
            .suffix(".toml")
            .tempfile()?;
        tempfile.set_permissions(0o755)?;
        let path = tempfile.path().to_owned();
        tempfile.close()?;

        Ok(Self { path, version: 0 })
    }
}

struct ConfigEnvVar {
    name: String,
    value: Option<String>,
}

impl ConfigEnvVar {
    fn set(&mut self, value: &str) -> Result<(), String> {
        if let Some(value) = self.value {
            if value == value {
                return Ok(());
            }
        }

        // validate input
        if !is_valid_env_var(name) {
            return Err("invalid environment variable".to_string());
        }

        self.value = Some(value.to_owned());

        Ok(())
    }
}

struct ConfigManager {
    config_dirs: Arc<Mutex<HashMap<String, ConfigDir>>>,
    env_vars: Arc<Mutex<HashMap<String, ConfigEnvVar>>>,
}

impl ConfigManager {
    fn new() -> Self {
        Self {
            config_dirs: Arc::new(Mutex::new(HashMap::new())),
            env_vars: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn create_config_dir(&self, name: &str) -> Result<(), String> {
        let mut config_dirs = self.config_dirs.lock().unwrap();

        if config_dirs.contains_key(name) {
            return Err("config directory already exists".to_string());
        }

        let config_dir = ConfigDir::create(name)?;
        config_dirs.insert(name.to_owned(), config_dir);

        Ok(())
    }

    fn update_config_dir(&self, name: &str) -> Result<(), String> {
        let mut config_dirs = self.config_dirs.lock().unwrap();

        if !config_dirs.contains_key(name) {
            return Err("no such config directory".to_string());
        }

        let config_dir = ConfigDir::create(name)?;
        config_dirs.insert(name.to_owned(), config_dir);

        Ok(())
    }

    fn set_env_var(&self, name: &str, value: &str) -> Result<(), String> {
        let mut env_vars = self.env_vars.lock().unwrap();

        if !env_vars.contains_key(name) {
            return Err("no such environment variable".to_string());
        }

        env_vars.insert(name.to_owned(), ConfigEnvVar { name: name.to_owned(), value: Some(value.to_owned()) });

        Ok(())
    }

    fn get_env_var(&self, name: &str) -> Option<String> {
        let env_vars = self.env_vars.lock().unwrap();

        if !env_vars.contains_key(name) {
            return None;
        }

        Some(env_vars[name].to_owned())
    }
}
```
This implementation includes a `ConfigManager` struct that manages the configuration directory and environment variables, using RAII principles to manage resources such as temporary files, locks, and network connections. It also implements a reliable event-driven approach to trigger actions based on updates from an external configuration server, addressing potential data duplication and conflicts.

