#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdbool.h>

// Constants
#define BUFFER_SIZE 1024
#define MAX_ENDPOINTS 5
#define TIMEOUT 10 // seconds
#define RATE_LIMIT 10 // requests per second
#define RETRY_POLICY 3 // number of retries before failing request

// Structures
struct Endpoint {
    char* url;
    int latency;
    float success_rate;
    int response_time;
};

struct Request {
    char* url;
    int endpoint;
    bool retry;
    int retries;
    int status;
};

// Global variables
bool running = true;
int num_endpoints = 0;
struct Endpoint endpoints[MAX_ENDPOINTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
pthread_t thread;

// Function prototypes
void* handle_requests(void*);
int get_endpoint();
int make_request(struct Request*);
void update_metrics(struct Endpoint*);
bool is_healthy(struct Endpoint*);
void print_help();

// Main function
int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s [options]\n", argv[0]);
        return 1;
    }

    // Initialize endpoints
    for (int i = 0; i < MAX_ENDPOINTS; i++) {
        endpoints[i].url = NULL;
    }

    // Parse options
    int opt;
    while ((opt = getopt(argc, argv, "u:")) != -1) {
        switch (opt) {
            case 'u':
                if (num_endpoints < MAX_ENDPOINTS) {
                    endpoints[num_endpoints++].url = optarg;
                } else {
                    printf("Maximum number of endpoints reached.\n");
                }
                break;
        }
    }

    if (num_endpoints == 0) {
        print_help();
        return 1;
    }

    // Initialize request handling thread
    pthread_create(&thread, NULL, handle_requests, NULL);

    // Main loop
    while (running) {
        struct Request* request = malloc(sizeof(struct Request));
        char buffer[BUFFER_SIZE];
        printf("Enter URL: ");
        fgets(buffer, BUFFER_SIZE, stdin);
        int endpoint = get_endpoint();
        if (endpoint != -1) {
            request->url = strdup(buffer);
            request->endpoint = endpoint;
            make_request(request);
        } else {
            free(request);
        }
    }

    // Cleanup
    pthread_join(thread, NULL);
    for (int i = 0; i < num_endpoints; i++) {
        if (endpoints[i].url != NULL) {
            free(endpoints[i].url);
        }
    }

    return 0;
}

// Function definitions
void* handle_requests(void* args) {
    while (running) {
        struct Request* request = malloc(sizeof(struct Request));
        pthread_mutex_lock(&mutex);
        pthread_cond_wait(&cond, &mutex);
        int endpoint = get_endpoint();
        if (endpoint != -1) {
            request->url = endpoints[endpoint].url;
            request->endpoint = endpoint;
            request->retry = true;
            request->retries = 0;
            pthread_cond_signal(&cond);
        } else {
            free(request);
        }
    }
}

int get_endpoint() {
    int best_endpoint = -1;
    for (int i = 0; i < num_endpoints; i++) {
        if (is_healthy(&endpoints[i])) {
            best_endpoint = i;
            break;
        }
    }
    return best_endpoint;
}

int make_request(struct Request* request) {
    struct timeval timeout;
    timeout.tv_sec = TIMEOUT;
    timeout.tv_usec = 0;

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, request->url, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    int rc = connect(sockfd, (struct sockaddr*)&server_addr, sizeof(struct sockaddr_in));
    if (rc == -1) {
        perror("connect");
        close(sockfd);
        return -1;
    }

    char* buffer = malloc(BUFFER_SIZE);
    snprintf(buffer, BUFFER_SIZE, "GET / HTTP/1.1\r\nHost: %s\r\nConnection: Close\r\n\r\n", request->url);
    rc = send(sockfd, buffer, strlen(buffer), 0);
    if (rc == -1) {
        perror("send");
        close(sockfd);
        return -1;
    }

    free(buffer);
    char* response = malloc(BUFFER_SIZE);
    rc = recv(sockfd, response, BUFFER_SIZE, 0);
    if (rc == -1) {
        perror("recv");
        close(sockfd);
        return -1;
    }
    printf("%s\n", response);

    close(sockfd);
    return 0;
}

bool is_healthy(struct Endpoint* endpoint) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, endpoint->url, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        return false;
    }

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        return false;
    }

    struct timeval timeout;
    timeout.tv_sec = TIMEOUT;
    timeout.tv_usec = 0;

    int rc = connect(sockfd, (struct sockaddr*)&server_addr, sizeof(struct sockaddr_in));
    if (rc == -1) {
        perror("connect");
        close(sockfd);
        return false;
    }

    char* buffer = malloc(BUFFER_SIZE);
    snprintf(buffer, BUFFER_SIZE, "GET / HTTP/1.1\r\nHost: %s\r\nConnection: Close\r\n\r\n", endpoint->url);
    rc = send(sockfd, buffer, strlen(buffer), 0);
    if (rc == -1) {
        perror("send");
        close(sockfd);
        return false;
    }

    free(buffer);
    char* response = malloc(BUFFER_SIZE);
    rc = recv(sockfd, response, BUFFER_SIZE, 0);
    if (rc == -1) {
        perror("recv");
        close(sockfd);
        return false;
    }
    printf("%s\n", response);

    close(sockfd);
    return true;
}
```

The `get_endpoint()` function returns the index of the best endpoint for a request, based on the current health check results. It selects the endpoint with the lowest load average and the highest uptime. If all endpoints are unhealthy, it returns `-1`.

The `make_request()` function makes an HTTP request to the specified URL using TCP sockets. It sends a GET request to the server with the Host header set to the specified URL, followed by a newline character and two CRLF characters. It then reads the response from the socket until it reaches the end of the headers, and prints the response headers and body to stdout.

The `is_healthy()` function performs an HTTP GET request to the specified endpoint and returns `true` if the server responds with a 200 status code, and `false` otherwise. If there is any error when making the request or reading the response, it returns `false`.
