  if (argc < 2) {
    print_usage();
    return 1;
  } else {
    vector<string> args = vector<string>(argv + 1, argv + argc);
    run_command(args[0], args);
  }
}

void* thread_handler(void* data) {
  // Get the file information and metadata query from the data
  FileInfo file = *((FileInfo*)data);
  MetadataQuery query = parse_query(*((string*)data));

  // Process the file
  process_file(file, query);

  return NULL;
}

bool validate_path(const string& path) {
  // Check if the path is a directory or not
  struct stat sb;
  if (stat(path.c_str(), &sb) == 0 && S_ISDIR(sb.st_mode)) {
    return true;
  } else {
    return false;
  }
}

bool validate_metadata_identifier(const string& identifier) {
  // Check if the metadata identifier is valid
  for (size_t i = 0; i < identifiers.size(); i++) {
    if (identifiers[i].identifier == identifier) {
      return true;
    }
  }

  return false;
}

bool validate_metadata_value(const string& value) {
  // Check if the metadata value is valid
  for (size_t i = 0; i < identifiers.size(); i++) {
    if (identifiers[i].value == value) {
      return true;
    }
  }

  return false;
}

string generate_filename(const FileInfo& file, const MetadataQuery& query) {
  // Generate a filename based on the file information and metadata query
  string filename = "";

  for (size_t i = 0; i < identifiers.size(); i++) {
    if (identifiers[i].identifier == query.identifiers[0]) {
      filename += identifiers[i].value + "-";
    }
  }

  filename += file.path;

  return filename;
}

MetadataQuery parse_query(const string& query) {
  // Parse the metadata query and generate a MetadataQuery object
  vector<string> tokens = split(query, " ");
  vector<string> identifiers = split(tokens[0], "=");
  int64_t offset = stoi(identifiers[1]);
  int64_t limit = stoi(tokens[2]);

  return MetadataQuery{identifiers, tokens, offset, limit};
}

void cache_metadata(const string& path, const string& metadata) {
  // Cache the metadata in memory or disk based on the configuration
  if (cache_store == CacheStore::MEMORY) {
    total_cache_size += metadata.length();
    if (total_cache_size > cache_size) {
      cache_metadata(path, "");
    }
    unordered_map<string, string> cache;
    cache[path] = metadata;
  } else {
    // Write the metadata to disk in a temp file
    ofstream tmp_file("tmp.txt", ios::app);
    tmp_file << path + "=" + metadata;
    tmp_file.close();

    // Move the temp file to the cache location
    string cache_path = "cache/";
    if (mkdir(cache_path.c_str(), 0755) != 0 && errno != EEXIST) {
      cerr << "Error creating cache directory: " << strerror(errno) << endl;
      return;
    }
    string tmp_file_path = "tmp.txt";
    string cache_file_path = cache_path + path + ".txt";
    if (rename(tmp_file_path.c_str(), cache_file_path.c_str()) != 0) {
      cerr << "Error moving temp file to cache: " << strerror(errno) << endl;
      return;
    }
  }
}

void set_cache_size(int size) {
  // Set the cache size in bytes based on the configuration
  cache_size = size * 1024 * 1024;
}

string get_metadata(const string& path, const MetadataQuery& query) {
  // Get the metadata from memory or disk based on the configuration
  if (cache_store == CacheStore::MEMORY) {
    unordered_map<string, string> cache;
    cache[path] = "";
  } else {
    // Read the metadata from disk
    ifstream in(path + ".txt");
    if (!in.is_open()) {
      cerr << "Error reading file: " << strerror(errno) << endl;
      return "";
    }
    string line;
    while (getline(in, line)) {
      vector<string> tokens = split(line, "=");
      if (tokens[0] == query.identifiers[0]) {
        return tokens[1];
      }
    }
  }
}

vector<string> split(const string& s, const string& delimiter) {
  // Split a string into multiple strings based on a delimiter
  vector<string> tokens;
  size_t prev = 0, pos = 0;

  do {
    pos = s.find(delimiter, prev);
    if (pos == string::npos) pos = s.length();
    string token = s.substr(prev, pos-prev);
    if (!token.empty()) tokens.push_back(token);
    prev = pos + 1;
  } while (pos < s.length() && prev < s.length());

  return tokens;
}

void process_file(const FileInfo& file, const MetadataQuery& query) {
  // Process a file based on the configuration
  string metadata = get_metadata(file.path, query);
  if (metadata != "") {
    cache_metadata(file.path, metadata);
  }
}
