using System;
using System.IO;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;
using WebDeploymentManager.Models;

namespace WebDeploymentManager
{
    public class DeploymentService : IDisposable
    {
        private const int MaxRetryCount = 5;
        private const int RetryDelayBaseMs = 100;
        private const int RetryDelayFactor = 2;
        private const int ConnectionPoolSize = 5;

        private readonly HttpClient _httpClient;
        private readonly SemaphoreSlim _lock = new SemaphoreSlim(ConnectionPoolSize, ConnectionPoolSize);

        public DeploymentService()
        {
            var handler = new HttpClientHandler();
            _httpClient = new HttpClient(handler)
            {
                BaseAddress = new Uri("https://api.webserver.com/")
            };
        }

        public async Task<bool> DeployAsync(string directoryPath)
        {
            var result = false;

            if (!ValidateDirectoryPath(directoryPath))
            {
                LogWarning($"Invalid directory path: {directoryPath}");
                return result;
            }

            var webConfigFilePath = Path.Combine(directoryPath, "web.config");
            if (!ValidateWebConfigFile(webConfigFilePath))
            {
                LogWarning($"Invalid web.config file: {webConfigFilePath}");
                return result;
            }

            await _lock.WaitAsync();
            try
            {
                var deploymentRequest = new DeploymentRequest
                {
                    DirectoryPath = directoryPath,
                    WebConfigFilePath = webConfigFilePath
                };

                var response = await RetryPolicy.ExecuteAsync(async () =>
                {
                    return await _httpClient.PostAsJsonAsync("deployments", deploymentRequest);
                });

                if (response.IsSuccessStatusCode)
                {
                    result = true;
                }
                else
                {
                    LogError($"Failed to deploy directory: {directoryPath}");
                }
            }
            catch (Exception ex)
            {
                LogError(ex, $"Failed to deploy directory: {directoryPath}");
            }
            finally
            {
                _lock.Release();
            }

            return result;
        }

        public async Task<bool> StartAsync(string directoryPath)
        {
            var result = false;

            await _lock.WaitAsync();
            try
            {
                var response = await RetryPolicy.ExecuteAsync(async () =>
                {
                    return await _httpClient.PostAsync($"deployments/{directoryPath}/start", null);
                });

                if (response.IsSuccessStatusCode)
                {
                    result = true;
                }
                else
                {
                    LogError($"Failed to start deployment: {directoryPath}");
                }
            }
            catch (Exception ex)
            {
                LogError(ex, $"Failed to start deployment: {directoryPath}");
            }
            finally
            {
                _lock.Release();
            }

            return result;
        }

        public async Task<bool> StopAsync(string directoryPath)
        {
            var result = false;

            await _lock.WaitAsync();
            try
            {
                var response = await RetryPolicy.ExecuteAsync(async () =>
                {
                    return await _httpClient.PostAsync($"deployments/{directoryPath}/stop", null);
                });

                if (response.IsSuccessStatusCode)
                {
                    result = true;
                }
                else
                {
                    LogError($"Failed to stop deployment: {directoryPath}");
                }
            }
            catch (Exception ex)
            {
                LogError(ex, $"Failed to stop deployment: {directoryPath}");
            }
            finally
            {
                _lock.Release();
            }

            return result;
        }

        public async Task<bool> ScaleAsync(string directoryPath, int instances)
        {
            var result = false;

            await _lock.WaitAsync();
            try
            {
                var response = await RetryPolicy.ExecuteAsync(async () =>
                {
                    return await _httpClient.PostAsJsonAsync($"deployments/{directoryPath}/scale", instances);
                });

                if (response.IsSuccessStatusCode)
                {
                    result = true;
                }
                else
