Here is a sample implementation of the modular, scalable Node.js microservice that integrates with third-party APIs for managing system configurations:
```
const express = require('express');
const axios = require('axios');
const os = require('os');

// Define API endpoints
const app = express();
app.use(express.json());

app.get('/config', async (req, res) => {
  // Fetch configuration from third-party APIs
  const config = await fetchConfigFromAPIs();
  res.json(config);
});

app.put('/config', async (req, res) => {
  // Update configuration in third-party APIs
  const updateResponse = await updateConfigInAPIs(req.body);
  res.json(updateResponse);
});

// Define functions for fetching and updating configurations
async function fetchConfigFromAPIs() {
  try {
    // Fetch configuration from API 1
    const config1 = await axios.get(`http://api1/config`);
    // Fetch configuration from API 2
    const config2 = await axios.get(`http://api2/config`);
    return mergeConfigs(config1, config2);
  } catch (error) {
    console.log(`Error fetching configuration: ${error}`);
    throw error;
  }
}

async function updateConfigInAPIs(config) {
  try {
    // Update configuration in API 1
    const updateResponse1 = await axios.put(`http://api1/config`, config);
    // Update configuration in API 2
    const updateResponse2 = await axios.put(`http://api2/config`, config);
    return mergeUpdateResponses(updateResponse1, updateResponse2);
  } catch (error) {
    console.log(`Error updating configuration: ${error}`);
    throw error;
  }
}

function mergeConfigs(config1, config2) {
  const mergedConfig = {};
  // Merge configurations from API 1 and API 2
  Object.assign(mergedConfig, config1, config2);
  return mergedConfig;
}

function mergeUpdateResponses(updateResponse1, updateResponse2) {
  const mergedResponse = {};
  // Merge update responses from API 1 and API 2
  Object.assign(mergedResponse, updateResponse1, updateResponse2);
  return mergedResponse;
}

// Define functions for handling concurrent requests
async function handleConcurrentRequests() {
  try {
    const requests = [];
    // Create a request queue
    while (true) {
      const request = await axios.get(`http://api1/config`);
      requests.push(request);
      if (requests.length === os.cpus().length * 2) {
        // Handle concurrent requests
        await Promise.all(requests).then((results) => {
          console.log('All requests handled');
        });
        break;
      }
    }
  } catch (error) {
    console.log(`Error handling concurrent requests: ${error}`);
    throw error;
  }
}

// Define functions for rate limiting and back-off strategies
async function handleRateLimits() {
  try {
    // Implement rate limiting logic
    const rateLimit = 10;
    if (requests.length > rateLimit) {
      await Promise.all(requests).then((results) => {
        console.log(`Requests limited to ${rateLimit}`);
      });
      return;
    }
  } catch (error) {
    console.log(`Error handling rate limits: ${error}`);
    throw error;
  }
}

async function handleBackOff() {
  try {
    // Implement back-off logic
    const delay = 5000;
    if (requests.length > 1) {
      await Promise.all(requests).then((results) => {
        console.log(`Back-off triggered with ${delay} milliseconds`);
      });
      return;
    }
  } catch (error) {
    console.log(`Error handling back-offs: ${error}`);
    throw error;
  }
}

// Define functions for atomicity in file operations
async function handleFileOperations() {
  try {
    // Implement file operation logic
    const file = await fs.promises.open('config.json', 'a+');
    await file.write(`{ "key": "value" }`);
    await file.close();
  } catch (error) {
    console.log(`Error handling file operations: ${error}`);
    throw error;
  }
}

// Define functions for raising exceptions for failures and incorporating a rollback mechanism for partial failures
async function handleExceptions() {
  try {
    // Implement exception handling logic
    if (error) {
      console.log(`Error raised: ${error}`);
      throw error;
    }
  } catch (error) {
    console.log(`Error handling exceptions: ${error}`);
    throw error;
  }
}

// Define functions for logging and auditing
async function handleLogging() {
  try {
    // Implement logging logic
    const log = await fs.promises.createWriteStream('access.log', 'a+');
    await log.write(`${Date()} ${error}`);
    await log.close();
  } catch (error) {
    console.log(`Error handling logging: ${error}`);
    throw error;
  }
}

async function handleAuditing() {
  try {
    // Implement auditing logic
    const audit = await fs.promises.createWriteStream('audit.log', 'a+');
    await audit.write(`${Date()} ${error}`);
    await audit.close();
  } catch (error) {
    console.log(`Error handling auditing: ${error}`);
    throw error;
  }
}

// Define functions for versioning and backup
async function handleVersioning() {
  try {
    // Implement versioning logic
    const currentVersion = await fs.promises.readFile('config.json', 'utf-8');
    if (currentVersion !== latestVersion) {
      console.log(`Current version: ${currentVersion}`);
      console.log(`Latest version: ${latestVersion}`);
      return;
    }
  } catch (error) {
    console.log(`Error handling versioning: ${error}`);
    throw error;
  }
}

async function handleBackup() {
  try {
    // Implement backup logic
