#include <future>
#include <queue>
#include <cassert>
#include <vector>
#include <algorithm>
#include <iterator>
#include <memory>
#include <utility>

// Semaphore class
class Semaphore {
public:
    // Constructor with initial value and name
    Semaphore(int initialValue, const std::string& name) :
        value_(initialValue),
        name_(name) {}

    // Acquire semaphore (decrement value by 1)
    void acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (value_ <= 0) {
            condition_.wait(lock);
        }
        --value_;
    }

    // Release semaphore (increment value by 1)
    void release() {
        std::unique_lock<std::mutex> lock(mutex_);
        ++value_;
        condition_.notify_all();
    }

    // Return current value of the semaphore
    int getValue() const {
        return value_;
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    int value_;
    std::string name_;
};

// Semaphore manager class
class SemaphoreManager {
public:
    // Constructor with number of semaphores and initial values
    SemaphoreManager(int numSemaphores, const std::vector<int>& initialValues) :
        semaphores_(numSemaphores),
        initialValues_(initialValues) {}

    // Create semaphore with specified name and initial value
    void createSemaphore(const std::string& name, int initialValue) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(semaphores_.begin(), semaphores_.end(), [&](auto& s) { return s->getName() == name; });
        if (it != semaphores_.end()) {
            throw std::invalid_argument("Semaphore with name " + name + " already exists");
        }

        auto semaphore = std::make_shared<Semaphore>(initialValue, name);
        semaphores_.push_back(semaphore);
    }

    // Delete semaphore with specified name
    void deleteSemaphore(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(semaphores_.begin(), semaphores_.end(), [&](auto& s) { return s->getName() == name; });
        if (it == semaphores_.end()) {
            throw std::invalid_argument("Semaphore with name " + name + " does not exist");
        }

        semaphores_.erase(it);
    }

    // Acquire semaphore with specified name
    void acquire(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(semaphores_.begin(), semaphores_.end(), [&](auto& s) { return s->getName() == name; });
        if (it == semaphores_.end()) {
            throw std::invalid_argument("Semaphore with name " + name + " does not exist");
        }

        it->get()->acquire();
    }

    // Release semaphore with specified name
    void release(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(semaphores_.begin(), semaphores_.end(), [&](auto& s) { return s->getName() == name; });
        if (it == semaphores_.end()) {
            throw std::invalid_argument("Semaphore with name " + name + " does not exist");
        }

        it->get()->release();
    }

    // Return current value of the semaphore with specified name
    int getValue(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::find_if(semaphores_.begin(), semaphores_.end(), [&](auto& s) { return s->getName() == name; });
        if (it == semaphores_.end()) {
            throw std::invalid_argument("Semaphore with name " + name + " does not exist");
        }

        return it->get()->getValue();
    }

private:
    // Vector of semaphore pointers
    std::vector<std::shared_ptr<Semaphore>> semaphores_;

    // Initial values for the semaphores
    std::vector<int> initialValues_;

    // Mutex for thread-safe access to the vector of semaphores
    std::mutex mutex_;
};

// Logging class
class Logger {
public:
    // Constructor with log level and file path
    Logger(LogLevel level, const std::string& filePath) :
        level_(level),
        filePath_(filePath) {}

    // Write message to the log file
    void writeMessage(const std::string& message) {
        std::ofstream ofs(filePath_, std::ios_base::app);
        ofs << message << "\n";
    }

private:
    // Log level (e.g., info, warning, error)
    LogLevel level_;

    // File path for log file
    std::string filePath_;
};

// Semaphore class with logging functionality
class LoggingSemaphore : public Semaphore {
public:
    // Constructor with name and initial value, logger instance
    LoggingSemaphore(const std::string& name, int initialValue, Logger& logger) :
        Semaphore(name, initialValue),
        logger_(logger) {}

    // Acquire the semaphore
    void acquire() {
        logger_.writeMessage("Acquiring semaphore " + getName());
        Semaphore::acquire();
        logger_.writeMessage("Semaphore " + getName() + " acquired");
    }

    // Release the semaphore
    void release() {
        logger_.writeMessage("Releasing semaphore " + getName());
        Semaphore::release();
        logger_.writeMessage("Semaphore " + getName() + " released");
    }

private:
    // Logger instance
    Logger& logger_;
};

// Main function for the program
int main() {
    // Initialize logging
    LoggingSemaphore semaphore1("semaphore1", 0, logger);
    Logger logger(LogLevel::info, "log.txt");

    // Create and delete semaphores
    semaphore1.createSemaphore("semaphore2", 1);
    semaphore1.deleteSemaphore("semaphore2");

    // Acquire and release semaphores
    semaphore1.acquire();
    semaphore1.release();

    // Get the current value of a semaphore
    std::cout << "Value of semaphore1: " << semaphore1.getValue() << "\n";
}
```']

