class DynamicNetworkClient {
public:
    DynamicNetworkClient(const std::string& baseUrl, const std::unordered_map<std::string, std::string>& headers = {}, int timeout = 10)
        : baseUrl_(baseUrl), headers_(headers), timeout_(timeout) {}

    ~DynamicNetworkClient() {
        stop();
    }

    void start() {
        if (!running_) {
            running_ = true;
            std::thread([this]() {
                while (running_) {
                    // check for new work
                    std::unique_lock<std::mutex> lock(queueMutex_);
                    if (requestQueue_.empty()) {
                        continue;
                    }
                    RequestData data = requestQueue_.front();
                    requestQueue_.pop();

                    // perform work
                    std::string responseBody;
                    int statusCode = makeRequest(data.method, data.url, data.headers, data.payload, responseBody);

                    // handle response
                    if (statusCode == 200) {
                        if (!responseBody.empty()) {
                            std::cout << "Successfully received response for request: " << data.id << std::endl;
                            data.callback(data, statusCode, responseBody);
                        } else {
                            std::cout << "Response body is empty!" << std::endl;
                        }
                    } else {
                        std::cout << "Error: " << statusCode << std::endl;
                    }
                }
            }).detach();
        }
    }

    void stop() {
        running_ = false;
    }

    void sendRequest(const std::string& method, const std::string& url, const std::unordered_map<std::string, std::string>& headers = {}, const std::string& payload = "", const RequestCallback& callback = nullptr) {
        if (running_) {
            std::cout << "Sending request..." << std::endl;
            // add to queue
            RequestData data(method, url, headers, payload, callback);
            std::unique_lock<std::mutex> lock(queueMutex_);
            requestQueue_.push(data);
            requestCondVar_.notify_one();
        } else {
            std::cout << "Client is not running!" << std::endl;
        }
    }

private:
    struct RequestData {
        RequestData(const std::string& method, const std::string& url, const std::unordered_map<std::string, std::string>& headers, const std::string& payload, const RequestCallback& callback)
            : method(method), url(url), headers(headers), payload(payload), callback(callback) {}
        std::string method;
        std::string url;
        std::unordered_map<std::string, std::string> headers;
        std::string payload;
        RequestCallback callback;
    };

    typedef void (*RequestCallback)(const RequestData& data, int statusCode, const std::string& responseBody);

    bool running_;
    std::string baseUrl_;
    std::unordered_map<std::string, std::string> headers_;
    int timeout_;
    std::mutex queueMutex_;
    std::condition_variable requestCondVar_;
    std::queue<RequestData> requestQueue_;

    void makeRequest(const std::string& method, const std::string& url, const std::unordered_map<std::string, std::string>& headers, const std::string& payload, std::string& responseBody) {
        // TODO: implement HTTP request here using the provided parameters and return the status code and response body
    }
};
