// ImageOptimizer.java
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import org.apache.commons.io.IOUtils;
import org.apache.commons.lang3.tuple.Pair;

public class ImageOptimizer {
    private static final int MAX_FILE_SIZE = 1024 * 1024; // 1MB
    private static final String[] SUPPORTED_FORMATS = new String[] {"JPEG", "PNG", "GIF", "WEBP"};

    public Pair<File, Integer> optimizeImage(String url, int minWidth, int minHeight, int maxWidth, int maxHeight, boolean lossless) throws IOException {
        // 1. Validate input parameters and retrieve image metadata
        File originalFile = validateInput(url);
        BufferedImage originalImage = ImageIO.read(originalFile);
        int originalWidth = originalImage.getWidth();
        int originalHeight = originalImage.getHeight();
        int originalSize = (int) originalFile.length();

        // 2. Analyze and validate image dimensions and format
        if (!isSupportedFormat(originalImage)) {
            throw new IOException("Unsupported file format: " + url);
        }
        if (minWidth > maxWidth || minHeight > maxHeight) {
            throw new IllegalArgumentException("Invalid resolution limits");
        }
        if (originalSize > MAX_FILE_SIZE) {
            throw new IOException("Image file size exceeds limit: " + url);
        }

        // 3. Apply dynamic resizing algorithm to preserve aspect ratio and visual quality
        int resizeWidth = Math.max(minWidth, Math.min(originalWidth, maxWidth));
        int resizeHeight = Math.max(minHeight, Math.min(originalHeight, maxHeight));
        BufferedImage resizedImage;
        if (lossless) {
            resizedImage = Scalr.resize(originalImage, ResizeMethod.ULTRA_QUALITY, resizeWidth, resizeHeight);
        } else {
            resizedImage = Scalr.resize(originalImage, ResizeMethod.AUTOMATIC, resizeWidth, resizeHeight);
        }

        // 4. Implement intelligent caching mechanism to store optimized images based on URL and hash of metadata
        File cacheFile = new File("cache", Hashing.sha1().hashUnencodedChars(url).toString() + ".jpg");
        if (cacheFile.exists()) {
            return Pair.of(cacheFile, originalSize);
        } else {
            ImageIO.write(resizedImage, "JPEG", cacheFile);
            return Pair.of(cacheFile, IOUtils.toByteArray(new FileInputStream(cacheFile)).length);
        }
    }

    private boolean isSupportedFormat(BufferedImage image) {
        String formatName = image.getColorModel().getColorSpace().getName();
        for (String supportedFormat : SUPPORTED_FORMATS) {
            if (supportedFormat.equalsIgnoreCase(formatName)) {
                return true;
            }
        }
        return false;
    }

    private File validateInput(String url) throws IOException {
        File originalFile = new File(url);
        if (!originalFile.exists()) {
            throw new IOException("Invalid image URL: " + url);
        }
        return originalFile;
    }
}

// Scalr.java (external library for image resizing)
import java.awt.image.BufferedImage;
import org.imgscalr.Scalr;

public class Scalr {
    public static BufferedImage resize(BufferedImage src, ResizeMethod method, int width, int height) {
        return Scalr.resize(src, method, width, height);
    }
}

// Hashing.java (external library for image hashing)
import com.google.common.hash.HashFunction;
import com.google.common.hash.Hashing;

public class Hashing {
    public static String sha1(String value) {
        return Hashing.sha1().newHasher().putUnencodedChars(value).hash().toString();
    }
}']

