Here is an example of the generateDynamicFileName function:
```scss
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

string generateDynamicFileName(const string& filename) {
    // Split the filename into a vector of tokens based on the extension separator (.)
    vector<string> tokens = split(filename, ".");
    if (tokens.size() == 0) {
        return "";
    }

    // Get the extension from the last token
    string extension = tokens[tokens.size() - 1];

    // Check if the extension is already in a desired format
    if (extension == "xml" || extension == "json") {
        return filename;
    }

    // Generate a new file name with a customized suffix based on the extension
    string newFileName = "";
    for (int i = 0; i < tokens.size() - 1; i++) {
        newFileName += tokens[i] + ".";
    }
    newFileName += extension + "-dynamic";

    return newFileName;
}

// Split a string into a vector of tokens based on a separator character
vector<string> split(const string& str, char sep) {
    vector<string> tokens;
    size_t i = 0;
    while (i < str.length()) {
        size_t j = i + 1;
        while (j < str.length() && str[j] != sep) {
            j++;
        }
        tokens.push_back(str.substr(i, j - i));
        i = j + 1;
    }
    return tokens;
}
```
This function takes a filename as a UTF-8 string and returns a new filename based on customizable rules. The function first splits the filename into a vector of tokens based on the extension separator (.) and then checks if the last token is already in the desired format (e.g., "xml" or "json"). If it is, the original filename is returned. Otherwise, a new file name with a customized suffix is generated based on the last token.

To use this function, simply call it with the filename as an argument:
```scss
string dynamicFileName = generateDynamicFileName("example.txt");
cout << "New file name: " << dynamicFileName << endl;
```']

