```
// Configuration variables
const config = {
  directories: ['/var/log', '/var/log2'], // Directories to monitor for log files
  fileFilter: /^\d{4}-\d{2}-\d{2}.log$/, // Filter for log files by timestamp and extension
  maxConcurrentJobs: 10, // Maximum number of concurrent jobs to run at a time
  processingThreshold: 500, // Processing threshold in milliseconds
  alertingSystem: 'https://alerting-system.com/', // URL for external monitoring and alerting system
};

// Set up file watcher to monitor directories for new log files
const fs = require('fs');
const chokidar = require('chokidar');
const watcher = chokidar.watch(config.directories, { persistent: true });

// Function to process a log file asynchronously
async function processLogFile(filePath) {
  // Check if file is within processing threshold and if not, return early
  const currentTime = Date.now();
  if (currentTime - fs.statSync(filePath).mtimeMs < config.processingThreshold) {
    console.log(`Skipping log file ${filePath} as it is within the processing threshold.`);
    return;
  }

  // Parse JSON from log file and transform if necessary
  const json = fs.readFileSync(filePath, 'utf-8');
  const transformedJson = jsonTransformer(json);

  // Post processed JSON to external monitoring and alerting system
  await axios.post(config.alertingSystem, transformedJson);
}

// Function to run processing jobs concurrently with load balancing
async function runJobs() {
  const jobs = [];
  for (const filePath of watcher.getWatchedFiles()) {
    if (!fileFilter.test(filePath)) continue;
    jobs.push(processLogFile(filePath));
    if (jobs.length >= maxConcurrentJobs) break;
  }
  await Promise.all(jobs);
}

// Function to handle edge cases and maintain data integrity and consistency
async function handleEdgeCases() {
  // Check for partial failures during processing and resume if necessary
  try {
    await runJobs();
  } catch (error) {
    console.log(`Error during processing: ${error}`);
    const lastSuccessfulState = await getLastSuccessfulState();
    await resumeProcessing(lastSuccessfulState);
  }
}

// Function to handle rate limiting and ensure the service can scale automatically in response to load changes
async function handleRateLimiting() {
  // Check for rate limit exceeded errors during processing and slow down if necessary
  try {
    await runJobs();
  } catch (error) {
    console.log(`Error during processing: ${error}`);
    const lastSuccessfulState = await getLastSuccessfulState();
    await slowDownProcessing(lastSuccessfulState);
  }
}

// Function to handle complex, nested log file structures by implementing robust JSON parsing and transformation mechanisms
async function jsonTransformer(json) {
  // Parse JSON from log file and transform if necessary
  const transformedJson = JSON.parse(json);
  // Transform data as needed based on business requirements
  return transformedJson;
}

// Function to track the service's health and performance under high-load conditions, providing detailed insights into processing bottlenecks
async function monitoringFramework() {
  // Implement monitoring framework using Prometheus or other metrics tooling
}

// Function to prepare the service for deployment in containerized environments, supporting blue/green deployments for smooth rollouts and rollbacks
async function deploymentFramework() {
  // Implement deployment framework using Docker or Kubernetes
}
```
