 public:
  // Add a new session context to the cache.
  void addSession(const std::string& userId, const std::string& authToken) {
    std::lock_guard<std::mutex> lock(mutex_);
    sessionMap_.emplace(userId, SessionContext{userId, authToken, std::chrono::system_clock::now(), true});
  }

  // Update the last activity time of a specific session.
