['```c
int filter_transactions(transaction* transactions[], int n_transactions,
                       int max_age, int min_num_recent, int min_weight) {
    // Initialize the set of metrics and the maximum weighted sum to 0.
    int max_weight = 0;
    int transaction_id = -1;
    double total_weight = 0;

    // Iterate through each transaction in the array.
    for (int i = 0; i < n_transactions; i++) {
        // Check if the transaction is older than the maximum age.
        if (transactions[i]->age > max_age) {
            continue;
        }

        // Count the number of transactions in the past 3 seconds.
        int num_recent = 0;
        for (int j = i - 1; j >= 0 && transactions[j]->timestamp + 3 > get_current_time(); j--) {
            num_recent++;
        }

        // Check if the number of recent transactions meets the minimum requirement.
        if (num_recent < min_num_recent) {
            continue;
        }

        // Calculate the weighted sum of the transaction.
        double weight = transactions[i]->amount * transactions[i]->age / 100;

        // Update the set of metrics and the maximum weighted sum if necessary.
        total_weight += weight;
        if (weight > max_weight) {
            max_weight = weight;
            transaction_id = i;
        }
    }

    return max_weight;
}
