// Modular, scalable C++ component for a MOBA game that dynamically selects one of five advanced attack strategies for a character, ensuring thread-safe execution in a highly concurrent environment.

#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class AttackSelector {
public:
    AttackSelector(int maxConcurrentAttacks) : maxConcurrentAttacks_(maxConcurrentAttacks) {}

    void selectAttackStrategy(std::function<void()> onAttackStrategySelected) {
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if there are any available attack slots.
        if (concurrentAttacks_ < maxConcurrentAttacks_) {
            concurrentAttacks_++;
            onAttackStrategySelected();
            return;
        }

        // Add the callback to the queue and wait for an available attack slot.
        auto callback = [onAttackStrategySelected]() {
            std::lock_guard<std::mutex> lock(mutex_);
            onAttackStrategySelected();
            concurrentAttacks_--;
            cv_.notify_one();
        };
        queue_.push_back(callback);
        cv_.wait(lock, [this] { return concurrentAttacks_ < maxConcurrentAttacks_; });
    }

private:
    int maxConcurrentAttacks_;
    int concurrentAttacks_ = 0;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<std::function<void()>> queue_;
};

