    private final Map<String, Command> pendingCommands = new ConcurrentHashMap<>();

    // Define a method for processing a command
    public void processCommand(Command command) {
        // Acquire a distributed lock on the command ID to prevent concurrent executions
        String commandId = command.getId();
        Lock lock = lockManager.acquireLock(commandId);

        try {
            // Validate the command against an external REST API, respecting rate limits and timeouts
            restClient.validateCommand(command);

            // Execute the command in a separate thread using the executor service
            executorService.execute(() -> {
                // Process the command
                try {
                    command.process();
                } catch (Exception e) {
                    // Log the error and retry the command after an exponential backoff
                    log.error("Error processing command", e);
                    long delay = calculateDelay(e);
                    Thread.sleep(delay);
                    processCommand(command);
                } finally {
                    // Release the lock on the command ID
                    lockManager.releaseLock(lock);
                }
