class Logger {
public:
    Logger(const std::string& filename) : filename_(filename) {}

    ~Logger() {
        if (fstream_.is_open()) {
            fstream_.close();
        }
    }

    void write(const std::string& message, LogLevel level = LogLevel::INFO) {
        if (!fstream_.is_open()) {
            return;
        }

        // Acquire mutex to ensure thread-safety
        std::lock_guard<std::mutex> lock(mutex_);

        // Write message to file stream
        fstream_ << message << "\n";

        // Update statistics for this message
        ++messageCount_;
        totalMessageSize_ += message.size();
    }

private:
    std::string filename_;
    std::fstream fstream_;
    std::mutex mutex_;
    size_t messageCount_ = 0;
    size_t totalMessageSize_ = 0;
};
