class DatabaseConnectionManager {
public:
    DatabaseConnectionManager(const std::string& host, const std::string& port) : host_(host), port_(port) {}

    ~DatabaseConnectionManager() {
        if (connections_.size()) {
            for (auto& connection : connections_) {
                delete connection;
            }
        }
    }

    void addConnection(const std::string& username, const std::string& password) {
        // Acquire mutex to ensure thread-safety
        std::lock_guard<std::mutex> lock(mutex_);

        // Create new database connection
        auto* connection = new DatabaseConnection(host_, port_, username, password);
        connections_.push_back(connection);
    }

private:
    class DatabaseConnection {
    public:
        DatabaseConnection(const std::string& host, const std::string& port, const std::string& username, const std::string& password) : host_(host), port_(port), username_(username), password_(password) {}

        void query(const std::string& sql) {
            // Acquire mutex to ensure thread-safety
            std::lock_guard<std::mutex> lock(mutex_);

            // Create connection if needed
            if (!connection_) {
                connection_ = new MySQLConnection();
                connection_->connect(host_, port_, username_, password_);
            }

            // Execute query on database
            auto result = connection_->query(sql);

            // Release connection back to pool
            if (result.size() == 0) {
                delete connection_;
                connection_ = nullptr;
            }
        }

    private:
        std::string host_;
        std::string port_;
        std::string username_;
        std::string password_;
        MySQLConnection* connection_ = nullptr;
    };

    std::vector<DatabaseConnection*> connections_;
    std::mutex mutex_;
};
