        if (cache_.size()) {
            for (auto& cache : cache_) {
                delete cache;
            }
        }
    }

    void set(const std::string& key, const std::string& value) {
        // Acquire mutex to ensure thread-safety
        std::lock_guard<std::mutex> lock(mutex_);

        // Create new cache if needed
        if (!cache_.count(key)) {
            auto* cache = new Cache(key, value);
            cache_.emplace(key, cache);
        } else {
            cache_[key]->setValue(value);
        }
    }

    std::string get(const std::string& key) {
        // Acquire mutex to ensure thread-safety
        std::lock_guard<std::mutex> lock(mutex_);

        // Return value from cache if exists
        if (cache_.count(key)) {
            return cache_[key]->getValue();
        }

        return "";
    }

private:
    class Cache {
    public:
        Cache(const std::string& key, const std::string& value) : key_(key), value_(value) {}

        void setValue(const std::string& value) {
            value_ = value;
        }

        std::string getValue() {
            return value_;
        }

    private:
        std::string key_;
        std::string value_;
    };

    std::map<std::string, Cache*> cache_;
    std::mutex mutex_;
};
