import json
from typing import Dict, List, Optional
from threading import Lock

class JSONManager:
    def __init__(self):
        self.data: Dict[str, dict] = {}
        self.lock: Lock = Lock()

    def get_data(self, key: str) -> Optional[dict]:
        with self.lock:
            return self.data.get(key)

    def set_data(self, key: str, value: dict):
        with self.lock:
            self.data[key] = value

    def delete_data(self, key: str):
        with self.lock:
            del self.data[key]

class JSONValidator:
    def __init__(self, schema: Dict[str, dict]):
        self.schema = schema

    def validate(self, data: dict) -> bool:
        for key, value in self.schema.items():
            if key not in data:
                return False
            elif isinstance(value, dict):
                return self.validate(data[key])
            else:
                if value != data[key]:
                    return False
        return True

class JSONParser:
    def __init__(self, schema: Dict[str, dict], caching: bool = True):
        self.schema = schema
        self.caching = caching

    def parse(self, data: str) -> Optional[dict]:
        if self.caching:
            json_data = json.loads(data)
            validator = JSONValidator(self.schema)
            if validator.validate(json_data):
                return json_data
            else:
                return None
        else:
            try:
                json_data = json.loads(data)
                validator = JSONValidator(self.schema)
                if validator.validate(json_data):
                    return json_data
                else:
                    return None
            except json.JSONDecodeError:
                return None

class RESTfulAPI:
    def __init__(self, url: str, timeout: int = 5):
        self.url = url
        self.timeout = timeout

    def get(self) -> Optional[dict]:
        try:
            response = requests.get(self.url, timeout=self.timeout)
            if response.status_code == 200:
                return json.loads(response.content)
            else:
                return None
        except requests.RequestException:
            return None

class JSONDataManager:
    def __init__(self, parser: JSONParser, api: RESTfulAPI, caching: bool = True):
        self.parser = parser
        self.api = api
        self.caching = caching
        self.lock: Lock = Lock()

    def get_data(self, key: str) -> Optional[dict]:
        with self.lock:
            if self.caching:
                data = self.parser.parse(key)
                if data is None:
                    data = self.api.get()
                    if data is not None:
                        self.parser.set_data(key, data)
            else:
                data = self.api.get()
                if data is not None:
                    self.parser.set_data(key, data)
            return data

    def set_data(self, key: str, value: dict):
        with self.lock:
            self.parser.set_data(key, value)

    def delete_data(self, key: str):
        with self.lock:
            self.parser.delete_data(key)

class JSONDataManagerFactory:
    @staticmethod
    def create(url: str, timeout: int = 5, caching: bool = True) -> JSONDataManager:
        parser = JSONParser(schema={"name": str, "age": int}, caching=caching)
        api = RESTfulAPI(url=url, timeout=timeout)
        return JSONDataManager(parser=parser, api=api, caching=caching)']

