    // Populate list of CRC_INDICATION_PDU_T structures with valid data
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crc_indication->valid = 1;
    crc_indication->crc_indication_rel8_tag = 0x02;
    crc_indication->crcflag = rand() % 256; // Generate random CRC flag using standard library function

    // Set up and validate NFAPI-based RAN site configuration
    NFAPI_STATUS status = nfapi_setup(directory, site);
    if (status != NFAPI_OK) {
        return NFAPI_ERROR;
    }
    status = nfapi_validate();
    if (status != NFAPI_OK) {
        return NFAPI_ERROR;
    }

    // Clean up temporary data structures
