void initializeNfarxSite(const char *directoryPath, const char *siteName) {
    // Initialize variables
    int errorCode = 0;
    bool configExists = false;
    NFAPI_CRC_INDICATION_PDU_T crcIndicationPdu = { 0 };
    char *rxUeInformationTag = NULL;
    uint16_t rnti = 0;
    uint8_t crcFlag = 0;
    // Check if web.config file exists in the specified directory
    errorCode = checkFileExists(directoryPath, "web.config");
    if (errorCode == 0) {
        configExists = true;
    } else {
        // Fall back to default configuration if web.config file is not found
        configExists = false;
        logError("Failed to find web.config file in specified directory");
    }
    // Validate the site name and generate a unique RX_UE_INFORMATION_TAG
    errorCode = validateSiteName(siteName);
    if (errorCode != 0) {
        logError("Invalid site name detected");
        return;
    }
    rxUeInformationTag = generateUniqueRxUeInformationTag();
    // Set up CRC indication for the site
    crcIndicationPdu.rx_ue_information_tag = rxUeInformationTag;
    crcIndicationPdu.rnti = rnti;
    crcIndicationPdu.crc_indication_rel8_tag = NFAPI_CRC_INDICATION_REL8_TAG;
    crcIndicationPdu.crcFlag = crcFlag;
    // Add the CRC indication PDU to a list of CRC indication PDUS
    addCrcIndicationPdu(crcIndicationPdu);
    // Clean up temporary variables
    free(rxUeInformationTag);
}

