// Define the configuration structure for the data processor
struct DataProcessorConfig {
    // List of data sources to be processed
    std::vector<std::string> dataSources;
    // Transformation rules for each data source
    std::map<std::string, std::function<void(const std::string&)>> transformationRules;
    // Storage adapters for each data source
