using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

namespace CSharpService
{
    public class SQLQueryService
    {
        private readonly string _connectionString;
        private readonly Dictionary<string, object> _queryTemplates = new Dictionary<string, object>();
        private readonly HashSet<string> _parameterMappings = new HashSet<string>();
        private readonly List<string> _externalDataSources = new List<string>();

        public SQLQueryService(string connectionString)
        {
            _connectionString = connectionString;
        }

        public void AddQueryTemplate(string templateName, string query)
        {
            if (_queryTemplates.ContainsKey(templateName))
                throw new InvalidOperationException($"A query template with the name '{templateName}' already exists.");

            _queryTemplates.Add(templateName, query);
        }

        public void AddParameterMapping(string parameterName, string variableName)
        {
            if (_parameterMappings.Contains(variableName))
                throw new InvalidOperationException($"A parameter mapping for the variable '{variableName}' already exists.");

            _parameterMappings.Add(variableName);
        }

        public void AddExternalDataSource(string dataSource)
        {
            if (_externalDataSources.Contains(dataSource))
                throw new InvalidOperationException($"An external data source with the name '{dataSource}' already exists.");

            _externalDataSources.Add(dataSource);
        }

        public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string templateName, Dictionary<string, object> parameters = null) where T : class
        {
            if (!_queryTemplates.ContainsKey(templateName))
                throw new InvalidOperationException($"A query template with the name '{templateName}' does not exist.");

            string query = _queryTemplates[templateName];

            using (SqlConnection connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    if (parameters != null)
                    {
                        foreach (var parameter in parameters)
                        {
                            if (_parameterMappings.Contains(parameter.Key))
                            {
                                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                            }
                            else
                            {
                                throw new InvalidOperationException($"A parameter mapping for the variable '{parameter.Key}' does not exist.");
                            }
                        }
                    }

                    using (SqlDataReader reader = await command.ExecuteReaderAsync())
                    {
                        List<T> results = new List<T>();

                        while (await reader.ReadAsync())
                        {
                            var result = new T();

                            for (int i = 0; i < reader.FieldCount; i++)
                            {
                                if (reader[i] != DBNull.Value)
                                {
                                    Type type = typeof(T).GetProperty(reader.GetName(i)).PropertyType;

                                    switch (type.Name)
                                    {
                                        case "Int32":
                                            result.GetType().GetProperty(reader.GetName(i)).SetValue(result, reader.GetInt32(i));
                                            break;
                                        case "String":
                                            result.GetType().GetProperty(reader.GetName(i)).SetValue(result, reader.GetString(i));
                                            break;
                                        case "DateTime":
                                            result.GetType().GetProperty(reader.GetName(i)).SetValue(result, reader.GetDateTime(i));
                                            break;
                                    }
                                }
                            }

                            results.Add(result);
                        }

                        return results;
                    }
                }
            }
        }

        public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string templateName, IEnumerable<object> parameters) where T : class
        {
            if (!_queryTemplates.ContainsKey(templateName))
                throw new InvalidOperationException($"A query template with the name '{templateName}' does not exist.");

            string query = _queryTemplates[templateName];

            using (SqlConnection connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    int parameterIndex = 0;
                    foreach (var parameter in parameters)
                    {
                        if (_parameterMappings.Contains($"@p{parameterIndex}"))
                        {
                            command.Parameters.AddWithValue($"@p{parameterIndex++}", parameter);
                        }
                        else
                        {
                            throw new InvalidOperationException($"A parameter mapping for the variable '@p{parameterIndex}' does not exist.");
                        }
                    }

                    using (SqlDataReader reader = await command.ExecuteReaderAsync())
                    {
                        List<T> results = new List<T>();

                        while (await reader.ReadAsync())
                        {
                            var result = new T();

                            for (int i = 0; i < reader.FieldCount; i++)
                            {
                                if (reader[i] != DBNull.Value)
                                {
                                    Type type = typeof(T).GetProperty(reader.GetName(i)).PropertyType;

                                    switch (type.Name)
                                    {
                                        case "Int32":
                                            result.GetType().GetProperty(reader.GetName(i)).SetValue(result, reader.GetInt32(i));
                                            break;
                                        case "String":
                                            result.GetType().GetProperty(reader.GetName(i)).SetValue(result, reader.GetString(i));
                                            break;
                                        case "DateTime":
                                            result.GetType().GetProperty(reader.GetName(i)).SetValue(result, reader.GetDateTime(i));
                                            break;
                                    }
                                }
                            }

                            results.Add(result);
                        }

                        return results;
                    }
                }
            }
        }
    }
}
