// C++ code for SecureRandomGenerator library
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

// Define the entropy source types
enum EntropySourceType { HRNG, CSPRNG, SWEntropyCollector };

// Define the security mode options
enum SecurityMode { Standard, Secure };

// Define the callback priorities
enum CallbackPriority { High = 1, Normal = 2, Low = 3 };

class SecureRandomGenerator {
    private:
        // Define the entropy sources and their types
        std::vector<std::pair<EntropySourceType, void*>> entropySources;

        // Define the current entropy source index
        size_t currentEntropySourceIndex = 0;

        // Define the callback queues for each priority level
        std::map<CallbackPriority, std::queue<std::function<void(const uint64_t&)>>> callbackQueues;

        // Define the mutex and condition variable for synchronizing access to the entropy sources and callbacks
        std::mutex mutex;
        std::condition_variable cv;

        // Define the security mode
        SecurityMode securityMode = Standard;

        // Define the entropy collection rate (in Hz)
        double entropyCollectionRate = 0.5;

        // Define the cache size for common ranges (in bytes)
        size_t cacheSize = 1024 * 1024;

        // Define the minimum and maximum values for each range in the cache
        std::map<size_t, uint64_t> minValues;
        std::map<size_t, uint64_t> maxValues;

        // Define the callback function for new random sequences
        std::function<void(const uint64_t&)> newRandomSequenceCallback = nullptr;

        // Define the callback function for initialization attempts and failures
        std::function<void(const int, const std::string&)> initCallback = nullptr;

        // Define the logging mechanism (e.g., to a distributed logging system)
        std::function<void(const std::string&, const LogLevel)> logFunction;

        // Define the lock contention monitor for performance evaluation
        std::chrono::time_point<std::chrono::high_resolution_clock> lastLockContentionTime = std::chrono::high_resolution_clock::now();

        // Define the maximum allowable lock contention time (in seconds)
        const double maxLockContentionTime = 1.0;

        // Define the lock contention threshold (in percent of total time)
        const double lockContentionThreshold = 0.5;

        // Define the thread pool for entropy collection and callback execution
        std::vector<std::thread> entropyCollectionThreads;
        std::vector<std::thread> callbackExecutionThreads;

    public:
        SecureRandomGenerator(const size_t& numEntropySources, const SecurityMode& securityMode, const double& entropyCollectionRate, const size_t& cacheSize);
        ~SecureRandomGenerator();

        void addEntropySource(const EntropySourceType& type, const void* source);
        void setNewRandomSequenceCallback(const std::function<void(const uint64_t&)>& callback);
        void setInitCallback(const std::function<void(const int, const std::string&)>& callback);
        void setLogFunction(const std::function<void(const std::string&, const LogLevel)>& function);
        void removeEntropySource();
        bool generateRandomNumber(uint64_t* randomNumber, const size_t& rangeSize);
        bool generateFloatingPointNumber(float* randomFloat, const double& rangeMin, const double& rangeMax);
        bool generateIntegerNumber(int* randomInt, const int& rangeMin, const int& rangeMax);
};

SecureRandomGenerator::SecureRandomGenerator(const size_t& numEntropySources, const SecurityMode& securityMode, const double& entropyCollectionRate, const size_t& cacheSize) {
    // Initialize the entropy sources and current index to 0
    for (size_t i = 0; i < numEntropySources; ++i) {
        entropySources.push_back(std::make_pair(HRNG, nullptr));
    }

    // Set the security mode and entropy collection rate
    this->securityMode = securityMode;
    this->entropyCollectionRate = entropyCollectionRate;

    // Initialize the cache size and minimum/maximum values for each range
    this->cacheSize = cacheSize;
    minValues[0] = 0;
    maxValues[0] = (1 << 64) - 1;

    // Initialize the callback queues for each priority level
    for (const auto& priority : CallbackPriority) {
        callbackQueues[priority] = std::queue<std::function<void(const uint64_t&)>>();
    }
}

SecureRandomGenerator::~SecureRandomGenerator() {
    // Shut down the entropy collection and callback execution threads
    for (auto& thread : entropyCollectionThreads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
    for (auto& thread : callbackExecutionThreads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void SecureRandomGenerator::addEntropySource(const EntropySourceType& type, const void* source) {
    // Lock the mutex to ensure exclusive access to the entropy sources and current index
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Check if the entropy source is already present in the list of sources
    for (const auto& source : entropySources) {
        if (source.first == type && source.second == source) {
            return;
        }
    }

    // Add the new entropy source to the list of sources and update the current index
    entropySources.push_back(std::make_pair(type, source));
    currentIndex = entropySources.size() - 1;
}

void SecureRandomGenerator::setNewRandomSequenceCallback(const std::function<void(const uint64_t&)>& callback) {
    // Lock the mutex to ensure exclusive access to the new random sequence callback function
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Set the new random sequence callback function
    newRandomSequenceCallback = callback;
}

void SecureRandomGenerator::setInitCallback(const std::function<void(const int, const std::string&)>& callback) {
    // Lock the mutex to ensure exclusive access to the initialization callback function
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Set the initialization callback function
    initCallback = callback;
}

void SecureRandomGenerator::setLogFunction(const std::function<void(const std::string&, const LogLevel)>& function) {
    // Lock the mutex to ensure exclusive access to the logging mechanism
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Set the logging mechanism
    logFunction = function;
}

void SecureRandomGenerator::removeEntropySource() {
    // Lock the mutex to ensure exclusive access to the entropy sources and current index
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Remove the last entropy source from the list of sources and update the current index
    if (entropySources.size() > 0) {
        entropySources.pop_back();
        currentIndex = entropySources.size() - 1;
    }
}

bool SecureRandomGenerator::generateRandomNumber(uint64_t* randomNumber, const size_t& rangeSize) {
    // Lock the mutex to ensure exclusive access to the entropy sources and current index
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Check if there are any available entropy sources
    if (entropySources.size() == 0) {
        return false;
    }

    // Generate a random number from the current index in the list of sources
    *randomNumber = getRandomNumber(currentIndex, rangeSize);

    // Update the minimum/maximum values for each range in the cache
    updateMinMaxValues(rangeSize);

    // Execute the new random sequence callback function if it is not null
    if (newRandomSequenceCallback) {
        newRandomSequenceCallback(*randomNumber);
    }

    return true;
}

bool SecureRandomGenerator::generateFloatingPointNumber(float* randomFloat, const double& rangeMin, const double& rangeMax) {
    // Lock the mutex to ensure exclusive access to the entropy sources and current index
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Check if there are any available entropy sources
    if (entropySources.size() == 0) {
        return false;
    }

    // Generate a random floating-point number from the current index in the list of sources
    *randomFloat = getRandomFloatingPointNumber(currentIndex, rangeMin, rangeMax);

    // Update the minimum/maximum values for each range in the cache
    updateMinMaxValues((size_t)rangeSize);

    // Execute the new random sequence callback function if it is not null
    if (newRandomSequenceCallback) {
        newRandomSequenceCallback(*randomFloat);
    }

    return true;
}

bool SecureRandomGenerator::generateIntegerNumber(int* randomInt, const int& rangeMin, const int& rangeMax) {
    // Lock the mutex to ensure exclusive access to the entropy sources and current index
    std::lock_guard<std::mutex> lockGuard(mutex);

    // Check if there are any available entropy sources
    if (entropySources.size() == 0) {
        return false;
    }

    // Generate a random integer number from the current index in the list of sources
    *randomInt = getRandomIntegerNumber(currentIndex, rangeMin, rangeMax);

    // Update the minimum/maximum values for each range in the cache
    updateMinMaxValues((size_t)rangeSize);

    // Execute the new random sequence callback function if it is not null
    if (newRandomSequenceCallback) {
        newRandomSequenceCallback(*randomInt);
    }

    return true;
}

uint64_t SecureRandomGenerator::getRandomNumber(const size_t& index, const size_t& rangeSize) {
    // Generate a random number from the specified entropy source
    uint64_t randomValue = getEntropySourceValue(index);

    // Update the current index to the next available source in the list of sources
    if (++currentIndex == entropySources.size()) {
        currentIndex = 0;
    }

    // Return the random number modulo the specified range size
    return randomValue % rangeSize;
}

float SecureRandomGenerator::getRandomFloatingPointNumber(const size_t& index, const double& rangeMin, const double& rangeMax) {
    // Generate a random floating-point number from the specified entropy source
    uint64_t randomValue = getEntropySourceValue(index);

    // Update the current index to the next available source in the list of sources
    if (++currentIndex == entropySources.size()) {
        currentIndex = 0;
    }

    // Return the random number as a floating-point number between the specified range
    return (float)randomValue / (float)UINT64_MAX * (rangeMax - rangeMin) + rangeMin;
}

int SecureRandomGenerator::getRandomIntegerNumber(const size_t& index, const int& rangeMin, const int& rangeMax) {
    // Generate a random integer number from the specified entropy source
    uint64_t randomValue = getEntropySourceValue(index);

    // Update the current index to the next available source in the list of sources
    if (++currentIndex == entropySources.size()) {
        currentIndex = 0;
    }

    // Return the random number as an integer number between the specified range
    return (int)randomValue % ((rangeMax - rangeMin) + 1) + rangeMin;
}

void SecureRandomGenerator::updateMinMaxValues(const size_t& rangeSize) {
    // Update the minimum/maximum values for each range in the cache
    for (auto& it : cache) {
        auto& [range, minMax] = it;
        if (range == 0 || (size_t)range % rangeSize == 0) {
            minMax.min = INT32_MAX;
            minMax.max = INT32_MIN;
        } else {
            minMax.min = ((int)range - 1) / rangeSize * rangeSize + 1;
            minMax.max = (int)range / rangeSize * rangeSize;
        }
    }
}

uint64_t SecureRandomGenerator::getEntropySourceValue(const size_t& index) {
    // Get the entropy source value from the specified index
    uint64_t randomValue = 0;
    auto& entropySource = entropySources[index];

    switch (entropySource.first) {
        case RANDOM_BYTE:
            std::random_device device;
            randomValue = device();
            break;
        case RANDOM_WORD:
            std::random_device device;
            std::uniform_int_distribution<uint64_t> distribution(0, UINT64_MAX);
            randomValue = distribution(device);
            break;
        case RANDOM_DEVICE:
            int fd = open("/dev/random", O_RDONLY);
            if (fd < 0) {
                throw std::runtime_error("Error opening /dev/random");
            }
            read(fd, &randomValue, sizeof(uint64_t));
            close(fd);
            break;
    }

    // Update the cache with the new value
    auto& minMax = cache[rangeSize];
    if (minMax.min > randomValue) {
        minMax.min = randomValue;
    }
    if (minMax.max < randomValue) {
        minMax.max = randomValue;
    }

    return randomValue;
}']

