Here's an example of how this could be implemented in code:
```scss
// Import necessary dependencies
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const axios = require('axios');
const redis = require('redis');

// Set up Express app and middleware
const app = express();
app.use(bodyParser.json());
app.use(cors());

// Set up Redis client for caching
const redisClient = redis.createClient({ host: 'localhost', port: 6379 });

// Define JWT authentication middleware
function authenticateJWT(req, res, next) {
  const token = req.headers['authorization'];
  if (token) {
    try {
      // Verify JWT and get user ID from payload
      const decoded = jwt.verify(token, 'my-secret');
      const userId = decoded.sub;

      // Check if user is allowed to access profile
      if (req.user) {
        const { roles } = req.user;
        if (roles.includes('admin') || roles.includes('user')) {
          next();
        } else {
          res.status(401).json({ message: 'User not authorized' });
        }
      } else {
        // If user is not logged in, check if token is valid
        const cachedToken = await redisClient.get(`token:${token}`);
        if (cachedToken) {
          next();
        } else {
          res.status(401).json({ message: 'Invalid token' });
        }
      }
    } catch (error) {
      // Handle JWT verification errors
      console.log('Error verifying JWT', error);
      next(error);
    }
  } else {
    // If no token is provided, check if user is logged in
    if (req.user) {
      next();
    } else {
      res.status(401).json({ message: 'No JWT token provided' });
    }
  }
}

// Define route for getting profile data
app.get('/api/profile', authenticateJWT, async (req, res) => {
  const userId = req.user.id;

  // Check if profile is cached in Redis
  const cacheKey = `profile:${userId}`;
  const cachedProfile = await redisClient.get(cacheKey);
  if (cachedProfile) {
    res.json(JSON.parse(cachedProfile));
  } else {
    // If profile is not cached, fetch data from external API
    try {
      const response = await axios.get(`https://external-api.com/profile/${userId}`);
      const profileData = response.data;

      // Cache profile in Redis for future requests
      redisClient.set(cacheKey, JSON.stringify(profileData));

      res.json(profileData);
    } catch (error) {
      // Handle external API errors
      console.log('Error fetching profile data', error);
      next(error);
    }
  }
});

// Define route for updating profile data
app.put('/api/profile', authenticateJWT, async (req, res) => {
  const userId = req.user.id;
  const { firstName, lastName, email } = req.body;

  // Check if profile is cached in Redis
  const cacheKey = `profile:${userId}`;
  const cachedProfile = await redisClient.get(cacheKey);
  if (cachedProfile) {
    const updatedProfileData = JSON.parse(cachedProfile);
    updatedProfileData.firstName = firstName;
    updatedProfileData.lastName = lastName;
    updatedProfileData.email = email;

    // Update profile in Redis cache
    redisClient.set(cacheKey, JSON.stringify(updatedProfileData));
  } else {
    // If profile is not cached, fetch data from external API
    try {
      const response = await axios.get(`https://external-api.com/profile/${userId}`);
      const profileData = response.data;

      profileData.firstName = firstName;
      profileData.lastName = lastName;
      profileData.email = email;

      // Update profile in Redis cache
      redisClient.set(cacheKey, JSON.stringify(profileData));
    } catch (error) {
      // Handle external API errors
      console.log('Error updating profile data', error);
      next(error);
    }
  }
});
```
In this example, we define an Express app and set up middleware for handling JSON web tokens (JWT), CORS, and body parsing. We also set up a Redis client for caching profile data.

We define two routes: one for getting profile data and another for updating it. The GET route checks if the profile is cached in Redis, and if so, returns the cached data. If not, it fetches the data from an external API and caches it in Redis for future requests.

The PUT route updates the profile data by setting the `firstName`, `lastName`, and `email` fields to the values provided in the request body. It first checks if the profile is cached in Redis, and if so, updates the cached data. If not, it fetches the data from an external API, updates the data, and caches it in Redis for future requests.

We also define a `authenticateJWT` middleware function to handle JWT authentication and role-based permissions. This function verifies the JWT token provided in the request header and checks if the user is authorized to access the requested route. If the user is not logged in, it checks if the token is valid by checking the Redis cache.

This code is just an example, and you may need to adjust it to fit your specific use case."]

