use std::fs::File;
use std::io::BufReader;
use std::thread::sleep;
use std::time::Duration;
use std::collections::HashSet;

fn process_log(path: &str) -> (u64, u32) {
    let file = File::open(path).unwrap();
    let reader = BufReader::new(file);

    let mut transactions: HashSet<String> = HashSet::new();
    let mut total_weighted_sum = 0;
    let mut max_weighted_sum = 0;
    let mut transaction_id = "";

    for line in reader.lines() {
        let line = line.unwrap();

        if !line.starts_with("age") {
            continue;
        }

        let mut tokens: Vec<&str> = line.split(",").collect();

        // Remove the "age" token and parse the remaining tokens as integers
        tokens.remove(0);
        let age = tokens.iter().map(|t| t.parse::<u32>().unwrap()).sum::<u32>();
        if age < 3 {
            continue;
        }

        // Parse the transaction ID and weighted sum from the line
        let mut parts: Vec<&str> = line.split("=").collect();
        let id = parts[0].to_string();
        let weighted_sum = parts[1].parse::<u64>().unwrap();

        // Update the metrics and store the transaction ID if it has a higher weighted sum than previous ones
        total_weighted_sum += weighted_sum;
        transactions.insert(id.to_string());
        if weighted_sum > max_weighted_sum {
            max_weighted_sum = weighted_sum;
            transaction_id = id;
        }
    }

    // Return the maximum weighted sum and the corresponding transaction ID
    (max_weighted_sum, transaction_id)
}
```
