Here is a sample implementation of the modular, thread-safe octree data structure in C++ that supports dynamic resizing and integration with an external spatial indexing database:
```c++
#include <iostream>
#include <memory>
#include <vector>
#include <set>
#include <unordered_map>
#include <mutex>

class Octree {
public:
    // Constructor
    Octree() : root_(nullptr) {}

    // Destructor
    ~Octree() { clear(); }

    // Insert a new point into the octree
    void insert(const Point& p) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!root_) {
            root_ = std::make_shared<Node>(p);
        } else {
            Node* node = find_node(p, root_);
            if (node) {
                node->add_point(p);
            } else {
                // If the point is not in the octree, create a new node and add it
                root_ = std::make_shared<Node>(p, root_);
            }
        }
    }

    // Remove a point from the octree
    void remove(const Point& p) {
        std::lock_guard<std::mutex> lock(mutex_);
        Node* node = find_node(p, root_);
        if (node) {
            node->remove_point(p);
            // If the node is empty, remove it from the octree
            if (node->empty()) {
                root_ = nullptr;
            }
        }
    }

    // Find a point in the octree
    bool find(const Point& p) const {
        std::lock_guard<std::mutex> lock(mutex_);
        Node* node = find_node(p, root_);
        if (node) {
            return node->contains_point(p);
        } else {
            return false;
        }
    }

private:
    // Node structure for the octree
    struct Node {
        Point p_;         // Center point of the node
        double size_;     // Size of the node in all dimensions
        std::vector<Point> points_;  // List of points stored in this node
        std::shared_ptr<Node> children_[8];   // Pointers to child nodes

        Node(const Point& p, const double size) : p_(p), size_(size) {}

        ~Node() { clear(); }

        void add_point(const Point& p) { points_.push_back(p); }

        bool remove_point(const Point& p) {
            auto it = std::find(points_.begin(), points_.end(), p);
            if (it != points_.end()) {
                points_.erase(it);
                return true;
            } else {
                return false;
            }
        }

        bool contains_point(const Point& p) const {
            return std::find(points_.begin(), points_.end(), p) != points_.end();
        }

        void clear() { points_.clear(); }
    };

    // Find the node containing a given point
    Node* find_node(const Point& p, const std::shared_ptr<Node>& root) const {
        if (root->contains_point(p)) {
            return root.get();
        } else {
            for (int i = 0; i < 8; i++) {
                Node* child = find_node(p, root->children_[i]);
                if (child) {
                    return child;
                }
            }
            return nullptr;
        }
    }

    // Clear the octree
    void clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        root_ = nullptr;
    }

