// C++ Programming Task: Develop a scalable application to process large CSV files containing user activity logs
#include <iostream>
#include <fstream>
#include <string>
#include <chrono>
#include <unordered_map>
#include <vector>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

// Forward declarations
class LogEntry;
class LogProcessor;
class FileReader;
class MessageQueue;
class Analyzer;

// Struct to represent a single log entry
struct LogEntry {
    std::string userId;
    std::string eventType;
    std::chrono::system_clock::time_point timestamp;
    std::unordered_map<std::string, std::string> metadata;
};

// Struct to represent a worker thread for processing log entries
struct WorkerThread {
    std::thread thread;
    std::mutex mutex;
    std::condition_variable cv;
    bool stop = false;
};

// Class to read a CSV file and push log entries onto a message queue
class FileReader {
public:
    FileReader(const std::string& filename, MessageQueue* queue) : filename_(filename), queue_(queue) {}
    void operator()();
private:
    const std::string& filename_;
    MessageQueue* queue_;
};

// Class to process log entries and compute unique events per user within time windows
class Analyzer {
public:
    Analyzer(MessageQueue* queue, int numWorkers) : queue_(queue), numWorkers_(numWorkers) {}
    void operator()();
private:
    MessageQueue* queue_;
    std::unordered_map<std::string, std::vector<LogEntry>> uniqueEventsPerUser_; // map of unique events per user within time window
    int numWorkers_;                                              // number of worker threads to process log entries
};

// Class to manage message queue and workers for processing log entries
class LogProcessor {
public:
    LogProcessor(int numWorkers, MessageQueue* queue) : numWorkers_(numWorkers), queue_(queue) {}
    void start();
private:
    int numWorkers_;                                      // number of worker threads to process log entries
    MessageQueue* queue_;                                // message queue for passing log entries between workers and main thread
};

// Implementation of the FileReader class
void FileReader::operator()() {
    std::ifstream file(filename_);
    if (!file) {
        std::cerr << "Error: Could not open file '" << filename_ << "'" << std::endl;
        return;
    }

    // Read the CSV header and skip over it
    std::string line;
    std::getline(file, line);

    while (std::getline(file, line)) {
        // Extract fields from the current log entry and construct a LogEntry object
        LogEntry entry;
        std::stringstream ss(line);
        ss >> entry.userId >> entry.eventType >> entry.timestamp;

        // Add the log entry to the message queue for processing
        queue_->push(entry);
    }
}

// Implementation of the Analyzer class
void Analyzer::operator()() {
    while (true) {
        LogEntry entry = queue_->pop();

        // Check if the current user has any unique events in the specified time window
        auto it = uniqueEventsPerUser_.find(entry.userId);
        if (it == uniqueEventsPerUser_.end()) {
            // User has no unique events in the specified time window, add this event to the map
            uniqueEventsPerUser_[entry.userId].push_back(entry);
        } else {
            // User has unique events in the specified time window, check if this event is a new unique event
            bool found = false;
            for (const auto& e : it->second) {
                if (e.eventType == entry.eventType && e.timestamp == entry.timestamp) {
                    found = true;
                    break;
                }
            }

            // Add this event to the user's unique events if it is a new unique event
            if (!found) {
                it->second.push_back(entry);
            }
        }

        // Check if all workers have processed their messages, signal the condition variable if so
        if (--numWorkers_ == 0) {
            break;
        }
    }
}

// Implementation of the LogProcessor class
void LogProcessor::start() {
    for (int i = 0; i < numWorkers_; ++i) {
        WorkerThread worker;
        worker.thread = std::thread(Analyzer(queue_, numWorkers_));
        workers_.push_back(worker);
    }

    FileReader reader(filename_, queue_);
    std::thread readerThread(reader);

    // Wait for all worker threads to finish processing their messages
    for (auto& worker : workers_) {
        worker.cv.wait(worker.mutex, [&]() { return worker.stop; });
    }

    // Clean up resources
    readerThread.join();
}

int main() {
    const std::string filename = "user_activity_log.csv";
    MessageQueue queue;
    LogProcessor processor(10, &queue);
    processor.start();

    // Print unique events per user within time window to console
    for (const auto& pair : processor.getUniqueEventsPerUser()) {
        std::cout << "User ID: " << pair.first << std::endl;
        for (const auto& entry : pair.second) {
            std::cout << "\tEvent type: " << entry.eventType << ", Timestamp: " << entry.timestamp << std::endl;
        }
    }

    return 0;
}

// Implementation of the MessageQueue class
class MessageQueue {
public:
    void push(const LogEntry& entry);
    LogEntry pop();
private:
    std::queue<LogEntry> queue_; // message queue for passing log entries between workers and main thread
};

void MessageQueue::push(const LogEntry& entry) {
    std::lock_guard<std::mutex> lock(mutex_);
    queue_.push(entry);
}

LogEntry MessageQueue::pop() {
    std::lock_guard<std::mutex> lock(mutex_);
    LogEntry entry = queue_.front();
    queue_.pop();
    return entry;
}']

