static size_t nfapi_cr_indications_size = 0;
static pthread_mutex_t nfapi_cr_indications_lock = PTHREAD_MUTEX_INITIALIZER;

void initializeNfarxSite(const char *directory, const char *site_name) {
    // Validate the existence of a web.config file in the specified directory
    if (!validateWebConfigFile(directory)) {
        logError("Missing web.config file in %s", directory);
        return;
    }

