void* conversionThread(void* thread_data);
void printUsage();

int main(int argc, char** argv) {
    // Check the number of arguments
    if (argc < 3) {
        printf("Error: Incorrect number of arguments.\n");
        printUsage();
        return 1;
    }

    // Initialize the input and output directories
    char** input_dirs = argv + 1;
    char** output_dirs = argv + 2;
    int num_input_dirs = argc - 2;
    int num_output_dirs = argc - 2;

    // Check if the input and output directories are valid
    for (int i = 0; i < num_input_dirs; ++i) {
        DIR* dir = opendir(input_dirs[i]);
        if (!dir) {
            printf("Error: Input directory %s does not exist.\n", input_dirs[i]);
            return 1;
        }
    }
    for (int i = 0; i < num_output_dirs; ++i) {
        DIR* dir = opendir(output_dirs[i]);
        if (!dir) {
            printf("Error: Output directory %s does not exist.\n", output_dirs[i]);
            return 1;
        }
    }

    // Convert and process the directories in parallel
    convertAndProcessDirs(input_dirs, output_dirs, num_input_dirs, num_output_dirs);

    return 0;
}

void convertAndProcessDirs(char** input_dirs, char** output_dirs, int num_input_dirs, int num_output_dirs) {
    // Initialize the priority-based queue for managing conversion tasks
    PriorityQueue* task_queue = initPriorityQueue();

    // Create a thread pool for executing the conversions
    ThreadPool* thread_pool = createThreadPool(16);

    // Iterate over all input directories and enqueue conversion tasks for each file
    for (int i = 0; i < num_input_dirs; ++i) {
        DIR* dir = opendir(input_dirs[i]);
        struct dirent* entry;
        while ((entry = readdir(dir)) != NULL) {
            // Skip directories and hidden files
            if (entry->d_type == DT_DIR || entry->d_name[0] == '.') continue;

            // Create a new conversion task for the current file
            TaskInfo* task_info = createTaskInfo(input_dirs[i], output_dirs[i], entry->d_name);

            // Enqueue the task in the priority queue based on its priority
            enqueuePriorityQueue(task_queue, task_info, getPriority(task_info));
        }
    }

    // Wait for all conversion tasks to complete and destroy the thread pool
    waitThreadPool(thread_pool);
    destroyThreadPool(thread_pool);

    // Destroy the priority-based queue
    destroyPriorityQueue(task_queue);
}

void* conversionThread(void* thread_data) {
    ThreadData* td = (ThreadData*)thread_data;
    TaskInfo* task_info = td->task_info;

    // Perform the actual conversion using the external media processing library
    char* output_file = convertFile(task_info->input_file, task_info->format);

    // Check if the conversion was successful
    if (output_file == NULL) {
        printf("Error: Conversion failed for file %s.\n", task_info->input_file);
        return NULL;
    }

    // Enqueue the output file in the priority queue based on its priority
    enqueuePriorityQueue(td->sem, output_file, getPriority(task_info));

    return NULL;
}

void printUsage() {
    printf("Usage: BatchMediaConverter -i <input_dirs> -o <output_dirs>\n");
    printf("\t-f <format>: Specify the target format for conversion\n");
    printf("\t--manpage: Display usage information\n");
    printf("\t-c: Enable checksum verification\n");
    printf("\t-q: Quiet mode (only error messages are printed)\n");
    printf("\t-t <max_threads>: Set the maximum number of concurrent threads (default 16)\n");
}
