int64_t cache_timestamp = 0; // timestamp of the last cache update

// Main function
int main(int argc, char **argv) {
    int thread_count = 0; // number of threads to use for data processing
    bool rate_limit = false; // whether to enforce rate limiting
    bool burst_protection = false; // whether to enable burst protection
    if (argc < 3) {
        print_usage();
        exit(1);
    }
    thread_count = atoi(argv[2]);
    if (thread_count <= 0 || thread_count > MAX_THREADS) {
        fprintf(stderr, "Invalid number of threads: %d\n", thread_count);
        exit(1);
    }
    for (int i = 3; i < argc; ++i) {
        if (!strcmp(argv[i], "-rate-limit")) {
            rate_limit = true;
        } else if (!strcmp(argv[i], "-burst-protection")) {
            burst_protection = true;
        } else {
            fprintf(stderr, "Invalid argument: %s\n", argv[i]);
            exit(1);
        }
    }

    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigfillset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to set up signal handling", __LINE__);
        exit(1);
    }

    // Initialize caching mechanism
    if (update_cache(NULL)) {
        log_warning("Failed to initialize cache", __LINE__);
    }

    // Launch data processing threads
