    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, fetch_data, NULL)) {
            log_error("Failed to create data processing thread", __LINE__);
            exit(1);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < thread_count; ++i) {
        if (pthread_join(threads[i], NULL)) {
            log_error("Failed to join data processing thread", __LINE__);
            exit(1);
        }
    }

    // Clean up resources
    free(threads);

    return 0;
}

// Function definitions
