class GPIO {
  public:
    virtual ~GPIO() {}

    // Set GPIO pin mode
    virtual void setMode(uint8_t pin, uint8_t mode) = 0;

    // Write to GPIO pin
    virtual void write(uint8_t pin, bool value) = 0;

    // Read from GPIO pin
    virtual bool read(uint8_t pin) = 0;
};

class I2C {
  public:
    virtual ~I2C() {}

    // Set I2C device address
    virtual void setAddress(uint8_t addr) = 0;

    // Write to I2C device
    virtual void write(std::vector<uint8_t> data) = 0;

    // Read from I2C device
    virtual std::vector<uint8_t> read() = 0;
};

class GPIOI2CController {
  public:
    GPIOI2CController(std::vector<GPIO*> gpios, std::vector<I2C*> i2cs) : gpios_(gpios), i2cs_(i2cs) {}

    ~GPIOI2CController() {
      for (auto gpio : gpios_) {
        delete gpio;
      }
      for (auto i2c : i2cs_) {
        delete i2c;
      }
    }

    void setMode(uint8_t pin, uint8_t mode) {
      for (auto gpio : gpios_) {
        if (gpio->getPin() == pin) {
          gpio->setMode(mode);
          break;
        }
      }
    }

    void write(uint8_t pin, bool value) {
      for (auto gpio : gpios_) {
        if (gpio->getPin() == pin) {
          gpio->write(value);
          break;
        }
      }
    }

    bool read(uint8_t pin) {
      for (auto gpio : gpios_) {
        if (gpio->getPin() == pin) {
          return gpio->read();
        }
      }
      throw std::invalid_argument("Pin does not exist");
    }

    void setAddress(uint8_t addr) {
      for (auto i2c : i2cs_) {
        if (i2c->getAddress() == addr) {
          i2c->setAddress(addr);
          break;
        }
      }
    }

    void write(std::vector<uint8_t> data) {
      for (auto i2c : i2cs_) {
        i2c->write(data);
      }
    }

    std::vector<uint8_t> read() {
      for (auto i2c : i2cs_) {
        return i2c->read();
      }
      throw std::invalid_argument("No I2C devices found");
    }

  private:
    std::vector<GPIO*> gpios_;
    std::vector<I2C*> i2cs_;
};
```
