import java.util.concurrent.*;
import java.util.logging.*;

public class IoTDataAggregator {
  private static final Logger LOGGER = Logger.getLogger(IoTDataAggregator.class.getName());
  private static final int DEFAULT_PRIORITY_QUEUE_SIZE = 100;
  private static final int DEFAULT_MAX_CONCURRENT_JOBS = 5;
  private static final int DEFAULT_MAX_WORKER_THREADS = 20;
  private static final int DEFAULT_MAX_BATCH_SIZE = 100;
  private static final int DEFAULT_BATCH_INTERVAL = 300; // in milliseconds
  private static final int DEFAULT_CACHE_SIZE = 5000;
  private static final int DEFAULT_RETRY_COUNT = 3;
  private static final int DEFAULT_TIMEOUT = 60; // in seconds
  private static final int DEFAULT_MAX_CONNECTIONS = 100;
  private static final int DEFAULT_MAX_CONNECTION_TTL = 300; // in seconds

  private final PriorityQueue<DataJob> priorityQueue = new PriorityQueue<>(DEFAULT_PRIORITY_QUEUE_SIZE);
  private final ExecutorService executorService = Executors.newFixedThreadPool(DEFAULT_MAX_WORKER_THREADS);
  private final Map<String, DataCache> dataCacheMap = new HashMap<>();
  private final Set<DataJob> runningJobs = Collections.synchronizedSet(new HashSet<>());

  public IoTDataAggregator() {
    // Initialize the cache and priority queue
    for (int i = 0; i < DEFAULT_CACHE_SIZE; i++) {
      dataCacheMap.put("cache-" + i, new DataCache());
    }
  }

  public void addDataJob(String jobName, String sensorId, int batchSize, long batchInterval) {
    // Add a new data job to the priority queue
    DataJob job = new DataJob(jobName, sensorId, batchSize, batchInterval);
    if (!runningJobs.contains(job)) {
      runningJobs.add(job);
      executorService.execute(() -> runDataJob(job));
    }
  }

  private void runDataJob(DataJob job) {
    // Run a data job in a separate thread
    try {
      while (true) {
        DataCache cache = dataCacheMap.get(job.sensorId);
        if (cache == null || cache.isEmpty()) {
          Thread.sleep(DEFAULT_BATCH_INTERVAL);
          continue;
        }

        // Process the data in batches
        while (!cache.isEmpty() && !runningJobs.contains(job)) {
          DataBatch batch = new DataBatch(job, cache.poll(batchSize));
          LOGGER.info("Processing data batch for job " + job.jobName);
          processDataBatch(batch);
        }
      }
    } catch (InterruptedException e) {
      LOGGER.severe("Thread interrupted while running data job: " + job.jobName);
    } finally {
      runningJobs.remove(job);
    }
  }

  private void processDataBatch(DataBatch batch) {
    // Process a single data batch
    try {
      for (int i = 0; i < batch.size(); i++) {
        DataPoint point = batch.get(i);
        LOGGER.info("Processing data point: " + point);
        // Implement your own data processing logic here
      }
    } catch (Exception e) {
      LOGGER.severe("Error while processing data batch: " + batch, e);
    }
  }
}
```
