// Modular cryptographic toolkit for secure communications across Windows, macOS, and Linux environments

import java.util.*;
import java.security.*;
import javax.crypto.*;
import javax.net.ssl.*;

public class CryptographyToolkit {
  // Setup module: configure key management and communication channels
  private KeyManager keyManager;
  private ChannelManager channelManager;

  public CryptographyToolkit() {
    keyManager = new KeyManager();
    channelManager = new ChannelManager(keyManager);
  }

  // AES module: encrypt, decrypt, and generate keys
  public class AESCipher extends Cipher {
    private SecretKey secretKey;

    public AESCipher(SecretKey secretKey) {
      this.secretKey = secretKey;
    }

    public byte[] encrypt(byte[] plaintext) throws NoSuchAlgorithmException, InvalidKeyException {
      Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
      cipher.init(Cipher.ENCRYPT_MODE, secretKey);
      return cipher.doFinal(plaintext);
    }

    public byte[] decrypt(byte[] ciphertext) throws NoSuchAlgorithmException, InvalidKeyException {
      Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
      cipher.init(Cipher.DECRYPT_MODE, secretKey);
      return cipher.doFinal(ciphertext);
    }

    public SecretKey generateKey() throws NoSuchAlgorithmException {
      return new SecretKeySpec("".getBytes(), "AES");
    }
  }

  // RSA module: encrypt, decrypt, and sign data using the RSA algorithm
  public class RSACipher extends Cipher {
    private PublicKey publicKey;
    private PrivateKey privateKey;

    public RSACipher(PublicKey publicKey, PrivateKey privateKey) {
      this.publicKey = publicKey;
      this.privateKey = privateKey;
    }

    public byte[] encrypt(byte[] plaintext) throws NoSuchAlgorithmException, InvalidKeyException {
      Cipher cipher = Cipher.getInstance("RSA/ECB/OAEPWithSHA-256AndMGF1Padding");
      cipher.init(Cipher.ENCRYPT_MODE, publicKey);
      return cipher.doFinal(plaintext);
    }

    public byte[] decrypt(byte[] ciphertext) throws NoSuchAlgorithmException, InvalidKeyException {
      Cipher cipher = Cipher.getInstance("RSA/ECB/OAEPWithSHA-256AndMGF1Padding");
      cipher.init(Cipher.DECRYPT_MODE, privateKey);
      return cipher.doFinal(ciphertext);
    }

    public byte[] sign(byte[] data) throws NoSuchAlgorithmException, InvalidKeyException {
      Signature signature = Signature.getInstance("SHA256withRSA");
      signature.initSign(privateKey);
      return signature.sign();
    }

    public boolean verify(byte[] data, byte[] signature) throws NoSuchAlgorithmException, InvalidKeyException {
      Signature signature = Signature.getInstance("SHA256withRSA");
      signature.initVerify(publicKey);
      return signature.verify(signature);
    }
  }

  // ECC module: encrypt, decrypt, and sign data using the ECDH or ECDSA algorithms
  public class ECSCipher extends Cipher {
    private PublicKey publicKey;
    private PrivateKey privateKey;

    public ECSCipher(PublicKey publicKey, PrivateKey privateKey) {
      this.publicKey = publicKey;
      this.privateKey = privateKey;
    }

    public byte[] encrypt(byte[] plaintext) throws NoSuchAlgorithmException, InvalidKeyException {
      Cipher cipher = Cipher.getInstance("ECDH");
      cipher.init(Cipher.ENCRYPT_MODE, publicKey);
      return cipher.doFinal(plaintext);
    }

    public byte[] decrypt(byte[] ciphertext) throws NoSuchAlgorithmException, InvalidKeyException {
      Cipher cipher = Cipher.getInstance("ECDH");
      cipher.init(Cipher.DECRYPT_MODE, privateKey);
      return cipher.doFinal(ciphertext);
    }

    public byte[] sign(byte[] data) throws NoSuchAlgorithmException, InvalidKeyException {
      Signature signature = Signature.getInstance("ECDSA");
      signature.initSign(privateKey);
      return signature.sign();
    }

    public boolean verify(byte[] data, byte[] signature) throws NoSuchAlgorithmException, InvalidKeyException {
      Signature signature = Signature.getInstance("ECDSA");
      signature.initVerify(publicKey);
      return signature.verify(signature);
    }
  }

  // TLS module: establish secure connections using the TLS 1.3 protocol
  public class TLSCipher extends Cipher {
    private SSLContext sslContext;

    public TLSCipher() throws NoSuchAlgorithmException, KeyManagementException {
      this.sslContext = SSLContext.getInstance("TLSv1.3");
      sslContext.init(null, null, new SecureRandom());
    }

    public SSLEngine createSSLEngine() {
      return sslContext.createSSLEngine();
    }
  }

  // Utility methods for managing keys and communication channels
  private class KeyManager {
    private Map<String, SecretKey> secretKeys;
    private Map<String, PublicKey> publicKeys;

    public KeyManager() {
      this.secretKeys = new HashMap<>();
      this.publicKeys = new HashMap<>();
    }

    public void generateKey(String keyType) throws NoSuchAlgorithmException {
      switch (keyType) {
        case "AES":
          secretKeys.put("AES", AESCipher.generateKey());
          break;
        case "RSA":
          RSACipher rsaCipher = new RSACipher();
          publicKeys.put("RSA", rsaCipher.getPublicKey());
          secretKeys.put("RSA", rsaCipher.getPrivateKey());
          break;
        case "ECDH":
          ECSCipher ecCipher = new ECSCipher();
          publicKeys.put("ECDH", ecCipher.getPublicKey());
          secretKeys.put("ECDH", ecCipher.getPrivateKey());
          break;
        case "ECDSA":
          ECSCipher ecdsaCipher = new ECSCipher();
          publicKeys.put("ECDSA", ecdsaCipher.getPublicKey());
          secretKeys.put("ECDSA", ecdsaCipher.getPrivateKey());
          break;
      }
    }

    public SecretKey getSecretKey(String keyType) {
      return secretKeys.get(keyType);
    }

    public PublicKey getPublicKey(String keyType) {
      return publicKeys.get(keyType);
    }
  }

  private class CommunicationChannelManager {
    private Map<String, SSLEngine> sslEngines;

    public CommunicationChannelManager() {
      this.sslEngines = new HashMap<>();
    }

    public void establishConnection(String keyType) throws NoSuchAlgorithmException, KeyManagementException {
      TLSCipher tlsCipher = new TLSCipher();
      SSLEngine sslEngine = tlsCipher.createSSLEngine();
      sslEngines.put(keyType, sslEngine);
    }

    public SSLEngine getSSLEngine(String keyType) {
      return sslEngines.get(keyType);
    }
  }

  // Utility methods for managing the cryptographic operations
  private class CryptographicOperationManager {
    private Map<String, Cipher> ciphers;

    public CryptographicOperationManager() {
      this.ciphers = new HashMap<>();
    }

    public void encrypt(byte[] plaintext, String keyType) throws NoSuchAlgorithmException, InvalidKeyException {
      switch (keyType) {
        case "AES":
          AESCipher aesCipher = new AESCipher();
          ciphers.put("AES", aesCipher.encrypt(plaintext));
          break;
        case "RSA":
          RSACipher rsaCipher = new RSACipher();
          ciphers.put("RSA", rsaCipher.encrypt(plaintext));
          break;
        case "ECDH":
          ECSCipher ecCipher = new ECSCipher();
          ciphers.put("ECDH", ecCipher.encrypt(plaintext));
          break;
        case "ECDSA":
          ECSCipher ecdsaCipher = new ECSCipher();
          ciphers.put("ECDSA", ecdsaCipher.encrypt(plaintext));
          break;
      }
    }

    public byte[] decrypt(byte[] ciphertext, String keyType) throws NoSuchAlgorithmException, InvalidKeyException {
      switch (keyType) {
        case "AES":
          AESCipher aesCipher = new AESCipher();
          return aesCipher.decrypt(ciphertext);
        case "RSA":
          RSACipher rsaCipher = new RSACipher();
          return rsaCipher.decrypt(ciphertext);
        case "ECDH":
          ECSCipher ecCipher = new ECSCipher();
          return ecCipher.decrypt(ciphertext);
        case "ECDSA":
          ECSCipher ecdsaCipher = new ECSCipher();
          return ecdsaCipher.decrypt(ciphertext);
      }
    }
  }
}
```
The `KeyManager` class is responsible for managing the keys used in the cryptographic operations, and provides methods for generating and retrieving secret keys, as well as public keys. The `CommunicationChannelManager` class is responsible for establishing connections between parties using SSL/TLS, and provides methods for getting an `SSLEngine` instance for a specific key type. Finally, the `CryptographicOperationManager` class is responsible for performing cryptographic operations, such as encrypting and decrypting data, and provides methods for doing so using different key types.

The `KeyManager` class has a map of secret keys, where each key is identified by its corresponding key type (e.g., "AES", "RSA", etc.). It also has a map of public keys, where each key is identified by its corresponding key type. The `generateKey` method takes a string argument that specifies the key type and generates a new secret key for it. The `getSecretKey` method returns the secret key for the specified key type, or null if there is no such key. The `getPublicKey` method returns the public key for the specified key type, or null if there is no such key.

The `CommunicationChannelManager` class has a map of SSL/TLS engines, where each engine is identified by its corresponding key type. The `establishConnection` method takes a string argument that specifies the key type and establishes a new connection using SSL/TLS for it. The `getSSLEngine` method returns an `SSLEngine` instance for the specified key type, or null if there is no such engine.

The `CryptographicOperationManager` class has a map of ciphers, where each cipher is identified by its corresponding key type. The `encrypt` method takes a byte array argument that specifies the plaintext and encrypts it using the specified key type. The `decrypt` method takes a byte array argument that specifies the ciphertext and decrypts it using the specified key type.

This implementation uses the Java Cryptography Architecture (JCA) to perform the cryptographic operations, which provides a high-level API for doing so. The JCA is responsible for managing the cryptographic operations, including generating and retrieving keys, establishing connections between parties, and performing encryption and decryption.

This implementation also uses the Java Secure Socket Extension (JSSE) to perform SSL/TLS connections, which provides a high-level API for doing so. The JSSE is responsible for managing the SSL/TLS connections, including establishing new connections and managing existing ones.

This implementation does not handle key exchange or authentication between parties in a secure way. It is up to the user of this library to ensure that keys are properly exchanged and authenticated using a secure method such as Diffie-Hellman or Elliptic Curve Cryptography.']

