                stmt.setInt(3, crc_indications[i].crc_indication_rel8_tag);
                stmt.setBoolean(4, crc_indications[i].crcflag);
                stmt.addBatch();
            }
            stmt.executeBatch();
            db.close();
            break;
        } catch (Exception e) {
