// Define the linked list structure for holding the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct NFAPI_CRC_INDICATION_PDU_LIST_T *next;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Define the function for generating and persisting CRC indications
void generateAndPersistCrcIndications(uint32_t num_elements) {
    // Check if the input parameter is within the valid range
    if (num_elements < 1 || num_elements > 10000000) {
        printf("Invalid number of elements: %d\n", num_elements);
        return;
    }

    // Declare variables for tracking the CRC indication data and the linked list
    NFAPI_CRC_INDICATION_PDU_LIST_T *crc_indication_list = NULL;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication = NULL;

    // Generate the CRC indications and populate the linked list
    for (uint32_t i = 0; i < num_elements; i++) {
        crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_indication) {
            printf("Failed to allocate memory for CRC indication\n");
            return;
        }

        // Set the random CRCFLAG value
        crc_indication->crci = (uint8_t)(rand() % 256);

        // Set the other fields in the structure to some arbitrary values
        crc_indication->rx_ue_information_tag = i;
        crc_indication->rnti = (uint16_t)((i * 100) % 200);
        crc_indication->crc_indication_rel8_tag = (uint8_t)(i % 5);

        // Add the CRC indication to the linked list
        if (!crc_indication_list) {
            crc_indication_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));
            if (!crc_indication_list) {
                printf("Failed to allocate memory for CRC indication list\n");
                free(crc_indication);
                return;
            }
            crc_indication_list->data = crc_indication;
            crc_indication_list->next = NULL;
        } else {
            crc_indication_list->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));
            if (!crc_indication_list->next) {
                printf("Failed to allocate memory for CRC indication list\n");
                free(crc_indication);
                return;
            }
            crc_indication_list = crc_indication_list->next;
            crc_indication_list->data = crc_indication;
            crc_indication_list->next = NULL;
        }
    }

    // Persist the linked list of CRC indications to some external storage
    printf("Persisting %d CRC indications\n", num_elements);
}
