// Define constants for network latency, packet loss, and duplicate frame handling
#define NETWORK_LATENCY 10 // milliseconds
#define PACKET_LOSS_RATE 0.05
#define DUPLICATE_FRAMES_RATE 0.01

// Define structure for storing Rx frames
typedef struct {
    uint32_t ue_id;
    uint8_t rnti;
    bool crc_status;
} frame_t;

// Function to simulate network latency, packet loss, and duplicate frame handling
void processRxFrames(nfapi_rx_indication_t *rx_ind) {
    // Calculate the number of frames to be processed based on the input parameter
    int num_frames = rx_ind->num_of_pdus;

    // Allocate memory for storing the Rx frames
    frame_t *frames = (frame_t *)malloc(sizeof(frame_t) * num_frames);
    if (!frames) {
        printf("Error: Failed to allocate memory for Rx frames\n");
        return;
    }

    // Simulate network latency, packet loss, and duplicate frame handling
    for (int i = 0; i < num_frames; i++) {
        // Simulate network latency
        usleep(NETWORK_LATENCY * 1000);

        // Check if the frame should be dropped due to packet loss
        if ((double)rand() / RAND_MAX < PACKET_LOSS_RATE) {
            continue;
        }

        // Store the received frame in the allocated memory
        frames[i].ue_id = rx_ind->ue_id[i];
        frames[i].rnti = rx_ind->rnti[i];
        frames[i].crc_status = rx_ind->crc_status[i];
    }

    // Merge duplicate frames by merging their CRC indications
    for (int i = 0; i < num_frames - 1; i++) {
        if (frames[i].rnti == frames[i + 1].rnti) {
            frames[i].crc_status |= frames[i + 1].crc_status;
            frames[i + 1] = {}; // Clear the duplicate frame
        }
    }

    // Log all successful and failed operations, including timestamps and detailed error codes
    for (int i = 0; i < num_frames; i++) {
        if (frames[i].crc_status) {
            printf("Rx frame %d with UE ID %u and RNTI %u successfully received\n", i, frames[i].ue_id, frames[i].rnti);
        } else {
            printf("Failed to receive Rx frame %d: CRC check failed\n", i);
        }
    }

    // Export the processed frames in a specified format (e.g., JSON, CSV) for further processing by external systems
    exportFrames(frames, num_frames);

    free(frames);
}

