  char *event_type; // Type of event (e.g., "cell_change", "signal_strength")
  int timestamp; // Timestamp of the event
  double value; // Value of the event (e.g., signal strength)
} NetworkEvent;

// Struct to represent the linked list of network events
typedef struct EventList {
  NetworkEvent *head;
  NetworkEvent *tail;
  int size;
  pthread_mutex_t lock; // Mutex for protecting access to the list
} EventList;

// Function to create a new linked list
EventList *create_event_list() {
  EventList *list = malloc(sizeof(EventList));
  list->head = NULL;
  list->tail = NULL;
  list->size = 0;
  pthread_mutex_init(&list->lock, NULL);
  return list;
}

// Function to add a new event to the linked list
