#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_FRAMES 1024 // Configurable input parameter for max number of frames to handle
#define LOGGING_BUFFER_SIZE 1024 * 1024 * 10 // 10 MB buffer size for logging

// Logging macros
#define log_info(format, ...) printf("[INFO] " format "\n", ##__VA_ARGS__)
#define log_error(format, ...) printf("[ERROR] " format "\n", ##__VA_ARGS__)
#define log_warning(format, ...) printf("[WARNING] " format "\n", ##__VA_ARGS__)

// Frame structure to store UE information and CRC indication status
struct frame {
    int ue_id; // Unique UE identifier
    char rnti[16]; // RNTI of the UE
    unsigned char crc_status; // CRC indication status (0 = OK, 1 = ERROR)
};

// Memory pool for dynamically allocating frames
struct frame *frame_pool;
int num_frames = 0;

// Lock for protecting access to the frame pool
pthread_mutex_t frame_pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the frame pool with a certain number of frames
void init_frame_pool(int num_frames) {
    frame_pool = (struct frame *) malloc(num_frames * sizeof(struct frame));
    if (!frame_pool) {
        log_error("Failed to allocate memory for frame pool");
        return;
    }
    this->num_frames = num_frames;
}

// Add a new frame to the pool and return its index
int add_frame(struct frame *new_frame) {
    pthread_mutex_lock(&frame_pool_lock);
    if (num_frames == MAX_FRAMES) {
        log_warning("Maximum number of frames reached, dropping new frame");
        return -1;
    }
    int index = num_frames++;
    memcpy(frame_pool + index, new_frame, sizeof(struct frame));
    pthread_mutex_unlock(&frame_pool_lock);
    return index;
}

// Remove a frame from the pool and return its index
int remove_frame(int index) {
    if (index >= num_frames) {
        log_error("Invalid frame index");
        return -1;
    }
    pthread_mutex_lock(&frame_pool_lock);
    struct frame *removed_frame = frame_pool + index;
    memset(removed_frame, 0, sizeof(struct frame));
    num_frames--;
    pthread_mutex_unlock(&frame_pool_lock);
    return index;
}

// Get a frame from the pool by its index
struct frame *get_frame(int index) {
    if (index >= num_frames) {
        log_error("Invalid frame index");
        return NULL;
    }
    return frame_pool + index;
}

// Process an Rx frame from the NFAPI interface and update the UE information
void processRxFrame(struct nfapi_msg *rx_frame) {
    struct frame new_frame = {};
    new_frame.ue_id = rx_frame->header.ue_id;
    new_frame.rnti = rx_frame->payload.rnti;
    new_frame.crc_status = rx_frame->payload.crc_indication;
    int index = add_frame(&new_frame);
    if (index < 0) {
        log_warning("Failed to add frame to pool, dropping");
        return;
    }
}

// Main function for the thread that handles Rx frames
void *rx_thread(void *args) {
    // Read data from NFAPI interface and process it in a loop
    while (1) {
        struct nfapi_msg rx_frame;
        read(nfapi_fd, &rx_frame, sizeof(struct nfapi_msg));
        processRxFrame(&rx_frame);
    }
}

// Main function for the thread that handles data export to external systems
void *export_thread(void *args) {
    // Create a socket and connect it to the data analytics platform
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        log_error("Failed to create socket");
        return;
    }
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // Replace with actual port number
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr); // Replace with actual IP address
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_error("Failed to connect socket");
        return;
    }
    // Loop indefinitely and send data to the analytics platform
    while (1) {
        struct frame *frame = get_frame(0); // Replace with actual index
        if (!frame) {
            log_warning("No frames available for export");
            continue;
        }
        char buffer[LOGGING_BUFFER_SIZE];
        int bytes_written = snprintf(buffer, LOGGING_BUFFER_SIZE, "UE %d: RNTI %s, CRC status %u\n", frame->ue_id, frame->rnti, frame->crc_status);
        if (bytes_written < 0) {
            log_error("Failed to write export data");
            continue;
        }
        send(sock, buffer, bytes_written, 0);
    }
}

// Main function for the thread that handles UE information logging
void *log_thread(void *args) {
    // Create a log file and open it in append mode
    FILE *log_file = fopen("ue_info.log", "a+");
    if (!log_file) {
        log_error("Failed to create log file");
        return;
    }
    struct frame *frame = get_frame(0); // Replace with actual index
    if (!frame) {
        log_warning("No frames available for logging");
        fclose(log_file);
        return;
    }
    char buffer[LOGGING_BUFFER_SIZE];
    int bytes_written = snprintf(buffer, LOGGING_BUFFER_SIZE, "UE %d: RNTI %s, CRC status %u\n", frame->ue_id, frame->rnti, frame->crc_status);
    if (bytes_written < 0) {
        log_error("Failed to write log data");
        fclose(log_file);
        return;
    }
    fwrite(buffer, bytes_written, 1, log_file);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    init_nfapi(); // Initialize the NFAPI interface
    int nfapi_fd = get_nfapi_fd(); // Get the file descriptor for the NFAPI interface
    if (nfapi_fd < 0) {
        log_error("Failed to open NFAPI interface");
        return -1;
    }
    pthread_t rx_thread_id, export_thread_id, log_thread_id;
    // Create the Rx thread and start it in a loop
    if (pthread_create(&rx_thread_id, NULL, rx_thread, NULL)) {
        log_error("Failed to create Rx thread");
        return -1;
    }
    // Create the export thread and start it in a loop
    if (pthread_create(&export_thread_id, NULL, export_thread, NULL)) {
        log_error("Failed to create export thread");
        return -1;
    }
    // Create the logging thread and start it in a loop
    if (pthread_create(&log_thread_id, NULL, log_thread, NULL)) {
        log_error("Failed to create log thread");
        return -1;
    }
    // Wait for all threads to finish before exiting the program
    pthread_join(rx_thread_id, NULL);
    pthread_join(export_thread_id, NULL);
    pthread_join(log_thread_id, NULL);
    return 0;
}
