            rules.Add(password => password.Length >= 8);
            rules.Add(password => Regex.IsMatch(password, @"[A-Z]"));
            rules.Add(password => Regex.IsMatch(password, @"[a-z]"));
            rules.Add(password => Regex.IsMatch(password, @"[0-9]"));
            foreach (var rule in rules)
            {
                if (!rule(password))
                {
                    return false;
                }
            }

            // Check if the password is unique and not part of a breached database
