// C function prototype
NFAPI_CRC_INDICATION_PDU_T* populateNFAPICRCIndications(int N, int seed, NFAPI_CONFIG_t config);

// Memory pool implementation for custom allocations
struct memoryPool {
    void* head;
    size_t size;
    size_t capacity;
};

// Function to create a new memory pool with the given capacity
struct memoryPool* createMemoryPool(size_t capacity) {
    struct memoryPool* pool = (struct memoryPool*) malloc(sizeof(struct memoryPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->head = NULL;
    pool->size = 0;
    pool->capacity = capacity;
    return pool;
}

// Function to allocate a new element from the pool, returns NULL if no elements available
void* memoryPoolAlloc(struct memoryPool* pool) {
    if (pool == NULL || pool->head == NULL) {
        return NULL;
    }
    void* node = pool->head;
    pool->head = node->next;
    pool->size--;
    return node;
}

// Function to free an element back into the pool, does not deallocate memory
void memoryPoolFree(struct memoryPool* pool, void* node) {
    if (pool == NULL || node == NULL) {
        return;
    }
    ((struct memoryNode*)node)->next = pool->head;
    pool->head = node;
    pool->size++;
}

// Function to allocate a new element from the pool, returns NULL if no elements available
NFAPI_CRC_INDICATION_PDU_T* memoryPoolAllocNFAPICRCIndication(struct memoryPool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*) memoryPoolAlloc(pool);
    if (pdu == NULL) {
        return NULL;
    }
    memset(&pdu->RX_UE_INFORMATION, 0, sizeof(NFAPI_RX_UE_INFORMATION_TAG));
    pdu->RX_UE_INFORMATION.RNTI = rand();
    pdu->RX_UE_INFORMATION.CRC_INDICATION_REL8_TAG = rand();
