void memoryPoolFreeNFAPICRCIndication(struct memoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pool == NULL || pdu == NULL) {
        return;
    }
    memset(&pdu->RX_UE_INFORMATION, 0, sizeof(NFAPI_RX_UE_INFORMATION_TAG));
