typedef struct State {
    int id;
    char* name;
} State;

typedef struct MemoryPool {
    size_t capacity;
    size_t used;
    size_t free;
    void* buffer;
} MemoryPool;

typedef struct Event {
    int stateId;
    char* eventName;
} Event;

typedef struct StateList {
    State** states;
    int count;
    sem_t lock;
} StateList;

void initStateList(StateList* list) {
    list->count = 0;
    list->states = malloc(STATE_LIST_SIZE * sizeof(State*));
    assert(list->states != NULL);
    sem_init(&list->lock, 0, 1);
}

void destroyStateList(StateList* list) {
    free(list->states);
    sem_destroy(&list->lock);
}

int addStateToList(StateList* list, State* state) {
    if (list->count == STATE_LIST_SIZE) {
        return -1; // State list is full
    }
    sem_wait(&list->lock);
    list->states[list->count] = state;
    list->count++;
    sem_post(&list->lock);
    return 0;
}

State* getStateFromList(StateList* list, int id) {
    for (int i = 0; i < list->count; i++) {
        if (list->states[i]->id == id) {
            return list->states[i];
        }
    }
    return NULL; // State not found
}

void updateNextPointer(StateList* list, int prevId, int newId) {
    sem_wait(&list->lock);
    State* prevState = getStateFromList(list, prevId);
    if (prevState == NULL) {
        return; // Previous state not found
    }
    State* newState = getStateFromList(list, newId);
    if (newState == NULL) {
        return; // New state not found
    }
    prevState->next = newState;
    sem_post(&list->lock);
}

