namespace nas_processor {
  /**
   * NASProcessor class for processing Network Access Stratum (NAS) Protocol Data Units (PDUs) in a dynamic LTE network environment.
   */
  class NASProcessor {
    private:
      std::queue<pdu_t> pdu_queue_; // queue of PDUs to be processed
      std::mutex mutex_; // mutex for protecting the queue
      std::condition_variable cv_; // condition variable for notifying threads of new PDUs
      bool terminate_; // flag indicating whether to terminate the processing loop
      std::atomic<int> num_threads_; // number of active processing threads
      std::map<pdu_key_t, pdu_t> processed_pdus_; // map of processed PDUs for deduplication
      db::DBManager db_manager_; // database manager for inserting/querying PDUs
      util::ThreadPool thread_pool_; // thread pool for processing PDUs concurrently
      std::vector<std::pair<pdu_t, error_code>> failed_pdus_; // vector of failed PDUs and associated errors

    public:
      NASProcessor(const db::DBManager& db_manager) :
        pdu_queue_(), mutex_(), cv_(), terminate_(false), num_threads_(0), processed_pdus_(), db_manager_(db_manager), thread_pool_(), failed_pdus_() {
          // initialize the processor with an empty queue and a DB manager
      }

      ~NASProcessor() {
        // terminate the processing loop and join all threads
        terminate_ = true;
        thread_pool_.stop();
      }

      void process(pdu_t pdu) {
        // add PDU to the queue for processing
        std::lock_guard<std::mutex> lock(mutex_);
        if (!terminate_) {
          pdu_queue_.push(pdu);
          cv_.notify_one();
        }
      }

    private:
      void processPDUs() {
        // process PDUs in the queue concurrently using a thread pool
        while (!terminate_) {
          std::unique_lock<std::mutex> lock(mutex_);
          cv_.wait(lock, [this] { return !pdu_queue_.empty() || terminate_; });
          if (terminate_) break;

          // process PDUs until the queue is empty or we reach the maximum number of threads
          while (!pdu_queue_.empty() && num_threads_ < max_num_threads) {
            pdu_t pdu = pdu_queue_.front();
            pdu_queue_.pop();
            lock.unlock();

            // check if the PDU has already been processed
            if (processed_pdus_.find(pdu.getKey()) == processed_pdus_.end()) {
              // insert the PDU into the database and update the map of processed PDUs
              db::DBResult result = db_manager_.insertPDU(pdu);
              if (result == db::OK) {
                processed_pdus_.emplace(pdu.getKey(), pdu);
              } else if (result == db::DUPLICATE) {
                // ignore duplicate PDUs
                continue;
              } else {
                failed_pdus_.push_back({pdu, result});
              }
            }

            lock.lock();
            ++num_threads_;
          }
        }
      }
  };
}']

