Here is a sample C++ library for managing containerized applications across multiple Kubernetes clusters:
```
// Library headers
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <utility>

// Cloud provider SDK headers
#include <aws/core/Aws.h>
#include <google/cloud/storage/client.h>
#include <azure/storage/blobs.hpp>

// Cryptographic algorithm headers
#include <openssl/sha.h>
#include <openssl/aes.h>

namespace ContainerManagement {
    // Define a container object to store information about each application
    struct Container {
        std::string name;
        std::string image;
        std::vector<std::string> ports;
        std::map<std::string, std::string> env_vars;
    };

    // Define a Kubernetes cluster object to store information about each cluster
    struct Cluster {
        std::string name;
        std::string api_endpoint;
        std::string token;
    };

    // Define a Kubernetes client class for managing clusters and containers
    class K8sClient {
    public:
        K8sClient(const Cluster& cluster);
        ~K8sClient();

        // Create a container in the specified cluster
        void create_container(const Container& container);

        // Delete a container from the specified cluster
        void delete_container(const std::string& name);

        // List all containers in the specified cluster
        void list_containers();

        // Get information about a specific container in the specified cluster
        void get_container_info(const std::string& name);

    private:
        Cluster _cluster;
        Aws::ClientConfiguration _awsConfig;
        google::cloud::storage::ClientOptions _gcsConfig;
        azure::storage::blobs::StorageSharedKeyCredential _azureCredentials;
        std::unique_ptr<Aws::ECS::ECSClient> _ecsClient;
        std::unique_ptr<google::cloud::storage::Client> _gcsClient;
        std::unique_ptr<azure::storage::blobs::BlobServiceClient> _azureClient;
    };

    // Define a container manager class for managing containers across multiple clusters
    class ContainerManager {
    public:
        ContainerManager(const std::vector<Container>& containers);
        ~ContainerManager();

        // Create all containers in the specified clusters
        void create_containers();

        // Delete all containers from the specified clusters
        void delete_containers();

        // List all containers across all clusters
        void list_containers();

        // Get information about a specific container across all clusters
        void get_container_info(const std::string& name);

    private:
        std::vector<Container> _containers;
        std::map<std::string, Cluster> _clusters;
        std::map<std::string, K8sClient> _clients;
    };
}
```
In this sample code, we define a `Container` struct to store information about each container, and a `Cluster` struct to store information about each Kubernetes cluster. We also define a `K8sClient` class for managing containers in a specific cluster, and a `ContainerManager` class for managing containers across multiple clusters.

The `K8sClient` class has functions for creating, deleting, listing, and getting information about containers in the specified cluster. The `ContainerManager` class has similar functions for managing containers across all clusters.

