  const dialogFields = ['name', 'email', 'phone']; // List of fields to refresh

  return axios.get(url, { params: { id: resourceId } })
    .then((response) => {
      if (!response.data || !response.data.success) {
        return Promise.reject(`Error retrieving data for ${resourceId}`);
      }

      const fieldsToRefresh = dialogFields.filter(field => response.data[field]);
      if (fieldsToRefresh.length === 0) {
        return Promise.resolve();
      }

      const message = {
        type: 'refresh-dialog-fields',
        payload: { resourceId, fields: fieldsToRefresh }
      };

      window.parent.postMessage(message, '*');
    })
    .catch((err) => {
      console.error(`Error refreshing dialog fields for ${resourceId}:`, err);
      return Promise.reject(err);
    });
};

// Define the API endpoint for managing user profiles
