// SessionContextManager.h
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <functional>

class SessionContextManager {
public:
    // Adds a new session context to the manager.
    void addSession(const std::string& userId, const std::string& sessionId,
                    const std::string& ipAddress, const std::string& device);

    // Updates an existing session context in the manager.
    void updateSession(const std::string& userId, const std::string& sessionId,
                       const std::string& ipAddress, const std::string& device);

    // Retrieves a session context from the manager.
    SessionContext getSession(const std::string& userId, const std::string& sessionId);

    // Removes an existing session context from the manager.
    void removeSession(const std::string& userId, const std::string& sessionId);

    // Expires a session context based on its inactivity timeout.
    void expireSession(const std::string& userId, const std::string& sessionId);

    // Updates the authentication status of a session context.
    void updateAuthStatus(const std::string& userId, const std::string& sessionId, bool isAuthenticated);

    // Updates the activity timestamp of a session context.
    void updateActivityTimestamp(const std::string& userId, const std::string& sessionId);

private:
    struct SessionContext {
        std::string userId;
        std::string sessionId;
        std::string ipAddress;
        std::string device;
        bool isAuthenticated = false;
        std::chrono::time_point<std::chrono::system_clock> activityTimestamp;
    };

    // The map of user IDs to their associated session contexts.
    std::unordered_map<std::string, SessionContext*> userSessions_;

    // The mutex used to protect concurrent access to the user sessions map.
    std::mutex userSessionsMutex_;

    // The condition variable used to signal when a session context has expired.
    std::condition_variable sessionExpiryCondVar_;

    // The atomic flag indicating whether or not the manager is shutting down.
    std::atomic<bool> isShuttingDown_;
};
```
```
// SessionContextManager.cpp
#include "SessionContextManager.h"

void SessionContextManager::addSession(const std::string& userId, const std::string& sessionId,
                                      const std::string& ipAddress, const std::string& device) {
    std::lock_guard<std::mutex> lock(userSessionsMutex_);
    if (userSessions_.find(userId) == userSessions_.end()) {
        // The user does not have any existing sessions. Create a new session context.
        SessionContext* session = new SessionContext();
        session->userId = userId;
        session->sessionId = sessionId;
        session->ipAddress = ipAddress;
        session->device = device;
        session->isAuthenticated = false;
        session->activityTimestamp = std::chrono::system_clock::now();
        userSessions_.emplace(userId, session);
    } else {
        // The user has an existing session. Update the existing session context.
        SessionContext* session = userSessions_[userId];
        session->sessionId = sessionId;
        session->ipAddress = ipAddress;
        session->device = device;
        session->isAuthenticated = false;
        session->activityTimestamp = std::chrono::system_clock::now();
    }
}

void SessionContextManager::updateSession(const std::string& userId, const std::string& sessionId,
                                         const std::string& ipAddress, const std::string& device) {
    std::lock_guard<std::mutex> lock(userSessionsMutex_);
    auto it = userSessions_.find(userId);
    if (it == userSessions_.end()) {
        // The user does not have any existing sessions. Create a new session context.
        SessionContext* session = new SessionContext();
        session->userId = userId;
        session->sessionId = sessionId;
        session->ipAddress = ipAddress;
        session->device = device;
        session->isAuthenticated = false;
        session->activityTimestamp = std::chrono::system_clock::now();
        userSessions_.emplace(userId, session);
    } else {
        // The user has an existing session. Update the existing session context.
        SessionContext* session = it->second;
        session->sessionId = sessionId;
        session->ipAddress = ipAddress;
        session->device = device;
        session->activityTimestamp = std::chrono::system_clock::now();
    }
}

SessionContext SessionContextManager::getSession(const std::string& userId, const std::string& sessionId) {
    std::lock_guard<std::mutex> lock(userSessionsMutex_);
    auto it = userSessions_.find(userId);
    if (it == userSessions_.end()) {
        return SessionContext();
    } else {
        SessionContext* session = it->second;
        return *session;
    }
}

void SessionContextManager::removeSession(const std::string& userId, const std::string& sessionId) {
    std::lock_guard<std::mutex> lock(userSessionsMutex_);
    auto it = userSessions_.find(userId);
    if (it == userSessions_.end()) {
        return;
    } else {
        SessionContext* session = it->second;
        delete session;
        userSessions_.erase(it);
    }
}

void SessionContextManager::expireSession(const std::string& userId, const std::string& sessionId) {
    // Notify the condition variable that a session has expired.
    sessionExpiryCondVar_.notify_one();
}

void SessionContextManager::updateAuthStatus(const std::string& userId, const std::string& sessionId, bool isAuthenticated) {
    std::lock_guard<std::mutex> lock(userSessionsMutex_);
    auto it = userSessions_.find(userId);
    if (it == userSessions_.end()) {
        return;
    } else {
        SessionContext* session = it->second;
        session->isAuthenticated = isAuthenticated;
    }
}
```
In the above code, we have defined a `SessionContextManager` class that manages user sessions. The class has several methods:

* `addSession`: Adds a new session context for the given user ID and session ID. If there is already an existing session context for the user, this method updates the existing session context.
* `updateSession`: Updates the existing session context for the given user ID and session ID with the new IP address, device, and authentication status.
* `getSession`: Returns the existing session context for the given user ID and session ID, or an empty session context if there is no such session.
* `removeSession`: Removes the existing session context for the given user ID and session ID.
* `expireSession`: Notifies that a session has expired. This method is called when the manager detects that a session has timed out or been explicitly closed by the user.

The class also has an atomic flag `isShuttingDown_` to indicate whether or not the manager is shutting down, and a condition variable `sessionExpiryCondVar_` to signal when a session has expired.

Note that in this example, we have used a map data structure to store the user sessions. This allows us to efficiently retrieve the existing session context for a given user ID and session ID, and also provides a way to notify when a session has expired. However, you can use other data structures or techniques to manage user sessions as well.']

