#include <string.h>
#include <time.h>
#include <errno.h>

// Session data structure
typedef struct {
    char* user_id;
    char* auth_token;
    char* connection_metadata;
    time_t last_accessed;
} session_data;

// Session cache data structure
typedef struct {
    session_data** sessions;
    int num_sessions;
    int max_sessions;
} session_cache;

// Initialize session cache with given number of slots
void init_session_cache(session_cache* sc, int num_slots) {
    sc->sessions = (session_data**)malloc(num_slots * sizeof(session_data*));
    memset(sc->sessions, 0, num_slots * sizeof(session_data*));
    sc->num_sessions = 0;
    sc->max_sessions = num_slots;
}

// Add a new session to the cache
void add_session(session_cache* sc, char* user_id, char* auth_token, char* connection_metadata) {
    if (sc->num_sessions >= sc->max_sessions) {
        // Cache is full, remove the least recently used session
        int min_idx = 0;
        for (int i = 1; i < sc->num_sessions; i++) {
            if (sc->sessions[i]->last_accessed < sc->sessions[min_idx]->last_accessed) {
                min_idx = i;
            }
        }
        free(sc->sessions[min_idx]);
        memmove(sc->sessions + min_idx, sc->sessions + min_idx + 1, (sc->num_sessions - min_idx - 1) * sizeof(session_data*));
        sc->num_sessions--;
    }

    int idx = sc->num_sessions++;
    session_data* sd = (session_data*)malloc(sizeof(session_data));
    memset(sd, 0, sizeof(session_data));
    sd->user_id = strdup(user_id);
    sd->auth_token = strdup(auth_token);
    sd->connection_metadata = strdup(connection_metadata);
    sc->sessions[idx] = sd;
}

// Update a session in the cache
void update_session(session_cache* sc, char* user_id, char* auth_token, char* connection_metadata) {
    for (int i = 0; i < sc->num_sessions; i++) {
        if (strcmp(sc->sessions[i]->user_id, user_id) == 0) {
            // Found the session to update
            free(sc->sessions[i]->auth_token);
            free(sc->sessions[i]->connection_metadata);
            sc->sessions[i]->auth_token = strdup(auth_token);
            sc->sessions[i]->connection_metadata = strdup(connection_metadata);
            sc->sessions[i]->last_accessed = time(NULL);
            return;
        }
    }
}

// Retrieve a session from the cache
session_data* get_session(session_cache* sc, char* user_id) {
    for (int i = 0; i < sc->num_sessions; i++) {
        if (strcmp(sc->sessions[i]->user_id, user_id) == 0) {
            // Found the session to retrieve
            return sc->sessions[i];
        }
    }
    return NULL;
}

// Remove a session from the cache
void remove_session(session_cache* sc, char* user_id) {
    for (int i = 0; i < sc->num_sessions; i++) {
        if (strcmp(sc->sessions[i]->user_id, user_id) == 0) {
            // Found the session to remove
            free(sc->sessions[i]);
            memmove(sc->sessions + i, sc->sessions + i + 1, (sc->num_sessions - i - 1) * sizeof(session_data*));
            sc->num_sessions--;
            break;
        }
    }
}

// Check if a session is expired based on inactivity timeout
int is_expired(session_cache* sc, char* user_id) {
    session_data* sd = get_session(sc, user_id);
    if (sd == NULL) return 1;

    time_t now = time(NULL);
    int timeout = 60 * 15; // Inactivity timeout of 15 minutes
    if ((now - sd->last_accessed) >= timeout) {
        remove_session(sc, user_id);
        return 1;
    }
    return 0;
}

// Expire sessions based on inactivity timeouts
void expire_sessions(session_cache* sc, int timeout) {
    time_t now = time(NULL);
    for (int i = 0; i < sc->num_sessions; i++) {
        if ((now - sc->sessions[i]->last_accessed) >= timeout) {
            free(sc->sessions[i]);
            memmove(sc->sessions + i, sc->sessions + i + 1, (sc->num_sessions - i - 1) * sizeof(session_data*));
            sc->num_sessions--;
        }
    }
}

// Log session activity for monitoring and debugging purposes
void log_activity(char* user_id, char* action) {
    // TODO: Implement logging mechanism here
}
