void createFile(int tenantId, const string& name, const string& folder, const vector<string>& permissions) {
    Tenant* tenant = getTenantById(tenantId);
    if (tenant == nullptr) {
        return;
    }

    Folder* folder = getFolderByPath(folder, tenant);
    if (folder == nullptr) {
        return;
    }

    File file = { 0, name, folder->name, tenant->userId };
    for (auto permission : permissions) {
        file.permissions.push_back(permission);
    }
    tenant->files.push_back(file);
}

void deleteFile(int tenantId, const string& name, const string& folder) {
    Tenant* tenant = getTenantById(tenantId);
    if (tenant == nullptr) {
        return;
    }

    Folder* folder = getFolderByPath(folder, tenant);
    if (folder == nullptr) {
        return;
    }

    for (auto it = tenant->files.begin(); it != tenant->files.end(); ++it) {
        if (it->name == name && it->folder == folder->name) {
            tenant->files.erase(it);
            return;
        }
    }
}

