import java.util.*;
import javax.inject.Inject;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Controller;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.annotation.CachingConfigurerSupport;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.messaging.Message;
import org.springframework.messaging.support.MessageBuilder;
import org.springframework.statemachine.extendedstate.ExtendedState;
import org.springframework.statemachine.Action;
import org.springframework.statemachine.StateMachine;
import org.springframework.statemachine.StateMachineContext;
import org.springframework.statemachine.StateMachineRuntimeException;
import org.springframework.statemachine.StateMachineService;
import org.springframework.statemachine.annotation.OnTransition;
import org.springframework.statemachine.annotation.OnExit;
import org.springframework.statemachine.annotation.WithStateMachineListenerAdapter;
import org.springframework.statemachine.config.EnableStateMachineFactory;
import org.springframework.statemachine.config.EnumStateMachineConfigurerAdapter;
import org.springframework.statemachine.config.builders.StateMachineConfigurationConfigurer;
import org.springframework.statemachine.config.builders.StateMachineStateConfigurer;
import org.springframework.statemachine.config.builders.StateMachineTransitionConfigurer;
import org.springframework.statemachine.listener.StateMachineListener;
import org.springframework.statemachine.service.DefaultStateMachineService;
import org.springframework.statemachine.service.StateMachineServiceFactory;
import org.springframework.statemachine.transition.*;
import org.springframework.util.concurrent.ListenableFuture;

@Controller
public class UserProfileController {
  @Autowired
  private StateMachine<UserProfileStatus, UserProfileEvent> stateMachine;

  @OnTransition(source = "NEW", target = "ACTIVE")
  public void onActivation() {
    // handle activation transition
  }

  @OnExit("ACTIVE")
  public void onDeactivation() {
    // handle deactivation transition
  }

  @Transactional
  @Cacheable(cacheNames = "userProfiles", key = "#userId")
  public UserProfile getUserProfile(@PathVariable Long userId) {
    return userProfileService.getUserProfile(userId);
  }

  @Transactional
  public void updateUserProfile(@RequestBody UserProfile profile, @PathVariable Long userId) {
    UserProfile existingProfile = getUserProfile(userId);
    if (existingProfile == null) {
      throw new ResourceNotFoundException("User profile not found");
    }
    existingProfile.setName(profile.getName());
    existingProfile.setEmail(profile.getEmail());
    existingProfile.setPhoneNumber(profile.getPhoneNumber());
  }

  @Transactional
  public void deleteUserProfile(@PathVariable Long userId) {
    UserProfile existingProfile = getUserProfile(userId);
    if (existingProfile == null) {
      throw new ResourceNotFoundException("User profile not found");
    }
    userProfileService.deleteUserProfile(userId);
  }

  @Transactional
  public void batchUpdateUserProfiles(@RequestBody List<UserProfile> profiles) {
    for (UserProfile profile : profiles) {
      updateUserProfile(profile, profile.getId());
    }
  }

  @Transactional
  public void batchDeleteUserProfiles(@RequestBody List<Long> userIds) {
    for (Long userId : userIds) {
      deleteUserProfile(userId);
    }
  }
}

@EnableStateMachineFactory
public class UserProfileStateMachineConfigurer extends EnumStateMachineConfigurerAdapter<UserProfileStatus, UserProfileEvent> {
  @Override
  public void configure(StateMachineConfigurationConfigurer<UserProfileStatus, UserProfileEvent> config) throws Exception {
    config.withPersistence().jpa();
  }

  @Override
  public void configure(StateMachineStateConfigurer<UserProfileStatus, UserProfileEvent> states) throws Exception {
    states.withStates()
        .initial(UserProfileStatus.NEW)
        .states(EnumSet.allOf(UserProfileStatus.class));
  }

  @Override
  public void configure(StateMachineTransitionConfigurer<UserProfileStatus, UserProfileEvent> transitions) throws Exception {
    transitions
        // activation transition
        .withExternal()
        .source(UserProfileStatus.NEW)
        .target(UserProfileStatus.ACTIVE)
        .event(UserProfileEvent.ACTIVATION)
        .and()
        // deactivation transition
        .withExternal()
        .source(UserProfileStatus.ACTIVE)
        .target(UserProfileStatus.NEW)
        .event(UserProfileEvent.DEACTIVATION);
  }
}

@WithStateMachineListenerAdapter
public class UserProfileStateMachineListener implements StateMachineListener<UserProfileStatus, UserProfileEvent> {
  @Override
  public void stateChanged(StateMachine<UserProfileStatus, UserProfileEvent> stateMachine, Object event) {
    // handle state changes
  }

  @Override
  public void transition(StateMachine<UserProfileStatus, UserProfileEvent> stateMachine, Transition<UserProfileStatus, UserProfileEvent> transition) {
    // handle transitions
  }
}
