public class StateManager {
    private static final Logger logger = LoggerFactory.getLogger(StateManager.class);
    private static final Map<String, Object> cache = new HashMap<>();
    private static final ReentrantLock lock = new ReentrantLock();

    public MoSTState loadStateObject(String filePath) throws IOException {
        // Ensure the object is an instance of the MoSTState class
        if (!filePath.endsWith(".mo")) {
            throw new IOException("File path must end with '.mo'");
        }

        // Integrate with external configuration service to dynamically determine file path
        String dynamicFilePath = getDynamicFilePath(filePath);

        // Handle potential IOExceptions, ClassNotFoundExceptions, and EOFExceptions gracefully
        try {
            lock.lock();
            if (cache.containsKey(dynamicFilePath)) {
                return (MoSTState) cache.get(dynamicFilePath);
            } else {
                ObjectInputStream ois = new ObjectInputStream(new FileInputStream(dynamicFilePath));
                MoSTState state = (MoSTState) ois.readObject();
                cache.put(dynamicFilePath, state);
                return state;
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Failed to load state object from file path: {}", dynamicFilePath, e);
            throw new IOException(e);
        } finally {
            lock.unlock();
        }
    }

