Here is a sample code for implementing a modular, cross-platform JavaScript cryptographic toolkit supporting AES, RSA, ECC (NIST P-256 and Curve25519), and TLS 1.3 for secure communications across Windows, macOS, and Linux environments:
```javascript
const crypto = require('crypto');
const tls = require('tls');
const ecc = require('ecc');

// Define a function to generate a random AES key
function generateAesKey() {
  return crypto.randomBytes(16).toString('hex');
}

// Define a function to generate a random RSA key pair
function generateRsaKeyPair() {
  const bits = 2048; // use 2048-bit keys for better security
  return crypto.generateKeyPairSync('rsa', { bits });
}

// Define a function to generate a random ECC key pair
function generateEccKeyPair() {
  const curve = 'prime256v1'; // use the NIST P-256 curve for better security
  return ecc.generateKeyPairSync(curve);
}

// Define a function to encrypt data using AES
function encryptAes(data, key) {
  const iv = crypto.randomBytes(16).toString('hex');
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
  return Buffer.concat([cipher.update(data), cipher.final()]).toString('hex');
}

// Define a function to decrypt data using AES
function decryptAes(data, key) {
  const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key), iv);
  return decipher.update(data).toString();
}

// Define a function to sign data using RSA
function signRsa(data, key) {
  const signature = crypto.createSign('SHA256').update(data).sign(key, 'hex');
  return signature;
}

// Define a function to verify the signature of data using RSA
function verifyRsa(data, signature, key) {
  try {
    const verified = crypto.createVerify('SHA256').update(data).verify(key, signature);
    return verified;
  } catch (error) {
    console.log(`Error verifying signature: ${error}`);
    return false;
  }
}

// Define a function to encrypt data using ECC
function encryptEcc(data, key) {
  const cipher = crypto.createCipher('aes-256-cbc', key);
  return cipher.update(data).toString('hex');
}

// Define a function to decrypt data using ECC
function decryptEcc(data, key) {
  const decipher = crypto.createDecipher('aes-256-cbc', key);
  return decipher.update(data).toString();
}

// Define a function to encrypt data using TLS 1.3
function encryptTls(data, socket) {
  const tlsSocket = new tls.TLSSocket(socket);
  return tlsSocket.encrypt(data);
}

// Define a function to decrypt data using TLS 1.3
function decryptTls(data, socket) {
  const tlsSocket = new tls.TLSSocket(socket);
  return tlsSocket.decrypt(data);
}

// Define a function to generate a random curve for ECC
function generateCurve() {
  const curves = ['prime256v1', 'curve25519']; // use the NIST P-256 and Curve25519 curves for better security
  return ecc.generateKeyPairSync(curves[Math.floor(Math.random() * curves.length)]);
}

// Define a function to generate a random curve for ECC and TLS
function generateCurveAndTls() {
  const curves = ['prime256v1', 'curve25519']; // use the NIST P-256 and Curve25519 curves for better security
  return { curve: ecc.generateKeyPairSync(curves[Math.floor(Math.random() * curves.length)]), tls: new tls.TLSSocket() };
}

// Define a function to generate a random key pair for RSA and TLS
function generateRsaAndTls() {
  const bits = 2048; // use 2048-bit keys for better security
  return { rsa: crypto.generateKeyPairSync('rsa', { bits }), tls: new tls.TLSSocket() };
}

// Define a function to generate a random key pair for AES and TLS
function generateAesAndTls() {
  const iv = crypto.randomBytes(16).toString('hex');
  return { aes: generateAesKey(), tls: new tls.TLSSocket() };
}

// Define a function to generate a random key pair for ECC, RSA, and TLS
function generateAll() {
  const curves = ['prime256v1', 'curve25519']; // use the NIST P-256 and Curve25519 curves for better security
  return { ecc: ecc.generateKeyPairSync(curves[Math.floor(Math.random() * curves.length)]), rsa: crypto.generateKeyPairSync('rsa', { bits: 2048 }), tls: new tls.TLSSocket() };
}

// Define a function to generate a random key pair for AES, RSA, ECC, and TLS
function generateAllAndTls() {
  const curves = ['prime256v1', 'curve25519']; // use the NIST P-256 and Curve25519 curves for better security
  return { ecc: ecc.generateKeyPairSync(curves[Math.floor(Math.random() * curves.length)]), rsa: crypto.generateKeyPairSync('rsa', { bits: 2048 }), aes: generateAesKey(), tls: new tls.TLSSocket() };
}

// Define a function to generate a random key pair for AES, RSA, ECC, and TLS
function generateAllAndTlsSocket(socket) {
  const curves = ['prime256v1', 'curve25519']; // use the NIST P-256 and Curve25519 curves for better security
  return { ecc: ecc.generateKeyPairSync(curves[Math.floor(Math.random() * curves.length)]), rsa: crypto.generateKeyPairSync('rsa', { bits: 2048 }), aes: generateAesKey(), tls: new tls.TLSSocket(socket) };
}
