// Function to dynamically select an attack strategy for a character
std::pair<std::string, int> selectAttack(const std::vector<std::pair<std::string, int>>& attacks, const std::map<std::string, int>& cooldowns, const bool& isTraining) {
    // Create a vector of futures for each attack
    std::vector<std::future<int>> futures;
    for (const auto& attack : attacks) {
        futures.push_back(std::async(std::launch::async, [attack]() { return attackSelect(attack); }));
    }

    // Create a vector of results for each future
    std::vector<int> results;
    for (auto& future : futures) {
        results.push_back(future.get());
    }

    // Find the attack with the lowest result value and return it
    auto minResult = std::numeric_limits<int>::max();
    std::pair<std::string, int> selectedAttack;
    for (const auto& result : results) {
        if (result < minResult) {
            minResult = result;
            selectedAttack.first = attack.first;
            selectedAttack.second = attack.second;
        }
    }
    return selectedAttack;
}

