Here is the code block for the C# microservice that processes OAuth2 access token responses from a third-party API, ensuring compliance with the OAuth2 specification and handling high-throughput requests from thousands of concurrent users:
```csharp
using System;
using System.Threading;
using System.Threading.Tasks;
using ThirdPartyApi.Xml;

namespace OAuth2AccessTokenProcessor
{
    public class Service : IDisposable
    {
        private readonly IThirdPartyApi _thirdPartyApi;
        private readonly ConcurrentDictionary<string, Task> _taskCache = new ConcurrentDictionary<string, Task>();
        private readonly object _lock = new object();

        public Service(IThirdPartyApi thirdPartyApi)
        {
            _thirdPartyApi = thirdPartyApi;
        }

        public async Task<OAuth2AccessToken> ProcessAccessTokenResponseAsync(string responseXml)
        {
            var accessToken = ParseAccessTokenFromXml(responseXml);
            if (accessToken is null)
            {
                return null;
            }

            var cacheKey = CreateCacheKey(accessToken.ClientId, accessToken.Scope);
            if (_taskCache.TryGetValue(cacheKey, out Task task))
            {
                return await task.Result;
            }

            lock (_lock)
            {
                _taskCache[cacheKey] = ProcessAccessTokenAsync(accessToken);
            }

            return await task.Result;
        }

        private async Task<OAuth2AccessToken> ProcessAccessTokenAsync(OAuth2AccessToken accessToken)
        {
            var response = await _thirdPartyApi.ValidateAccessTokenAsync(accessToken);
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception("Failed to validate access token");
            }

            return response;
        }

        private static string CreateCacheKey(string clientId, string scope)
        {
            return $"{clientId}:{scope}";
        }

        public void Dispose()
        {
            _taskCache.Clear();
        }
    }
}
```
Note that this code block is just one possible implementation of a C# microservice responsible for processing OAuth2 access token responses from a third-party API. The service uses the `IThirdPartyApi` interface to interact with the external API, and the `ConcurrentDictionary<string, Task>` data structure to cache previously processed access tokens. The `ProcessAccessTokenResponseAsync` method is responsible for handling high-throughput requests from thousands of concurrent users by using thread-safe data structures and optimistic locking to prevent race conditions and ensure data integrity.']

