// Highly scalable, fault-tolerant, and tenant-specific logging system for a real-time, multi-tenant, distributed streaming application

import java.util.concurrent.*;
import java.util.logging.*;
import org.apache.commons.io.FileUtils;

public class LoggingSystem {
    private static final Logger logger = Logger.getLogger(LoggingSystem.class.getName());
    private static final int MAX_LOG_AGE = 7; // days
    private static final Map<String, BlockingQueue<LogEntry>> logQueues = new ConcurrentHashMap<>();

    public void addLogEntry(String tenantId, LogEntry entry) {
        if (!logQueues.containsKey(tenantId)) {
            logQueues.put(tenantId, new LinkedBlockingQueue<>());
        }
        logQueues.get(tenantId).add(entry);
    }

    public void purgeOldLogs() throws IOException {
        long currentTime = System.currentTimeMillis();
        for (Map.Entry<String, BlockingQueue<LogEntry>> entry : logQueues.entrySet()) {
            String tenantId = entry.getKey();
            BlockingQueue<LogEntry> queue = entry.getValue();
            while (!queue.isEmpty() && currentTime - queue.peek().getTimestamp() > MAX_LOG_AGE * 24 * 60 * 60 * 1000) {
                queue.poll();
            }
        }
    }

    public void archiveLogs(String tenantId, List<LogEntry> entries) throws IOException {
        if (!logQueues.containsKey(tenantId)) {
            return;
        }
        BlockingQueue<LogEntry> queue = logQueues.get(tenantId);
        for (LogEntry entry : entries) {
            queue.add(entry);
        }
        purgeOldLogs();
    }

    public List<LogEntry> getFilteredLogEntries(String tenantId, LogQuery query) throws IOException {
        if (!logQueues.containsKey(tenantId)) {
            return Collections.emptyList();
        }
        BlockingQueue<LogEntry> queue = logQueues.get(tenantId);
        List<LogEntry> filteredEntries = new ArrayList<>();
        for (LogEntry entry : queue) {
            if (query.matches(entry)) {
                filteredEntries.add(entry);
            }
        }
        return filteredEntries;
    }
}

// LogQuery class for querying log entries

import java.util.List;
import java.util.Map;

public class LogQuery {
    private Map<String, String> filters;

    public LogQuery(Map<String, String> filters) {
        this.filters = filters;
    }

    public boolean matches(LogEntry entry) {
        for (Map.Entry<String, String> filter : filters.entrySet()) {
            if (!filter.getKey().equals("tenantId") && !filter.getValue().equals(entry.get(filter.getKey()))) {
                return false;
            }
        }
        return true;
    }
}

// LogEntry class for storing log entries

import java.util.Date;

public class LogEntry {
    private Date timestamp;
    private String severityLevel;
    private String uniqueLogId;
    private String messageBody;

    public LogEntry(Date timestamp, String severityLevel, String uniqueLogId, String messageBody) {
        this.timestamp = timestamp;
        this.severityLevel = severityLevel;
        this.uniqueLogId = uniqueLogId;
        this.messageBody = messageBody;
    }

    public Date getTimestamp() {
        return timestamp;
    }

    public String getSeverityLevel() {
        return severityLevel;
    }

    public String getUniqueLogId() {
        return uniqueLogId;
    }

    public String getMessageBody() {
        return messageBody;
    }
}']

