// Session Management Service

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>

// Redis cache library
#include "redis_cache.h"

// External identity provider client
#include "identity_provider_client.h"

// Session management constants
#define SESSION_EXPIRATION 30 // in seconds
#define MAX_USER_SESSIONS 5
#define REFRESH_INTERVAL 10 // in seconds

// Session data structure
struct session {
    char *username;
    int user_id;
    time_t expiration;
    int access_count;
};

// In-memory cache for sessions
static redisContext *cache_ctx;
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Leader election algorithm
static int leader = 0;

// Identity provider client instance
static identity_provider_client_t *idp_client;

// Session management functions
int session_init() {
    // Initialize Redis cache connection
    cache_ctx = redisConnect("localhost", 6379);
    if (cache_ctx == NULL || cache_ctx->err) {
        printf("Error connecting to Redis: %s\n", cache_ctx->errstr);
        return -1;
    }

    // Initialize identity provider client instance
    idp_client = identity_provider_client_init();
    if (idp_client == NULL) {
        printf("Error initializing identity provider client\n");
        return -1;
    }

    // Set leader to current process
    leader = getpid();
}

void session_destroy() {
    // Release Redis cache connection
    redisFree(cache_ctx);

    // Release identity provider client instance
    identity_provider_client_destroy(idp_client);
}

// Session creation and update functions
int create_session(const char *username) {
    pthread_mutex_lock(&cache_lock);

    // Check if user already has an active session
    struct session *current = (struct session *)redisCommand(cache_ctx, "HGETALL %s", username);
    if (current != NULL && current->expiration > time(NULL)) {
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Create new session object and populate with default values
    struct session *new = (struct session *)malloc(sizeof(struct session));
    new->username = strdup(username);
    new->user_id = idp_client->get_user_id(username);
    new->expiration = time(NULL) + SESSION_EXPIRATION;
    new->access_count = 0;

    // Add session to Redis cache and update access count
    redisCommand(cache_ctx, "HSET %s %s %d", username, "user_id", new->user_id);
    redisCommand(cache_ctx, "HSET %s %s %d", username, "expiration", new->expiration);
    redisCommand(cache_ctx, "HSET %s %s %d", username, "access_count", new->access_count);

    // Release session object and unlock cache mutex
    free(new);
    pthread_mutex_unlock(&cache_lock);

    return 0;
}

int update_session(const char *username) {
    pthread_mutex_lock(&cache_lock);

    // Fetch current session object from Redis cache
    struct session *current = (struct session *)redisCommand(cache_ctx, "HGETALL %s", username);
    if (current == NULL || current->expiration < time(NULL)) {
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Update session access count and expiration timestamp
    int new_access_count = current->access_count + 1;
    struct session *new = (struct session *)malloc(sizeof(struct session));
    new->username = strdup(username);
    new->user_id = current->user_id;
    new->expiration = time(NULL) + SESSION_EXPIRATION;
    new->access_count = new_access_count;

    // Update session data in Redis cache
    redisCommand(cache_ctx, "HDEL %s %s", username, "user_id");
    redisCommand(cache_ctx, "HDEL %s %s", username, "expiration");
    redisCommand(cache_ctx, "HDEL %s %s", username, "access_count");
    redisCommand(cache_ctx, "HSET %s %s %d", username, "user_id", new->user_id);
    redisCommand(cache_ctx, "HSET %s %s %d", username, "expiration", new->expiration);
    redisCommand(cache_ctx, "HSET %s %s %d", username, "access_count", new->access_count);

    // Release session objects and unlock cache mutex
    free(current);
    free(new);
    pthread_mutex_unlock(&cache_lock);

    return 0;
}

// Session validation functions
int validate_session(const char *username) {
    pthread_mutex_lock(&cache_lock);

    // Fetch current session object from Redis cache
    struct session *current = (struct session *)redisCommand(cache_ctx, "HGETALL %s", username);
    if (current == NULL || current->expiration < time(NULL)) {
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Update session access count and expiration timestamp
    int new_access_count = current->access_count + 1;
    redisCommand(cache_ctx, "HSET %s %s %d", username, "expiration", time(NULL) + SESSION_EXPIRATION);
    redisCommand(cache_ctx, "HSET %s %s %d", username, "access_count", new_access_count);

    // Release session object and unlock cache mutex
    free(current);
    pthread_mutex_unlock(&cache_lock);

    return 0;
}

// Session termination functions
int terminate_session(const char *username) {
    pthread_mutex_lock(&cache_lock);

    // Fetch current session object from Redis cache
    struct session *current = (struct session *)redisCommand(cache_ctx, "HGETALL %s", username);
    if (current == NULL || current->expiration < time(NULL)) {
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Delete session data from Redis cache
    redisCommand(cache_ctx, "DEL %s", username);

    // Release session object and unlock cache mutex
    free(current);
    pthread_mutex_unlock(&cache_lock);

    return 0;
}
