    public class TransformRequestContentMiddleware : IMiddleware
    {
        private readonly ILogger<TransformRequestContentMiddleware> _logger;

        public TransformRequestContentMiddleware(ILogger<TransformRequestContentMiddleware> logger)
        {
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context, RequestDelegate next)
        {
            try
            {
                // Read the request body as a string
                var requestBody = await new StreamReader(context.Request.Body).ReadToEndAsync();

                // Validate the request body content integrity
                if (!ValidateContentIntegrity(requestBody))
                {
                    throw new InvalidContentException("Invalid request body content.");
                }

                // Apply GZIP compression or JSON pretty printing to the request body
                var transformedRequestBody = ApplyTransformations(requestBody);

                // Set the updated request body back to the context
                context.Request.Body = new MemoryStream(Encoding.UTF8.GetBytes(transformedRequestBody));

                await next(context);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error while transforming request content.");
                throw;
            }
        }

        private bool ValidateContentIntegrity(string requestBody)
        {
            // Implement your own validation logic here
            return true;
        }

        private string ApplyTransformations(string requestBody)
        {
            // Implement your own transformations here
            return requestBody;
        }
    }
}
```
This middleware implementation uses the `IMiddleware` interface and is designed to be used with ASP.NET Core's built-in dependency injection mechanism. It reads the request body as a string, validates its content integrity using a custom `ValidateContentIntegrity` method, applies transformations to the request body using an `ApplyTransformations` method, and sets the updated request body back to the context using the `MemoryStream` class.

The `ValidateContentIntegrity` method is responsible for validating the content integrity of the incoming request body. You can implement your own validation logic here based on your specific requirements. For example, you may want to validate that the request body contains a certain header or that it meets a certain format.

The `ApplyTransformations` method is responsible for applying the desired transformations to the request body. You can implement your own transformations here based on your specific requirements. For example, you may want to apply GZIP compression or JSON pretty printing to the request body.

In this implementation, we have also included a try-catch block to catch any errors that may occur during the transformation process and log them using the `ILogger` interface. This ensures that any errors that occur during the transformation process are handled gracefully and do not affect the overall performance of the middleware.']

