using System;
using System.IO;
using System.Text;
using System.Threading;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace JsonSerializerTool
{
    class Program
    {
        static void Main(string[] args)
        {
            // Initialize the serialization module with default options
            var serializer = new JsonSerializer();

            // Process each input file in parallel
            foreach (var filePath in args)
            {
                // Read the file contents and deserialize the JSON data
                string jsonData = File.ReadAllText(filePath);
                JToken token = JToken.Parse(jsonData);

                // Serialize the data to a custom data structure
                var data = serializer.Deserialize<MyCustomType>(token);

                // Save the serialized data to a file
                File.WriteAllText($"{filePath}.bin", data.ToString());
            }
        }
    }

    public class JsonSerializer : IJsonSerializer
    {
        private readonly BinaryFormatter _binaryFormatter = new BinaryFormatter();
        private readonly JsonSerializerSettings _jsonSettings;

        public JsonSerializer()
        {
            // Initialize the JSON serializer settings with default options
            _jsonSettings = new JsonSerializerSettings
            {
                NullValueHandling = NullValueHandling.Ignore,
                MissingMemberHandling = MissingMemberHandling.Error,
                ErrorHandlingPolicy = ErrorHandlingPolicy.DenySilent,
                ContractResolver = new CamelCasePropertyNamesContractResolver()
            };
        }

        public T Deserialize<T>(JToken token) where T : class
        {
            // Deserialize the JSON data to a custom data structure using the binary serializer
            return _binaryFormatter.Deserialize(token, typeof(T)) as T;
        }

        public void Serialize<T>(T obj, Stream stream) where T : class
        {
            // Serialize the custom data structure to a JSON string using the binary serializer
            byte[] jsonData = _binaryFormatter.Serialize(obj);

            // Write the JSON data to the output stream
            stream.Write(jsonData, 0, jsonData.Length);
        }
    }
}
