// Define the function to dynamically allocate and link a new CRC indication structure into the list
struct CRC_INDICATION_PTR* allocAndLinkCrcIndication(RX_UE_INFORMATION_TAG rxUeInfoTag, RNTI rnti, int crcFlag) {
