        crcIndicationList.tail->next = newNode;
        crcIndicationList.tail = newNode;
    }
    pthread_mutex_unlock(&crcIndicationListMutex);
}

// Define the function to free the memory allocated for a CRC indication structure
void freeCrcIndication(struct CRC_INDICATION_PTR* node) {
    pthread_mutex_lock(&crcIndicationListMutex);
    struct CRC_INDICATION_PTR* currNode = crcIndicationList.head;
    while (currNode != NULL && currNode != node) {
        // Move to the next node
        currNode = currNode->next;
    }
    if (currNode == node) {
        // Remove from the list
        if (crcIndicationList.head == crcIndicationList.tail) {
            // The only element in the list, so reset both head and tail
            free(node);
            crcIndicationList.head = NULL;
            crcIndicationList.tail = NULL;
        } else if (currNode == crcIndicationList.head) {
            // The first element in the list, so reset head and move tail to next node
            free(node);
            crcIndicationList.head = currNode->next;
        } else {
            // An intermediate element, so just reset next pointer and maintain the tail
            free(node);
            currNode->next = NULL;
        }
    } else {
        printf("Error: Attempted to free non-existent node!\n");
    }
    pthread_mutex_unlock(&crcIndicationListMutex);
}

// Define the function to serialize the CRC indications into a file
