    struct CRC_INDICATION_PTR* currNode = crcIndicationList.head;
    while (currNode != NULL) {
        // Write the node data structure to the file
        fwrite(currNode, sizeof(struct CRC_INDICATION_PTR), 1, f);
        // Move to the next node
        currNode = currNode->next;
    }
    pthread_mutex_unlock(&crcIndicationListMutex);
}

// Define the function to deserialize CRC indications from a file into the list
void deserializeCrcIndications(char* filename) {
    // Open the input file in binary mode and read the list data structure from it
    FILE* f = fopen(filename, "rb");
    if (f == NULL) {
