    NFAPI_CRC_INDICATION_PDU_T *data;
    struct NFAPI_LIST_NODE *prev, *next;
} NFAPI_LIST_NODE_T;

struct NFAPI_LIST {
    NFAPI_LIST_NODE_T *head, *tail;
    pthread_mutex_t mutex;
};

void nfapi_list_init(NFAPI_LIST_T *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void nfapi_list_add(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_LIST_NODE_T *node = malloc(sizeof(NFAPI_LIST_NODE_T));
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void nfapi_list_remove(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_LIST_NODE_T *node = list->head;
    while (node != NULL && node->data != data) {
        node = node->next;
    }
    if (node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    if (node == list->head) {
        list->head = node->next;
    }
    if (node == list->tail) {
        list->tail = node->prev;
    }
    if (node->prev != NULL) {
        node->prev->next = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
    free(node);
    pthread_mutex_unlock(&list->mutex);
}

void nfapi_list_free(NFAPI_LIST_T *list) {
    NFAPI_LIST_NODE_T *node = list->head;
    while (node != NULL) {
        NFAPI_LIST_NODE_T *next = node->next;
        free(node);
        node = next;
    }
}
```
