int nfapi_add_rnti(int rnti) {
    // Validate the RNTI value
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI value: %d\n", rnti);
        return -1;
    }

    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Allocate a new structure from the memory pool
    nfapi_crc_indication_pdu_t *new_data = (nfapi_crc_indication_pdu_t *) malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (!new_data) {
        printf("Failed to allocate new data structure\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize the new structure with the RNTI value
    new_data->rnti = rnti;

    // Add the new structure to the linked list
    nfapi_crc_indication_list_t *new_node = (nfapi_crc_indication_list_t *) malloc(sizeof(nfapi_crc_indication_list_t));
    if (!new_node) {
        printf("Failed to allocate new node\n");
        free(new_data);
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    new_node->data = new_data;
    new_node->next = NULL;
    if (memory_pool == NULL) {
        memory_pool = new_node;
    } else {
        nfapi_crc_indication_list_t *curr = memory_pool;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
