// Declare the Semaphore class
class Semaphore {
public:
    // Constructor to initialize the semaphore with a given name and initial value
    Semaphore(const std::string& name, int initialValue) : name_(name), value_(initialValue) {}

    // Acquire a permit from the semaphore
    void acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (value_ <= 0) {
            condition_.wait(lock);
        }
        value_--;
    }

    // Release a permit to the semaphore
    void release() {
        std::unique_lock<std::mutex> lock(mutex_);
        value_++;
        condition_.notify_all();
    }

    // Return the name of the semaphore
    const std::string& getName() const { return name_; }

    // Return the current value of the semaphore
    int getValue() const { return value_; }

private:
    // Name of the semaphore
    std::string name_;

    // Current value of the semaphore
    int value_;

    // Mutex for protecting concurrent access to the semaphore
    std::mutex mutex_;

    // Condition variable for waiting on the semaphore
    std::condition_variable condition_;
};

// Declare the SemaphoreManager class
class SemaphoreManager {
public:
    // Constructor to initialize the semaphore manager with a given set of semaphores and their initial values
    SemaphoreManager(const std::vector<std::pair<std::string, int>>& semaphores) : semaphores_(semaphores) {}

    // Add a new semaphore to the manager with a given name and initial value
    void addSemaphore(const std::string& name, int initialValue) {
        std::unique_lock<std::mutex> lock(mutex_);
        semaphores_.push_back({name, initialValue});
    }

    // Remove a semaphore from the manager with a given name
    void removeSemaphore(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto it = semaphores_.begin(); it != semaphores_.end(); ++it) {
            if (it->first == name) {
                semaphores_.erase(it);
                return;
            }
        }
    }

    // Acquire a permit from a semaphore with a given name, blocking until the permit is available
    void acquireSemaphore(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto it = semaphores_.begin(); it != semaphores_.end(); ++it) {
            if (it->first == name) {
                it->second.acquire();
                return;
            }
        }
    }

    // Release a permit to a semaphore with a given name
    void releaseSemaphore(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto it = semaphores_.begin(); it != semaphores_.end(); ++it) {
            if (it->first == name) {
                it->second.release();
                return;
            }
        }
    }

private:
    // Mutex for protecting concurrent access to the semaphore map
    std::mutex mutex_;

    // Map of semaphores and their current values
    std::vector<std::pair<std::string, Semaphore>> semaphores_;
};

