// process_string.c

#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <errno.h>
#include <string.h>
#include <pthread.h>
#include "resource_pool.h" // custom resource pool implementation

typedef struct {
    size_t max_size; // maximum allowed string length, including appended slash
    void (*error_callback)(const char*); // callback function for handling errors
} process_string_options_t;

int process_string(char *input_str, const process_string_options_t *options) {
    if (options->max_size <= 0) {
        options->error_callback("Invalid size limit provided");
        return -EINVAL; // error code for invalid arguments
    }

    // validate input string for invalid UTF-8 sequences and handle multibyte characters appropriately
    if (!validate_utf8(input_str)) {
        options->error_callback("Invalid UTF-8 sequence detected");
        return -EILSEQ; // error code for invalid UTF-8 sequence
    }

    // acquire lock on shared memory pool to allocate string buffer safely
    pthread_mutex_lock(&pool_mutex);
    char *buffer = get_string_buffer(options->max_size);
    if (buffer == NULL) {
        options->error_callback("Failed to allocate string buffer");
        return -ENOMEM; // error code for out of memory
    }

    // append slash to end of input string and copy into shared buffer
    strcpy(buffer, input_str);
    if (input_str[strlen(input_str) - 1] != '/') {
        strcat(buffer, "/");
    }

    // release lock on shared memory pool after copying input string to buffer safely
    pthread_mutex_unlock(&pool_mutex);

    return 0; // success
}

// custom resource pool implementation for allocating and managing shared memory buffers

#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    char *buffer; // shared memory buffer
    size_t size; // size of shared memory buffer
} string_buffer_t;

// lock for synchronizing access to shared memory pool
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// array of available shared memory buffers
static string_buffer_t *available_buffers;

// size of available buffer array
static int num_available_buffers;

// initialize shared memory pool with a set of pre-allocated buffers
void init_pool(int num_buffers) {
    available_buffers = malloc(num_buffers * sizeof(string_buffer_t));
    if (available_buffers == NULL) {
        perror("Failed to allocate memory for shared memory pool");
        exit(EXIT_FAILURE);
    }
    num_available_buffers = 0;
}

// acquire lock on shared memory pool and return available buffer
char *get_string_buffer(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (num_available_buffers > 0) {
        string_buffer_t *buffer = &available_buffers[--num_available_buffers];
        available_buffers[num_available_buffers] = NULL;
        return buffer->buffer;
    } else {
        // allocate new shared memory buffer and return it if possible, otherwise return NULL
        char *buffer = malloc(size);
        if (buffer == NULL) {
            pthread_mutex_unlock(&pool_mutex);
            return NULL;
        }
        return buffer;
    }
}

// release lock on shared memory pool and return buffer to available list
void release_string_buffer(char *buffer, size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (num_available_buffers == 0) {
        available_buffers = realloc(available_buffers, (num_available_buffers + 1) * sizeof(string_buffer_t));
        if (available_buffers == NULL) {
            perror("Failed to allocate memory for shared memory pool");
            exit(EXIT_FAILURE);
        }
    }
    available_buffers[num_available_buffers++].buffer = buffer;
    pthread_mutex_unlock(&pool_mutex);
}

// validate input string for invalid UTF-8 sequences and handle multibyte characters appropriately
bool validate_utf8(char *str) {
    while (*str != '\0') {
        if ((*str & 0x80) == 0x80) { // multi-byte character detected
            char *end = str + 1;
            while ((*end & 0xc0) != 0x80) end++;
            if (*end == '\0') return false; // incomplete multi-byte sequence at end of string
        }
        str++;
    }
    return true;
}
