// Dynamic array of LTE_PDCP_PDU structures for packet management
typedef struct {
    int size; // Current number of packets in the array
    int capacity; // Maximum number of packets that can be stored in the array
    LTE_PDCP_PDU *packets[]; // Array of LTE_PDCP_PDU structures
} PacketArray;

// Initialize and allocate memory for a specified number of packets
void initPacketArray(PacketArray *array, int num_packets) {
    array->size = 0;
    array->capacity = num_packets;
    array->packets = (LTE_PDCP_PDU *)malloc(num_packets * sizeof(LTE_PDCP_PDU));
}

// Populate each LTE_PDCP_PDU structure with a random PDCP SN and DL_SRB_MESSAGE
