        array->packets[i].dl_srb_message.header_length = rand() % 100; // Randomly generate header length
        array->packets[i].dl_srb_message.payload_length = rand(); // Randomly generate payload length
    }
}

// Free memory allocated for the packet array
void freePacketArray(PacketArray *array) {
    if (array->packets != NULL) {
        free(array->packets);
    }
}

// Handle memory allocation failures by logging and propagating the error
void handleAllocationFailure(int failed_allocation, PacketArray *array) {
    printf("Memory allocation failure! Failed to allocate %d bytes\n", failed_allocation);
    freePacketArray(array);
}

// Handle invalid packet sequences by logging and propagating the error
