}

// Thread-safe function to add a new packet to the array
void addPacket(PacketArray *array, int pdcp_sn, DL_SRB_MESSAGE dl_srb_message) {
    // Check if there is enough space in the array for the new packet
    if (array->size == array->capacity) {
        printf("Reached capacity limit! Can't add new packet\n");
        return;
    }

    // Lock the critical section to ensure thread safety
    pthread_mutex_lock(&array->mutex);

    // Add the new packet to the array
    array->packets[array->size].pdcp_sn = pdcp_sn;
    array->packets[array->size].dl_srb_message = dl_srb_message;
    array->size++;

    // Unlock the critical section to release the lock
    pthread_mutex_unlock(&array->mutex);
}

// Thread-safe function to get a packet from the array by sequence number
void getPacket(PacketArray *array, int sequence_number) {
    // Lock the critical section to ensure thread safety
    pthread_mutex_lock(&array->mutex);

    // Check if the requested sequence number is within bounds
    if (sequence_number < 0 || sequence_number >= array->size) {
        printf("Invalid sequence number! Can't retrieve packet\n");
        return;
    }

    // Get the packet from the array and print it
    LTE_PDCP_PDU *packet = &array->packets[sequence_number];
    printf("Packet with PDCP SN %d received:\n", packet.pdcp_sn);
    printf("Header length: %d\nPayload length: %d\n", packet.dl_srb_message.header_length, packet.dl_srb_message.payload_length);

    // Unlock the critical section to release the lock
    pthread_mutex_unlock(&array->mutex);
}
