int packet_count = 0;

// Define the mutex and condition variable for synchronization
pthread_mutex_t mutex;
pthread_cond_t cond;

// Define the function to initialize the dynamic array of LTE_PDCP_PDU structures
void init_packet_array(int size) {
    // Allocate memory for the dynamic array
    packet_array = (LTE_PDCP_PDU*)malloc(size * sizeof(LTE_PDCP_PDU));
    if (!packet_array) {
        perror("Failed to allocate memory for the packet array");
        exit(-1);
    }
    // Initialize the packet count
    packet_count = 0;
}

// Define the function to add a new LTE_PDCP_PDU structure to the dynamic array
void add_packet(int pdcp_sn, char* dl_srb_message) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);
    // Increment the packet count and reallocate memory if necessary
    if (++packet_count > packet_array->length) {
        int new_size = packet_count * 2;
        LTE_PDCP_PDU* new_packet_array = (LTE_PDCP_PDU*)realloc(packet_array, new_size * sizeof(LTE_PDCP_PDU));
        if (!new_packet_array) {
            perror("Failed to reallocate memory for the packet array");
            exit(-1);
        }
        packet_array = new_packet_array;
    }
    // Set the pdcp_sn and dl_srb_message fields of the new LTE_PDCP_PDU structure
    packet_array[packet_count - 1].pdcp_sn = pdcp_sn;
    packet_array[packet_count - 1].dl_srb_message = dl_srb_message;
    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}

// Define the function to retrieve a LTE_PDCP_PDU structure from the dynamic array by index
LTE_PDCP_PDU* get_packet(int index) {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);
    // Check if the index is valid and return the corresponding LTE_PDCP_PDU structure
    if (index >= 0 && index < packet_count) {
        LTE_PDCP_PDU* packet = &packet_array[index];
        pthread_mutex_unlock(&mutex);
        return packet;
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

// Define the function to retrieve the number of LTE_PDCP_PDU structures in the dynamic array
int get_packet_count() {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);
    // Return the current packet count
    int count = packet_count;
    pthread_mutex_unlock(&mutex);
    return count;
}

// Define the function to free the memory of the dynamic array of LTE_PDCP_PDU structures
void free_packet_array() {
    // Lock the mutex before accessing the shared data
    pthread_mutex_lock(&mutex);
    // Free the memory allocated for the packet array
    if (packet_array) {
        free(packet_array);
    }
    // Reset the packet count to zero
    packet_count = 0;
    // Unlock the mutex after accessing the shared data
    pthread_mutex_unlock(&mutex);
}
