        .json::<Vec<Keyword>>()
        .await?;
    Ok(response)
}

async fn process_content(content: &UserGeneratedContent) -> Result<Vec<Keyword>> {
    let keywords = update_keywords(content).await?;
    Ok(keywords)
}

async fn handle_request(request: &KeywordUpdateRequest) -> Result<()> {
    let content = request.content.clone();
    let keywords = process_content(&content).await?;
    Ok(())
}

