    snprintf(messageBuffer, sizeof(char) * (strlen(message) + 1024), "{\"severity\": \"%s\", \"thread_id\": %lu, \"message\": \"%s\"}", getSeverityString(severity), pthread_self(), message);
    int sentBytes = SSL_write(sslConnection, messageBuffer, strlen(messageBuffer));
    if (sentBytes < 0) {
        printf("Error sending log entry: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(messageBuffer);
        return;
    }

    // Handle potential service outages and retry failed requests with exponential backoff
    int attempt = 1;
    while (sentBytes < 0) {
        printf("Error sending log entry. Attempt %d\n", attempt++);
        sleep(attempt * 2);
        sentBytes = SSL_write(sslConnection, messageBuffer, strlen(messageBuffer));
    }

    // Cleanup
    SSL_shutdown(sslConnection);
    SSL_free(sslConnection);
    SSL_CTX_free(sslCtx);
}

const char* getSeverityString(LogSeverity severity) {
    switch (severity) {
        case LogSeverity::ERROR: return "error";
        case LogSeverity::WARNING: return "warning";
        case LogSeverity::INFO: return "info";
        default: return "";
    }
}

void main() {
