#include <thread>
#include <future>
#include <chrono>
#include <ctime>
#include <iomanip>

using namespace std;

// Define the data structure to store sensor values and timestamps
struct SensorData {
    double temperature;
    double humidity;
    double voltage;
    int battery_level;
    time_t timestamp;
};

// Define a class for managing device records
class DeviceRecord {
public:
    // Constructor to initialize the record with an empty vector of sensor data
    DeviceRecord() : sensor_data(vector<SensorData>{}) {}

    // Add a new sensor data point to the record
    void add_sensor_data(const SensorData& data) {
        sensor_data.push_back(data);
    }

    // Get the most recent sensor data point from the record
    const SensorData& get_latest_sensor_data() const {
        return *(sensor_data.rbegin());
    }

private:
    vector<SensorData> sensor_data;
};

// Define a class for managing device records and sensor data streams
class DeviceManager {
public:
    // Constructor to initialize the device manager with an empty map of device records
    DeviceManager() : device_records(unordered_map<string, DeviceRecord>{}) {}

    // Add a new device record to the manager
    void add_device(const string& device_id) {
        device_records[device_id] = DeviceRecord();
    }

    // Remove a device record from the manager
    void remove_device(const string& device_id) {
        device_records.erase(device_id);
    }

    // Get the latest sensor data point from all devices in the manager
    vector<SensorData> get_latest_sensor_data() const {
        vector<SensorData> data;
        for (auto& device : device_records) {
            data.push_back(device.second.get_latest_sensor_data());
        }
        return data;
    }

    // Update the sensor data for a specific device in the manager
    void update_device_data(const string& device_id, const SensorData& data) {
        auto it = device_records.find(device_id);
        if (it != device_records.end()) {
            it->second.add_sensor_data(data);
        } else {
            add_device(device_id);
            update_device_data(device_id, data);
        }
    }

private:
    unordered_map<string, DeviceRecord> device_records;
};

// Define a class for managing sensor data streams from multiple devices
class SensorStreamManager {
public:
    // Constructor to initialize the stream manager with an empty map of device records
    SensorStreamManager() : device_manager(DeviceManager()) {}

    // Add a new device record to the stream manager
    void add_device(const string& device_id) {
        device_manager.add_device(device_id);
    }

    // Remove a device record from the stream manager
    void remove_device(const string& device_id) {
        device_manager.remove_device(device_id);
    }

    // Update the sensor data for a specific device in the stream manager
    void update_device_data(const string& device_id, const SensorData& data) {
        device_manager.update_device_data(device_id, data);
    }

    // Get the latest sensor data point from all devices in the stream manager
    vector<SensorData> get_latest_sensor_data() const {
        return device_manager.get_latest_sensor_data();
    }

private:
    DeviceManager device_manager;
};

// Define a class for managing multiple sensor streams and devices
class SensorStreamController {
public:
    // Constructor to initialize the stream controller with an empty map of sensor streams
    SensorStreamController() : sensor_streams(unordered_map<string, SensorStreamManager>{}) {}

    // Add a new sensor stream to the controller
    void add_stream(const string& stream_id) {
        sensor_streams[stream_id] = SensorStreamManager();
    }

    // Remove a sensor stream from the controller
    void remove_stream(const string& stream_id) {
        sensor_streams.erase(stream_id);
    }

    // Update the sensor data for a specific device in the controller
    void update_device_data(const string& device_id, const SensorData& data) {
        for (auto& stream : sensor_streams) {
            stream.second.update_device_data(device_id, data);
        }
    }

    // Get the latest sensor data point from all devices in the controller
    vector<SensorData> get_latest_sensor_data() const {
        vector<SensorData> data;
        for (auto& stream : sensor_streams) {
            data.insert(data.end(), stream.second.get_latest_sensor_data().begin(), stream.second.get_latest_sensor_data().end());
        }
        return data;
    }

private:
    unordered_map<string, SensorStreamManager> sensor_streams;
};

int main() {
    // Initialize the device manager and stream controller
    DeviceManager device_manager;
    SensorStreamController sensor_controller;

    // Add a new device record to the device manager
    device_manager.add_device("device1");

    // Update the sensor data for the device in the device manager
    SensorData data = { 25.0, 60.0, 4.8, 10 };
    device_manager.update_device_data("device1", data);

    // Add a new sensor stream to the stream controller
    sensor_controller.add_stream("stream1");

    // Update the sensor data for the device in the stream manager
    data = { 20.0, 50.0, 4.5, 8 };
    sensor_controller.update_device_data("device1", data);

    // Get the latest sensor data point from all devices in the controller
    vector<SensorData> data = sensor_controller.get_latest_sensor_data();

    return 0;
}
```
This example uses a `DeviceManager` class to manage the sensor data for multiple devices, and a `SensorStreamController` class to manage multiple sensor streams and devices. The `DeviceManager` class contains a map of device IDs to `SensorStreamManager` objects, which in turn contain a map of stream IDs to `SensorStreamManager` objects. The `SensorStreamManager` class contains a map of device IDs to `SensorData` objects, which store the latest sensor data for each device.

The example also demonstrates how to update the sensor data for a specific device in the manager and controller, as well as how to get the latest sensor data point from all devices in the manager and controller.

Note that this is just one possible implementation of a system that manages multiple sensor streams and devices, and there are many other ways to design such a system depending on the specific requirements and constraints of your application.']

