async function processAndLogCRCIndications(N, externalDataSource, maxConcurrency) {
  // Initialize metrics for processing time and success/failure rates
  const startTime = Date.now();
  let numSuccessfulProcessings = 0;
  let numFailedProcessings = 0;

  // Create a promise pool to manage concurrent operations
  const promisePool = new PromisePool(maxConcurrency);

  // Iterate over the specified number of structures to generate
  for (let i = 0; i < N; i++) {
    // Create a new NFAPI_CRC_INDICATION_PDU_T structure
    const crcIndicationPdu = {};

    // Fetch necessary UE information from the external data source
    promisePool.add(async () => {
      try {
        // Retrieve RX_UE_INFORMATION_TAG and RNTI for the current structure
        const [rxUeInformationTag, rnti] = await externalDataSource();

        // Set CRCFLAG to a randomly generated value
        crcIndicationPdu.crCflag = generateRandomCrcFlag();

        // Update the structure with the fetched UE information and flag
        crcIndicationPdu.rxUeInformationTag = rxUeInformationTag;
        crcIndicationPdu.rnti = rnti;
      } catch (error) {
        // Handle potential errors from the external data source
        numFailedProcessings++;
        console.error(`Failed to fetch UE information: ${error}`);
      }
    });
  }

  // Wait for all promises in the pool to resolve
  await promisePool.wait();

  // Calculate metrics for processing time and success/failure rates
  const endTime = Date.now();
  const processingTime = endTime - startTime;
  const successRate = (numSuccessfulProcessings / N) * 100;
  const failureRate = (numFailedProcessings / N) * 100;

  // Log metrics and debugging information
  console.log(`Processed ${N} CRC indications in ${processingTime} ms`);
  console.log(`Success rate: ${successRate}%, Failure rate: ${failureRate}%`);

  // Return the generated structures
  return crcIndicationPdus;
}

// Generate a randomly set CRCFLAG value
function generateRandomCrcFlag() {
  return Math.floor(Math.random() * 10) % 2 === 0 ? 'CRCFlag' : 'NoCRCFlag';
}

// Create a PromisePool to manage concurrent operations
class PromisePool {
  constructor(maxConcurrency) {
    this.concurrency = maxConcurrency;
    this.promises = [];
  }

  // Add a new promise to the pool
  add(promise) {
    this.promises.push(promise);
    if (this.promises.length === this.concurrency) {
      this.wait();
    }
  }

  // Wait for all promises in the pool to resolve
  async wait() {
    await Promise.all(this.promises);
    this.promises = [];
  }
}
