#define MAX_BUFFER_SIZE 1024
#define MAX_INPUT_SIZE 8192
#define MAX_TIMEOUT 5
#define MIN_THREADS 10
#define MAX_THREADS 100
#define THREAD_CACHE_SIZE 10
#define LOG_FILE "/var/log/processString.log"

typedef struct {
    char* input;
    int size;
} input_t;

// Logging function
void log(const char* message) {
    FILE* fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s\n", message);
    fclose(fp);
}

// Function to fetch input string from external service
char* getInputString() {
    // Implement a timeout mechanism with configurable values based on user preferences
    int timeout = 0;
    while (timeout < MAX_TIMEOUT) {
        char* inputString = fetchInputString();
        if (inputString != NULL) {
            return inputString;
        } else {
            timeout++;
        }
    }
    // Handle partial data reception by appending to a temporary buffer until the complete string is received, ensuring no buffer overflows
    char* tempBuffer = malloc(MAX_INPUT_SIZE);
    if (tempBuffer == NULL) {
        log("Error allocating memory for temporary buffer");
        return NULL;
