// AsyncDataProcessor.cpp
#include "AsyncDataProcessor.h"

#include <iostream>
#include <memory>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <functional>

using namespace std;

AsyncDataProcessor::AsyncDataProcessor(const vector<pair<string, string>>& dataSources) {
    // Initialize the processor with the given list of data sources and their associated configurations
    for (auto& source : dataSources) {
        _dataSources.push_back(source);
    }
}

AsyncDataProcessor::~AsyncDataProcessor() {
    // Clean up resources when the object is destroyed
    for (auto& connection : _connections) {
        connection.second->close();
    }
}

void AsyncDataProcessor::processData() {
    // Iterate through all active connections and handle incoming data
    for (auto& connection : _connections) {
        connection.second->read(([this](const std::string& message) {
            handleData(connection.first, message);
        }), [this](const std::exception& e) {
            handleError(connection.first, e);
        });
    }
}

void AsyncDataProcessor::addDataSource(const string& name, const string& config) {
    // Add a new data source to the processor with its associated configuration
    _dataSources.push_back({name, config});
}

void AsyncDataProcessor::removeDataSource(const string& name) {
    // Remove an existing data source from the processor by name
    auto it = find_if(_dataSources.begin(), _dataSources.end(), [name](auto& source) {
        return source.first == name;
    });
    if (it != _dataSources.end()) {
        _dataSources.erase(it);
    }
}

void AsyncDataProcessor::handleData(const string& source, const string& message) {
    // Handle incoming data from a connection by parsing and processing it
    cout << "Received data from source: " << source << endl;
    // Parse and process the message
    // ...
}

void AsyncDataProcessor::handleError(const string& source, const exception& e) {
    // Handle errors and disconnections from a connection by logging them and retrying if possible
    cout << "Encountered error: " << e.what() << endl;
    auto it = find_if(_dataSources.begin(), _dataSources.end(), [source](auto& source) {
        return source.first == source;
    });
    if (it != _dataSources.end()) {
        // Retry the connection if possible
        // ...
    }
}
