  // Define a function to handle circuit breaker patterns for failed CRC indication creation
  async function handleCircuitBreakerFailure(crcIndication, error) {
    try {
      console.log(`Failed to create CRC indication structure: ${error}`);
      return null;
    } catch (error) {
      console.log(`Failed to create CRC indication structure after ${numFailed} attempts: ${error}`);
      return null;
    }
  }

  // Define a function to handle circuit breaker patterns for failed thread safety
  async function handleCircuitBreakerFailure(crcIndications, error) {
    try {
      console.log(`Failed to populate CRC indication structures: ${error}`);
      return null;
    } catch (error) {
      console.log(`Failed to populate CRC indication structures after ${numFailed} attempts: ${error}`);
      return null;
    }
  }

  // Initialize the CRC indications array
  const crcIndications = [];

  // Loop through each data source and fetch UE information
  for (const dataSource of dataSources) {
    try {
      // Fetch UE information from the current data source
      const ueInfo = await fetchUEInformation(dataSource);

      // Create a CRC indication structure for the current UE
