    HttpHeaders headers = new HttpHeaders();
    headers.setContentType(MediaType.APPLICATION_JSON);
    try {
      return restTemplate.getForEntity(builder.toUriString(), Profile.class).getBody();
    } catch (Exception e) {
      throw new RuntimeException("Failed to get profile", e);
    }
  }

  public void deleteProfile(String userId) {
    UriComponentsBuilder builder = UriComponentsBuilder.fromUriString("http://profile-storage:8080/profiles");
    HttpHeaders headers = new HttpHeaders();
    headers.setContentType(MediaType.APPLICATION_JSON);
    try {
      restTemplate.delete(builder.toUriString());
    } catch (Exception e) {
      throw new RuntimeException("Failed to delete profile", e);
    }
  }
}
