    private static final int BATCH_SIZE = 100;
    private static final int BUFFER_SIZE = 2048;
    private static final String API_ENDPOINT = "https://example.com/api";

    public static void main(String[] args) {
        List<NFAPI_CRC_INDICATION_PDU_T> crcIndications = generateCRCIndications();
        sendCRCIndications(crcIndications);
    }

    private static List<NFAPI_CRC_INDICATION_PDU_T> generateCRCIndications() {
        List<NFAPI_CRC_INDICATION_PDU_T> crcIndications = new ArrayList<>();

        for (int i = 0; i < BATCH_SIZE; i++) {
            RX_UE_INFORMATION_TAG rxUeInformationTag = generateRX_UE_INFORMATION_TAG();
            int rnti = generateRNTI();
            CRC_INDICATION_REL8_TAG crcIndicationRel8Tag = generateCRC_INDICATION_REL8_TAG(rxUeInformationTag.timestamp);

            NFAPI_CRC_INDICATION_PDU_T crcIndication = new NFAPI_CRC_INDICATION_PDU_T(rxUeInformationTag, rnti, crcIndicationRel8Tag);
            crcIndications.add(crcIndication);
        }

        return crcIndications;
    }

    private static RX_UE_INFORMATION_TAG generateRX_UE_INFORMATION_TAG() {
        Random rand = new Random();
        long timestamp = System.currentTimeMillis();

