    }

    private static int generateRNTI() {
        Random rand = new Random();
        return rand.nextInt();
    }

    private static CRC_INDICATION_REL8_TAG generateCRC_INDICATION_REL8_TAG(long timestamp) {
        Random rand = new Random();
        int rxUeInformationIndex = rand.nextInt();

        return new CRC_INDICATION_REL8_TAG(timestamp, rxUeInformationIndex);
    }

    private static void sendCRCIndications(List<NFAPI_CRC_INDICATION_PDU_T> crcIndications) {
        // Validate URLs before attempting file uploads
