            URL url = generateURL(crcIndication);
            if (!validateURL(url)) {
                continue;
            }
        }

        // Retry logic for handling network errors and backoff delays
        int retryCount = 0;
        while (retryCount < MAX_RETRY_COUNT) {
            try {
                sendCRCIndicationsAsync(crcIndications);
                break;
            } catch (IOException e) {
                if (retryCount >= MAX_RETRY_COUNT) {
                    throw new RuntimeException("Maximum retry count exceeded. Giving up on file upload.");
                }

                int backoffDelay = calculateBackoffDelay(retryCount);
                System.out.println("Failed to send CRC indications. Retrying in " + backoffDelay + " milliseconds...");
                retryCount++;
                try {
                    Thread.sleep(backoffDelay);
                } catch (InterruptedException e1) {
                    // Ignore
                }
            }
        }
    }

    private static void sendCRCIndicationsAsync(List<NFAPI_CRC_INDICATION_PDU_T> crcIndications) throws IOException {
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("crcIndications", crcIndications);

        String jsonData = jsonObject.toString();
        byte[] data = jsonData.getBytes(StandardCharsets.UTF_8);

        URL url = generateURL(null);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setDoOutput(true);
        connection.setRequestMethod("POST");
        connection.setFixedLengthStreamingMode(data.length);
        connection.setRequestProperty("Content-Type", "application/json; charset=UTF-8");
        connection.connect();

        try (DataOutputStream output = new DataOutputStream(connection.getOutputStream())) {
            output.write(data);
        }
    }

    private static int calculateBackoffDelay(int retryCount) {
        // Exponential backoff with jitter
        int delay = (int) Math.round(Math.random() * BACKOFF_JITTER_FACTOR * Math.pow(2, retryCount - 1));
        return Math.min(delay, MAX_BACKOFF_DELAY);
    }

    private static URL generateURL(NFAPI_CRC_INDICATION_PDU_T crcIndication) {
        try {
            String url = API_ENDPOINT;
            if (crcIndication != null) {
                url += "?timestamp=" + crcIndication.getTimestamp();
            }
            return new URL(url);
        } catch (MalformedURLException e) {
            throw new RuntimeException("Invalid URL: " + API_ENDPOINT, e);
        }
    }

    private static boolean validateURL(URL url) {
        // Implement validation logic here
        return true;
    }
}
