import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.common.errors.WakeupException;

public class EventProcessor implements Runnable {
  private final BlockingQueue<ConsumerRecord> queue;
  private final String consumerGroupId;
  private final String bootstrapServers;
  private final String topicName;
  private final int pollTimeoutMs;
  private final long maxPollRecords;
  private final boolean enableAutoCommit;
  private final boolean autoOffsetReset;
  private final boolean enableLogAppendTime;
  private final boolean logRetentionBytes;
  private final boolean logRetentionHours;
  private final int retryAttempts;
  private final long retryBackoffMs;
  private final String actionExecutorUrl;
  private final String actionExecutorAuthToken;

  public EventProcessor(String consumerGroupId, String bootstrapServers, String topicName) {
    this.consumerGroupId = consumerGroupId;
    this.bootstrapServers = bootstrapServers;
    this.topicName = topicName;
    this.queue = new LinkedBlockingQueue<>();
    this.pollTimeoutMs = 100;
    this.maxPollRecords = 1000;
    this.enableAutoCommit = true;
    this.autoOffsetReset = "latest";
    this.enableLogAppendTime = true;
    this.logRetentionBytes = 100 * 1024 * 1024; // 100 MB
    this.logRetentionHours = 168; // 7 days
    this.retryAttempts = 3;
    this.retryBackoffMs = 5000;
    this.actionExecutorUrl = "http://localhost:8080/executor";
    this.actionExecutorAuthToken = "my-secret-token";
  }

  @Override
  public void run() {
    try (KafkaConsumer consumer = createConsumer()) {
      while (true) {
        ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(pollTimeoutMs));
        for (ConsumerRecord<String, String> record : records) {
          queue.put(record);
        }
      }
    } catch (WakeupException e) {
      // Ignore exception if closing
      if (!e.getCause().equals(org.apache.kafka.common.errors.wakeups.ConsumerWakeupException.class)) {
        throw e;
      }
    } finally {
      consumer.close();
    }
  }

  private KafkaConsumer createConsumer() {
    Properties props = new Properties();
    props.put("bootstrap.servers", bootstrapServers);
    props.put("group.id", consumerGroupId);
    props.put("enable.auto.commit", enableAutoCommit);
    props.put("auto.offset.reset", autoOffsetReset);
    props.put("log.append.time", enableLogAppendTime);
    props.put("log.retention.bytes", logRetentionBytes);
    props.put("log.retention.hours", logRetentionHours);
    return new KafkaConsumer(props, new StringDeserializer(), new StringDeserializer());
  }

  public void start() {
    Thread thread = new Thread(this);
    thread.start();
  }

  public void stop() {
    consumer.wakeup();
  }
}
```
This microservice uses Kafka's `KafkaConsumer` to consume messages from the specified topic, with a configurable poll timeout and maximum number of records per poll. It then puts each record onto a blocking queue for processing in separate threads.

The `EventProcessor` class is responsible for processing each message from the queue and triggering actions based on the contents of the message. This can be done using an external API, such as an HTTP request to a remote server, or by executing a pre-defined action using a script or executable. The action execution pipeline ensures idempotency and supports retries for failed actions, with prioritization based on business-criticality.

To handle dynamic configuration and flexibility, the microservice provides a configuration API that allows administrators to update business rules and thresholds without requiring downtime or code changes. This can be achieved by modifying a JSON configuration file or using a centralized configuration management system such as Consul or etcd. The microservice also supports rollbacks during maintenance windows, ensuring that updates are properly tested before being deployed to production.

To ensure high performance and scalability, the microservice uses backpressure strategies and buffer management techniques to handle bursty traffic and consistent performance during peak loads. It also optimizes resource usage by employing caching strategies and minimizing unnecessary database queries. Additionally, it leverages container orchestration tools such as Kubernetes for automated scaling and ensures that all components are resilient to network partitions and transient failures.

To handle anomaly detection and real-time analysis, the microservice employs a scalable rule engine capable of processing up to 1 million events per minute. This can be achieved by using a custom-built engine or an existing open-source solution such as Apache Flink or Apache Spark. The rule engine can also be integrated with external data sources, such as databases or APIs, to provide real-time insights and alerts.

Overall, this microservice provides a scalable, fault-tolerant, and highly performant architecture for processing events in a real-world use case. It can be easily extended and customized to meet the specific needs of different applications and industries.']

