    // Generate up to N random CRC indications
    for (int i = 0; i < N; i++) {
      generateAndPersistCrcIndication();
    }
  }

  private void generateAndPersistCrcIndication() {
    try {
      // Generate a new CRC indication
      NFAPI_CRC_INDICATION_PDU_T crcIndication = generateCrcIndication();

      // Persist the CRC indication in the database
      persistCrcIndication(crcIndication);
    } catch (Exception e) {
      // Handle any errors that may occur during persistence
      handlePersistenceError(e);
    }
  }

  private NFAPI_CRC_INDICATION_PDU_T generateCrcIndication() {
    Random random = new Random();
    int rnti = random.nextInt(100);
    int crcFlag = random.nextBoolean() ? 1 : 0;

    NFAPI_CRC_INDICATION_PDU_T crcIndication = new NFAPI_CRC_INDICATION_PDU_T();
    crcIndication.setRX_UE_INFORMATION_TAG(rnti);
    crcIndication.setCRC_INDICATION_REL8_TAG(crcFlag);

    return crcIndication;
  }

  private void persistCrcIndication(NFAPI_CRC_INDICATION_PDU_T crcIndication) {
    // Persist the CRC indication in the database asynchronously
    BackgroundTask task = new BackgroundTask();
    task.setData(crcIndication);
    tasks.add(task);
  }

  private void handlePersistenceError(Exception e) {
    // Handle any errors that may occur during persistence
    log.error("Error occurred while persisting CRC indication", e);
  }

