#define RETRY_PERIOD 300 // milliseconds
#define CACHE_SIZE 1024 * 1024 // 1 MB
#define CACHE_EXPIRATION_TIMEOUT 600 // seconds

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARN,
    LOG_ERROR,
    LOG_FATAL
} LogLevel;

typedef struct {
    int level;
    char message[LOG_BUFFER_SIZE];
    time_t timestamp;
} LogEntry;

void log_entry(int level, const char *message) {
    // Check if the current process is still alive
    if (kill(getpid(), 0)) {
        // If not, restart it with a delay of RECONNECT_DELAY seconds
        sleep(RECONNECT_DELAY);
    }

    // Create and fill a new log entry
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->level = level;
    strcpy(entry->message, message);
    entry->timestamp = time(NULL);

    // Add the log entry to the cache
    pthread_mutex_lock(&cache_mutex);
    if (cache_size < CACHE_SIZE) {
        cache[cache_tail++] = entry;
        cache_size++;
    } else {
        free(entry);
    }
    pthread_mutex_unlock(&cache_mutex);
}

void flush_cache() {
    // Check if there is anything to flush
    if (cache_size == 0) {
        return;
    }

    // Iterate over the cache entries and send them to the logging system
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_size; i++) {
        LogEntry *entry = cache[i];
        syslog(LOG_DEBUG, "%s", entry->message);
        free(entry);
    }
    cache_size = 0;
    pthread_mutex_unlock(&cache_mutex);
}

void log_retry(int level, const char *message) {
    // Check if the current process is still alive
    if (kill(getpid(), 0)) {
        // If not, restart it with a delay of RECONNECT_DELAY seconds
        sleep(RECONNECT_DELAY);
    }

    // Create and fill a new log entry
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->level = level;
    strcpy(entry->message, message);
    entry->timestamp = time(NULL);

    // Add the log entry to the cache
    pthread_mutex_lock(&cache_mutex);
    if (cache_size < CACHE_SIZE) {
        cache[cache_tail++] = entry;
        cache_size++;
    } else {
        free(entry);
    }
    pthread_mutex_unlock(&cache_mutex);

    // Check if the cache is full and needs to be flushed
    if (cache_size == CACHE_SIZE) {
        flush_cache();
    }
}

