Here's an implementation of the highly available, distributed session service library in C:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <redis/redis.h>

// Define the session structure
typedef struct {
    char* user_id;
    char* role;
    time_t last_accessed;
} session_t;

// Initialize the Redis client
static redisContext *redis_client = NULL;

// Connect to the Redis server
int redis_connect(const char *ip, int port) {
    if (redis_client != NULL) {
        return 0;
    }

    // Create a new Redis context
    redis_client = redisConnect(ip, port);

    // Check for errors
    if (!redis_client || redis_client->err) {
        printf("Error connecting to Redis: %s\n", redis_client->errstr);
        return -1;
    }

    return 0;
}

// Disconnect from the Redis server
void redis_disconnect() {
    if (redis_client != NULL) {
        redisFree(redis_client);
        redis_client = NULL;
    }
}

// Set a session value
int set_session(const char *user_id, const char *role) {
    // Create a new Redis command object
    redisReply *reply = redisCommand("SET %s %s", user_id, role);

    // Check for errors
    if (reply->type == REDIS_REPLY_ERROR) {
        printf("Error setting session value: %s\n", reply->str);
        freeReplyObject(reply);
        return -1;
    }

    // Set the last accessed time
    set_session_last_accessed(user_id);

    // Free the Redis reply object
    freeReplyObject(reply);

    return 0;
}

// Get a session value
char* get_session(const char *user_id) {
    // Create a new Redis command object
    redisReply *reply = redisCommand("GET %s", user_id);

    // Check for errors
    if (reply->type == REDIS_REPLY_ERROR) {
        printf("Error getting session value: %s\n", reply->str);
        freeReplyObject(reply);
        return NULL;
    }

    // Set the last accessed time
    set_session_last_accessed(user_id);

    // Free the Redis reply object
    char* role = (char*) malloc(sizeof(char) * 256);
    strncpy(role, reply->str, 256);
    freeReplyObject(reply);

    return role;
}

// Set the last accessed time for a session
void set_session_last_accessed(const char *user_id) {
    // Create a new Redis command object
    redisReply *reply = redisCommand("SETEX %s %d", user_id, get_current_timestamp());

    // Check for errors
    if (reply->type == REDIS_REPLY_ERROR) {
        printf("Error setting session last accessed time: %s\n", reply->str);
        freeReplyObject(reply);
        return;
    }

    // Free the Redis reply object
    freeReplyObject(reply);
}

// Get the current timestamp in seconds
long get_current_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long) ((double) ts.tv_sec + (double) ts.tv_nsec / 1000000000);
}

// Check if a session is valid
int check_session(const char *user_id) {
    // Create a new Redis command object
    redisReply *reply = redisCommand("EXISTS %s", user_id);

    // Check for errors
    if (reply->type == REDIS_REPLY_ERROR) {
        printf("Error checking session: %s\n", reply->str);
        freeReplyObject(reply);
        return -1;
    }

    // Free the Redis reply object
    int exists = reply->integer;
    freeReplyObject(reply);

    return exists;
}
```
