// Define struct for TX_MESSAGE data structure
struct tx_message {
    uint32_t transport_channel_identifier;
    uint8_t transport_format_indication;
    int8_t tx_power_level;
};

// Define struct for dynamic array of TX_MESSAGEs
struct tx_messages {
    size_t capacity;
    size_t count;
    struct tx_message *messages;
};

// Function to initialize and manage a dynamic array of TX_MESSAGEs
void tx_messages_init(struct tx_messages *txmsgs) {
    if (!txmsgs) return;

    // Allocate memory for the dynamic array
    txmsgs->count = 0;
    txmsgs->capacity = 16;
    txmsgs->messages = malloc(sizeof(struct tx_message) * txmsgs->capacity);
}

// Function to add a new TX_MESSAGE to the dynamic array
void tx_messages_add(struct tx_messages *txmsgs, struct tx_message msg) {
    if (!txmsgs || !msg.transport_channel_identifier || !msg.transport_format_indication || !msg.tx_power_level) return;

    // Check if the capacity of the dynamic array needs to be increased
    if (txmsgs->count == txmsgs->capacity) {
        txmsgs->capacity *= 2;
        txmsgs->messages = realloc(txmsgs->messages, sizeof(struct tx_message) * txmsgs->capacity);
    }

    // Add the new TX_MESSAGE to the dynamic array
    txmsgs->messages[txmsgs->count++] = msg;
}

// Function to get a TX_MESSAGE from the dynamic array by its index
struct tx_message *tx_messages_get(struct tx_messages *txmsgs, size_t idx) {
    if (!txmsgs || idx >= txmsgs->count) return NULL;
    return &txmsgs->messages[idx];
}

// Function to remove a TX_MESSAGE from the dynamic array by its index
void tx_messages_remove(struct tx_messages *txmsgs, size_t idx) {
    if (!txmsgs || idx >= txmsgs->count) return;

    // Shift all remaining messages to the left of the removed message
    for (size_t i = idx + 1; i < txmsgs->count; ++i) {
        txmsgs->messages[i - 1] = txmsgs->messages[i];
    }

    // Decrement the count of messages
    --txmsgs->count;
}

// Function to release the resources allocated by the dynamic array
void tx_messages_free(struct tx_messages *txmsgs) {
    if (!txmsgs) return;
    free(txmsgs->messages);
    txmsgs->messages = NULL;
}
