                unique_lock<mutex> lock(queueLock);

                // Wait for an event to become available in the queue
                eventAvailable.wait(lock, [this]() { return !events.empty(); });

                // Handle the next event in the queue
                while (!terminateFlag && !events.empty()) {
                    // Get the next event from the queue
                    CUSTOM_EVENT_RECORD* event = events.front();
                    events.pop_front();

                    // Add the event to the dispatcher's event pool
                    dispatcher->addEvent(event);
                }
            }
        });
    }

    // Terminate the Producer Thread and Release All Events in the Queue
    void terminate() {
        unique_lock<mutex> lock(queueLock);

        // Set the terminate flag to indicate that the thread should terminate
        terminateFlag = true;

        // Notify the producer thread of the termination request
        eventAvailable.notify_one();
    }
};

// Main Function for Testing
int main() {
    // Create an event pool and dispatcher
    EventPool* pool = new EventPool();
    EventDispatcher* dispatcher = new EventDispatcher();

    // Create a producer thread and start processing events
    EventProducer* producer = new EventProducer(dispatcher);
    producer->start();

    // Create consumer threads and start processing events
    EventConsumer* consumer1 = new EventConsumer(pool);
    consumer1->start();
    EventConsumer* consumer2 = new EventConsumer(pool);
    consumer2->start();

    // Terminate the producer thread
    producer->terminate();

    // Wait for all events to be processed
    while (producer->eventAvailable.wait_for(lock, std::chrono::seconds(1)) != std::cv_status::no_timeout) {
        // Handle any remaining events in the queue
        while (!events.empty()) {
            // Get the next event from the queue
            CUSTOM_EVENT_RECORD* event = events.front();
            events.pop_front();

            // Add the event to the dispatcher's event pool
            dispatcher->addEvent(event);
        }
    }

    // Terminate all consumer threads
    consumer1->terminate();
    consumer2->terminate();
}"]

