// Message Queue Library
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <memory>
#include <chrono>

class MessageQueue {
public:
    explicit MessageQueue(size_t capacity = 100);

    ~MessageQueue();

    void push(const std::string& message);

    std::string pop();

private:
    // message queue
    std::queue<std::string> mQueue;

    // mutex to synchronize access to the queue
    std::mutex mMutex;

    // condition variable to signal when a new message is available
    std::condition_variable mNewMessageCondVar;

    // condition variable to signal when the queue is empty
    std::condition_variable mEmptyQueueCondVar;
};
```

```
// Message Queue Implementation
#include "message_queue.h"

// constructor
MessageQueue::MessageQueue(size_t capacity) {
    // initialize message queue with given capacity
    mQueue = std::queue<std::string>(capacity);
}

// destructor
MessageQueue::~MessageQueue() {}

// push a new message to the queue
void MessageQueue::push(const std::string& message) {
    // acquire lock on mutex
    std::lock_guard<std::mutex> lockGuard(mMutex);

    // push message onto queue
    mQueue.push(message);

    // signal new message condition variable
    mNewMessageCondVar.notify_all();
}

// pop a message from the queue
std::string MessageQueue::pop() {
    // acquire lock on mutex
    std::lock_guard<std::mutex> lockGuard(mMutex);

    // wait for new message condition variable to be signaled or queue to become empty
    mNewMessageCondVar.wait(lockGuard, [this] { return !mQueue.empty() || mEmptyQueueCondVar.wait_for(std::chrono::seconds(1)) != std::cv_status::no_timeout; });

    // check if queue is empty
    if (mQueue.empty()) {
        // signal empty queue condition variable
        mEmptyQueueCondVar.notify_all();

        // return empty string
        return "";
    } else {
        // pop message from queue and return it
        std::string message = mQueue.front();
        mQueue.pop();
        return message;
    }
}
```

The above code implements a basic message queue system using the C++ Standard Template Library (STL) containers `queue` and `mutex`. The class `MessageQueue` provides push and pop operations for messages, with locking implemented using a mutex to ensure thread-safe access to the underlying data structure. The constructor takes an optional argument for the capacity of the queue, with a default value of 100 if not specified.

The `push` method acquires a lock on the mutex and pushes a new message onto the queue using the `queue::push` method. It then signals the `newMessageCondVar`, which is used by the `pop` method to wait for new messages or for the queue to become empty.

The `pop` method also acquires a lock on the mutex and waits for either a new message to be available using the `newMessageCondVar`, or for the queue to become empty using the `emptyQueueCondVar`. If the queue is empty, it signals the `emptyQueueCondVar` and returns an empty string. Otherwise, it pops the front message from the queue and returns it.

The `~MessageQueue()` destructor simply cleans up any resources used by the queue.']

