Config_t* load_config(char* filepath) {
    json_object* config = json_object_from_file(filepath);
    if (!config) {
        printf("Error loading configuration: %s\n", strerror(errno));
        return NULL;
    }
    Config_t* retval = malloc(sizeof(Config_t));
    retval->refcount = 1;
    retval->config = config;
    return retval;
}

void release_config(Config_t* config) {
    if (!config) {
        return;
    }
    pthread_mutex_lock(&config->lock);
    config->refcount--;
    if (config->refcount == 0) {
        json_object_put(config->json);
        free(config);
    }
    pthread_mutex_unlock(&config->lock);
}

