        pthread_mutex_lock(&context->ue_list_lock);
        int ue_count = context->ue_count;
        UE_t* ue_list = context->ue_list;
        for (int i = 0; i < ue_count; i++) {
            // Process CRC indications for each UE
        }
        pthread_mutex_unlock(&context->ue_list_lock);
    }
}

void token_bucket_fill(Context_t* context) {
    sem_wait(&context->token_bucket);
    if (sem_getvalue(&context->token_bucket, &context->tokens_available) < 0) {
        printf("Error filling token bucket: %s\n", strerror(errno));
        return;
    }
}

void token_bucket_empty(Context_t* context) {
    sem_post(&context->token_bucket);
    if (sem_getvalue(&context->token_bucket, &context->tokens_available) < 0) {
        printf("Error emptying token bucket: %s\n", strerror(errno));
        return;
    }
}

int main(int argc, char** argv) {
    if (argc != 3) {
        printf("Usage: %s <config file> <UE list file>\n", argv[0]);
        return 1;
    }
    Config_t* config = load_config(argv[1]);
    if (!config) {
        printf("Error loading configuration\n");
        return 1;
    }
    UE_t ue_list[MAX_UE_COUNT];
    int ue_count = 0;
    FILE* fp = fopen(argv[2], "r");
    if (!fp) {
        printf("Error opening UE list file: %s\n", strerror(errno));
        return 1;
    }
    while (fscanf(fp, "%s %d", ue_list[ue_count].ue_id, &ue_list[ue_count].rnti) == 2 && ue_count < MAX_UE_COUNT) {
        ue_count++;
    }
    fclose(fp);
    Context_t context = {0};
    pthread_mutex_init(&context.ue_list_lock, NULL);
    pthread_mutex_init(&context.rnti_list_lock, NULL);
    sem_init(&context.token_bucket, 1, TOKEN_BUCKET_SIZE);
    context.config = config;
    context.ue_count = ue_count;
    context.ue_list = ue_list;
    pthread_t thread;
    if (pthread_create(&thread, NULL, process_crc_indications, &context) < 0) {
        printf("Error creating processing thread: %s\n", strerror(errno));
        return 1;
    }
    token_bucket_fill(&context);
    while (1) {
        sleep(TOKEN_BUCKET_EMPTY);
        token_bucket_empty(&context);
    }
}
