// Function to calculate the number of disjoint pairs in an integer array using a Union-Find data structure
int count_disjoint_pairs(int *arr, int size) {
    // Initialize the Union-Find data structure with all elements as their own sets
    int *parent = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        parent[i] = i;
    }

    // Find and union the elements that are disjoint, keeping track of the number of disjoint pairs
    int count = 0;
    for (int i = 0; i < size - 1; i++) {
        if (arr[i] != arr[i + 1]) {
            int root_i = find(parent, arr[i]);
            int root_j = find(parent, arr[i + 1]);
            if (root_i != root_j) {
                union(parent, root_i, root_j);
                count++;
            }
        }
    }

    // Clean up the Union-Find data structure
    free(parent);

    return count;
}

// Find the root of a set in the Union-Find data structure
int find(int *parent, int element) {
    if (element != parent[element]) {
        // Recursively find the root of the parent set
        return find(parent, parent[element]);
    } else {
        return element;
    }
}

// Union two sets in the Union-Find data structure
void union(int *parent, int set_1, int set_2) {
    // Make set_1 the parent of set_2
    parent[set_2] = set_1;
}

int main() {
    // Test case: input array is [1, 3, 5, 7, 9], output should be 4 (4 disjoint pairs)
    int arr[] = {1, 3, 5, 7, 9};
    int size = sizeof(arr) / sizeof(int);
    printf("Number of disjoint pairs: %d\n", count_disjoint_pairs(arr, size));

    return 0;
}
