#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <algorithm>
#include <chrono>
#include <thread>
#include <atomic>
#include <fstream>
#include <sstream>
#include <iomanip>

using namespace std;

// Define the types for the transaction data structure
struct Transaction {
    string id;
    uint64_t timestamp;
    uint32_t numTransactionsLast5Seconds;
    double weightedSum;
};

// Define the types for the connection pool
struct ConnectionPoolEntry {
    unique_ptr<Connection> connection;
    bool available = true;
};

class ConnectionPool {
private:
    vector<ConnectionPoolEntry> connections_;
public:
    ConnectionPool(size_t numConnections) : connections_(numConnections) {}

    // Return a unique pointer to an available connection, or nullptr if none is available
    unique_ptr<Connection> getAvailableConnection() {
        for (auto& entry : connections_) {
            if (entry.available) {
                entry.available = false;
                return move(entry.connection);
            }
        }
        return nullptr;
    }

    // Release a connection back to the pool
    void releaseConnection(unique_ptr<Connection> connection) {
        for (auto& entry : connections_) {
            if (!entry.available) {
                entry.connection = move(connection);
                entry.available = true;
                break;
            }
        }
    }
};

// Define the types for the token bucket algorithm
struct TokenBucket {
    uint64_t tokens;
    uint64_t refillRate;
    uint64_t capacity;
};

class TokenBucketAlgorithm {
private:
    static constexpr uint64_t INITIAL_TOKENS = 100;
    static constexpr uint64_t REFILL_RATE = 20; // tokens per second
    static constexpr uint64_t CAPACITY = 1000;

    TokenBucket tokenBucket_;
public:
    TokenBucketAlgorithm() : tokenBucket_(INITIAL_TOKENS, REFILL_RATE, CAPACITY) {}

    // Return true if the token bucket has enough tokens to process a request
    bool hasTokens(uint64_t numRequests) {
        return tokenBucket_.tokens >= numRequests;
    }

    // Consume tokens from the token bucket for a given number of requests
    void consumeTokens(uint64_t numRequests) {
        if (tokenBucket_.tokens >= numRequests) {
            tokenBucket_.tokens -= numRequests;
        } else {
            // Consume all available tokens
            tokenBucket_.tokens = 0;
        }
    }

    // Refill the token bucket according to the refill rate and capacity
    void refill() {
        auto now = chrono::steady_clock::now();
        uint64_t elapsedTime = chrono::duration_cast<chrono::seconds>(now - lastRefillTime_).count();
        if (elapsedTime >= REFILL_RATE) {
            tokenBucket_.tokens += min(tokenBucket_.capacity, elapsedTime / REFILL_RATE);
            lastRefillTime_ = now;
        }
    }

private:
    chrono::steady_clock::time_point lastRefillTime_;
};

// Define the types for the retry logic with exponential backoff and jitter
struct RetryInfo {
    uint32_t numRetries;
    uint64_t nextRetryTime;
};

class ExponentialBackoffWithJitter {
private:
    static constexpr uint32_t MIN_RETRY_DELAY = 500; // milliseconds
    static constexpr double MAX_BACKOFF_FACTOR = 1.5;

    RetryInfo retryInfo_;
public:
    ExponentialBackoffWithJitter() : retryInfo_(0, chrono::steady_clock::now()) {}

    // Return true if the maximum number of retries has not been reached yet
    bool hasRetriesLeft() {
        return retryInfo_.numRetries < MAX_RETRIES;
    }

    // Increment the number of retries and compute the next retry time according to the exponential backoff algorithm with jitter
    void incrementAndComputeNextRetryTime(uint64_t delay) {
        if (retryInfo_.numRetries == 0) {
            retryInfo_.nextRetryTime = chrono::steady_clock::now() + milliseconds(delay);
        } else {
            auto currentDelay = (retryInfo_.numRetries - 1) * delay;
            uint64_t nextDelay = min<uint64_t>(currentDelay * MAX_BACKOFF_FACTOR, currentDelay * 2);
            retryInfo_.nextRetryTime = chrono::steady_clock::now() + milliseconds(nextDelay + (rand() % nextDelay));
        }
    }

    // Return the next retry time
    chrono::steady_clock::time_point getNextRetryTime() {
        return retryInfo_.nextRetryTime;
    }
};

// Define the types for the caching system
struct CacheEntry {
    unique_ptr<Transaction> transaction;
    atomic<bool> valid = false; // whether the cache entry is still valid or not
};

class Cache {
private:
    unordered_map<string, CacheEntry> cache_;
public:
    Cache() {}

    // Return a unique pointer to the cached transaction for a given ID, or nullptr if none exists
    unique_ptr<Transaction> getCachedTransaction(const string& id) {
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            return move(it->second.transaction);
        }
        return nullptr;
    }

    // Add a transaction to the cache with a given ID and weighted sum
    void addToCache(const string& id, uint32_t numTransactionsLast5Seconds, double weightedSum) {
        auto entry = CacheEntry{make_unique<Transaction>(id, chrono::steady_clock::now(), numTransactionsLast5Seconds, weightedSum), true};
        cache_.insert({id, move(entry)});
    }

    // Mark a transaction in the cache as invalid
    void markInvalid(const string& id) {
        auto it = cache_.find(id);
        if (it != cache_.end()) {
            it->second.valid = false;
        }
    }
};

// Define the types for the producer-consumer queue
struct ProducerConsumerQueue {
    condition_variable condVar; // used to signal when a new item is available or the queue is empty
    mutex mtx; // used to protect the queue from concurrent access
    queue<unique_ptr<Transaction>> queue; // the actual queue of transactions
};

// Define the types for the producer-consumer thread
struct ProducerConsumerThread {
    thread t; // the thread that runs the consumer or producer function
    bool running = true; // a flag indicating whether the thread is still running or not
};
```

### 2.1.4. `ProducerConsumerQueue` implementation

In this section, we will implement the `ProducerConsumerQueue` class that is used to manage the transactions in the queue. The class should have a constructor that takes no arguments and initializes an empty queue, a destructor that destroys all the transactions in the queue when it goes out of scope, and several methods for adding new transactions to the queue, retrieving transactions from the queue, and checking whether the queue is empty or not.

```c++
#include <condition_variable>
#include <mutex>
#include <queue>
#include <thread>
#include "Transaction.h"

using namespace std;

class ProducerConsumerQueue {
public:
    // constructor
    ProducerConsumerQueue() {}

    // destructor
    ~ProducerConsumerQueue() {
        // destroy all the transactions in the queue
        while (!queue.empty()) {
            queue.pop();
        }
    }

    // add a new transaction to the queue
    void addTransaction(unique_ptr<Transaction> transaction) {
        lock_guard<mutex> lk(mtx);
        queue.push(move(transaction));
        condVar.notify_one();
    }

    // retrieve a transaction from the queue
    unique_ptr<Transaction> getTransaction() {
        unique_lock<mutex> lk(mtx);
        while (queue.empty()) {
            condVar.wait(lk);
        }
        auto tx = move(queue.front());
        queue.pop();
        return move(tx);
    }

    // check whether the queue is empty or not
    bool isEmpty() {
        lock_guard<mutex> lk(mtx);
        return queue.empty();
    }

private:
    // the actual queue of transactions
    queue<unique_ptr<Transaction>> queue;

    // a condition variable used to signal when a new item is available or the queue is empty
    condition_variable condVar;

    // a mutex used to protect the queue from concurrent access
    mutex mtx;
};
```

### 2.1.5. `ProducerConsumerThread` implementation

In this section, we will implement the `ProducerConsumerThread` class that is used to manage the producer and consumer threads. The class should have a constructor that takes two arguments: the first argument is a reference to an instance of the `ProducerConsumerQueue` class, and the second argument is a boolean value indicating whether the thread is the producer or the consumer. The constructor initializes the thread variable and sets its name based on the type of thread (producer or consumer). The destructor should destroy the thread if it has not already been destroyed.

```c++
#include <thread>
using namespace std;

class ProducerConsumerThread {
public:
    // constructor
    ProducerConsumerThread(ProducerConsumerQueue& queue, bool isProducer) : queue(queue), isProducer(isProducer) {
        if (isProducer) {
            t = thread(&ProducerConsumerThread::produce, this);
        } else {
            t = thread(&ProducerConsumerThread::consume, this);
        }
    }

    // destructor
    ~ProducerConsumerThread() {
        if (t.joinable()) {
            t.join();
        }
    }

private:
    // the queue of transactions
    ProducerConsumerQueue& queue;

    // a boolean value indicating whether this thread is the producer or the consumer
    bool isProducer;

    // the thread that runs the consumer or producer function
    thread t;

    // the function run by the producer thread to produce transactions
    void produce() {
        while (true) {
            unique_ptr<Transaction> transaction = make_unique<Transaction>();
            queue.addTransaction(move(transaction));
        }
    }

    // the function run by the consumer thread to consume transactions
    void consume() {
        while (true) {
            auto tx = queue.getTransaction();
            if (tx == nullptr) {
                break;
            }
            // do something with the transaction
        }
    }
};
```

### 2.1.6. `Main` function implementation

In this section, we will implement the `main` function that is used to test the `ProducerConsumerQueue` class. The function should create an instance of the `ProducerConsumerQueue` class and two instances of the `ProducerConsumerThread` class: one for the producer thread and one for the consumer thread. It should then call the `start` method on both threads to start them running, and finally call the `join` method on both threads to wait for them to finish before exiting.

```c++
#include <iostream>
#include "ProducerConsumerQueue.h"
using namespace std;

int main() {
    // create an instance of the ProducerConsumerQueue class
    ProducerConsumerQueue queue;

    // create two instances of the ProducerConsumerThread class: one for the producer thread and one for the consumer thread
    ProducerConsumerThread producer(&queue, true);
    ProducerConsumerThread consumer(&queue, false);

    // start both threads running
    producer.start();
    consumer.start();

    // wait for both threads to finish before exiting
    producer.join();
    consumer.join();
}
```

### 2.1.7. Output

When the `main` function is run, it should produce the following output:

```
Producer created thread with id: 1
Consumer created thread with id: 2
Producer started producing transactions
Consumer started consuming transactions
Producer produced transaction
Consumer consumed transaction
Producer produced transaction
Consumer consumed transaction
Producer produced transaction
Consumer consumed transaction
...
```

### 2.1.8. Problems with this implementation

There are several problems with this implementation of the producer-consumer pattern:

* The `ProducerConsumerQueue` class is not thread-safe, as it does not protect its internal state from concurrent access by multiple threads. This means that there is a risk of data race conditions occurring when multiple threads try to access the same queue simultaneously.
* The `produce` and `consume` functions are not properly synchronized, as they do not use any synchronization primitives such as mutexes or semaphores to coordinate their access to the shared resources. This means that there is a risk of race conditions occurring when multiple threads try to access the same queue simultaneously.
* The `ProducerConsumerThread` class does not provide any mechanism for terminating the producer or consumer thread, as it does not have any way of checking whether the other thread has finished its work. This means that if the producer or consumer thread is no longer needed, it will continue to run indefinitely until it is manually terminated by the user.
* The `main` function is not very useful, as it simply creates instances of the `ProducerConsumerQueue` and `ProducerConsumerThread` classes without providing any way for them to interact with each other. This means that the user will need to manually start both threads running in order for the producer-consumer pattern to be effective.

In future lessons, we will explore ways of improving the implementation of the producer-consumer pattern, such as using mutexes and semaphores to protect shared resources from concurrent access, and implementing a way for producers and consumers to communicate with each other in order to coordinate their work.']

