    TransactionProcessor(int numProcessingNodes) : numProcessingNodes_(numProcessingNodes) {}

    // Process a transaction and return its ID
    int processTransaction(const string& txnId, const double& weightedSum) {
        unique_lock<mutex> lock(mu_);
        // Check if the queue is full and the system is still operating within the limits
        while (queue_.size() >= maxQueueSize_) {
            condVar_.wait(lock);
        }
        int id = nextId_++;
        Transaction t;
        t.id = id;
        t.txnId = txnId;
        t.weightedSum = weightedSum;
        // Add the transaction to the queue and notify any waiting threads
        queue_.push(t);
        condVar_.notify_all();
        return id;
    }

