    queue<Transaction> queue_;
    map<int, Transaction> transactions_;
    atomic<int> nextId_ = 0;
    mutex mu_;
    condition_variable condVar_;
    const int maxQueueSize_ = 10000; // Maximum size of the transaction queue
};
