['Here is an example of how you could implement the doubly-linked list of `NFAPI_CRC_INDICATION_PDU_T` structures:
```c
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "jemalloc/jemalloc.h"

// Define the structure to hold an RF frame's CRC indication
typedef struct NFAPI_CRC_INDICATION_PDU_T {
  uint16_t validRXUEInformationTag;
  uint32_t rnti;
  uint8_t crcIndicationRel8Tag;
  bool CRCFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure to hold a doubly-linked list of CRC indications
typedef struct DoublyLinkedList {
  // Pointer to the head of the list
  NFAPI_CRC_INDICATION_PDU_T* head;
  // Pointer to the tail of the list
  NFAPI_CRC_INDICATION_PDU_T* tail;
} DoublyLinkedList;

// Define a thread-safe way to access and modify the doubly-linked list
static pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

void addCRCIndication(NFAPI_CRC_INDICATION_PDU_T* crc) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&listLock);

  // Create a new node for the CRC indication
  NFAPI_CRC_INDICATION_PDU_T* newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  memcpy(newNode, crc, sizeof(NFAPI_CRC_INDICATION_PDU_T));

  // Add the node to the tail of the list
  if (tail == NULL) {
    head = newNode;
    tail = newNode;
  } else {
    tail->next = newNode;
    newNode->prev = tail;
    tail = newNode;
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&listLock);
}

void removeCRCIndication(NFAPI_CRC_INDICATION_PDU_T* crc) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&listLock);

  // Find the node with the matching RX UE information tag
  NFAPI_CRC_INDICATION_PDU_T* currentNode = head;
  while (currentNode != NULL) {
    if (currentNode->validRXUEInformationTag == crc->validRXUEInformationTag) {
      break;
    }
    currentNode = currentNode->next;
  }

  // Remove the node from the list
  if (currentNode != NULL) {
    if (currentNode == head) {
      head = head->next;
    }
    if (currentNode == tail) {
      tail = tail->prev;
    }
    free(currentNode);
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&listLock);
}

void updateCRCIndication(NFAPI_CRC_INDICATION_PDU_T* crc) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&listLock);

  // Find the node with the matching RX UE information tag
  NFAPI_CRC_INDICATION_PDU_T* currentNode = head;
  while (currentNode != NULL) {
    if (currentNode->validRXUEInformationTag == crc->validRXUEInformationTag) {
      break;
    }
    currentNode = currentNode->next;
  }

  // Update the node with the new CRC indication data
  if (currentNode != NULL) {
    memcpy(currentNode, crc, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&listLock);
}

void clearCRCIndications() {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&listLock);

  // Free all nodes in the list
  NFAPI_CRC_INDICATION_PDU_T* currentNode = head;
  while (currentNode != NULL) {
    NFAPI_CRC_INDICATION_PDU_T* nextNode = currentNode->next;
    free(currentNode);
    currentNode = nextNode;
  }

  // Reset the list to an empty state
  head = NULL;
  tail = NULL;

  // Unlock the mutex and return
  pthread_mutex_unlock(&listLock);
}
```
This implementation uses a doubly-linked list to store the CRC indications, with each node representing an RF frame's CRC indication. The `addCRCIndication`, `removeCRCIndication`, and `updateCRCIndication` functions provide thread-safe access to the list, while the `clearCRCIndications` function clears the entire list at once.

The implementation also uses a `pthread_mutex_t` mutex to prevent concurrent access to the list during updates and deletions. This ensures that only one thread can modify the list at a time, even if multiple threads are accessing it simultaneously.

Finally, this implementation uses memory allocation and deallocation functions from the C standard library (`malloc`, `free`) to manage the nodes in the list. These functions ensure that the memory used by the list is properly allocated and released when it is no longer needed.']

