    playerStates.reserve(MAX_PLAYERS); // Reserve space for player states
    skills.reserve(6); // Reserve space for 6 skills
    equipment.reserve(3); // Reserve space for 3 pieces of equipment
    historicalMatchOutcomes.resize(100); // Initialize cache with 100 slots for historical match outcomes

