struct FileWatcher {
    file: File,
    buffer: Vec<u8>,
}

impl FileWatcher {
    fn new(file: File) -> Self {
        Self {
            file,
            buffer: vec![],
        }
    }

    fn read(&mut self) -> Result<(), Box<dyn Error>> {
        let mut reader = BufReader::new(self.file);
        let mut line = String::new();

        while let Some(bytes) = reader.read_line(&mut line)? {
            if bytes > 0 {
                self.buffer.push(line.clone());
            } else {
                break;
            }

            line.clear();
        }

        Ok(())
    }
}
```
