['```
use actix_web::{App, HttpServer};
use std::sync::Mutex;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize)]
struct IoTData {
    device_id: String,
    sensor_data: Vec<f64>,
}

#[derive(Serialize, Deserialize)]
struct EquipmentFailurePrediction {
    equipment_id: String,
    predicted_failure_date: String,
    maintenance_schedule: String,
}

fn main() -> std::io::Result<()> {
    let mut system = IoTSystem::new();
    HttpServer::new(move || App::new().service(web::resource("/api/v1/data").route(web::post().to_async(system.process_data))))
        .bind("0.0.0.0:8080")?
        .run()
}

struct IoTSystem {
    pub cache: Mutex<HashMap<String, IoTData>>,
    pub prediction_model: Box<dyn PredictionModel>,
    pub maintenance_scheduler: Box<dyn MaintenanceScheduler>,
}

impl IoTSystem {
    fn new() -> Self {
        let cache = Mutex::new(HashMap::new());
        let prediction_model = Box::new(LinearRegressionPredictionModel::new());
        let maintenance_scheduler = Box::new(RandomMaintenanceScheduler::new());
        Self { cache, prediction_model, maintenance_scheduler }
    }

    async fn process_data(&self, data: IoTData) -> Result<EquipmentFailurePrediction> {
        let mut cache = self.cache.lock().unwrap();
        cache.insert(data.device_id.clone(), data);
        let prediction = self.prediction_model.predict(&cache);
        let maintenance_schedule = self.maintenance_scheduler.schedule(&cache);
        Ok(EquipmentFailurePrediction {
            equipment_id: data.device_id,
            predicted_failure_date: prediction.to_string(),
            maintenance_schedule: maintenance_schedule.to_string()
        })
    }
}

trait PredictionModel {
    fn predict(&self, cache: &HashMap<String, IoTData>) -> f64;
}

struct LinearRegressionPredictionModel {
    pub coefficients: Vec<f64>,
}

impl LinearRegressionPredictionModel {
    fn new() -> Self {
        Self {
            coefficients: vec![0.1, 0.2, 0.3],
        }
    }

    fn predict(&self, cache: &HashMap<String, IoTData>) -> f64 {
        let mut sum = 0f64;
        for (device_id, data) in cache {
            sum += self.coefficients[0] * data.sensor_data[0];
            sum += self.coefficients[1] * data.sensor_data[1];
            sum += self.coefficients[2] * data.sensor_data[2];
        }
        sum / cache.len() as f64
    }
}

trait MaintenanceScheduler {
    fn schedule(&self, cache: &HashMap<String, IoTData>) -> String;
}

struct RandomMaintenanceScheduler {}

impl RandomMaintenanceScheduler {
    fn new() -> Self {
        Self {}
    }

    fn schedule(&self, cache: &HashMap<String, IoTData>) -> String {
        let random_index = rand::random::<usize>() % cache.len();
        let (_, data) = cache[&data.device_id];
        data.sensor_data[0].to_string()
    }
}
```
