        cout << "Usage:" << endl;
        cout << "json-filter [options] [input files]" << endl;
        cout << "Options:" << endl;
        cout << "-h --help         show this help message" << endl;
        cout << "-v --version      show version information" << endl;
        cout << "-m --manpage      show manual page for the tool" << endl;
        cout << "-o --output <f>  output file (default: stdout)" << endl;
        cout << "-d --dry-run      preview filtering results without generating output files" << endl;
        return 0;
    } else if (argc == 1) {
        // no input files specified, print help message and exit
        cout << "Usage: json-filter [options] [input files]" << endl;
        cout << "Options:" << endl;
        cout << "-h --help         show this help message" << endl;
        cout << "-v --version      show version information" << endl;
        cout << "-m --manpage      show manual page for the tool" << endl;
        cout << "-o --output <f>  output file (default: stdout)" << endl;
        cout << "-d --dry-run      preview filtering results without generating output files" << endl;
        return 0;
    }

    // set up logging facility
    logging::logger_t logger;
    if (!cfg.dry_run) {
        logger = make_shared<logging::file_logger_t>(cfg.output);
    } else {
        logger = make_shared<logging::console_logger_t>();
    }

