    // set up thread pool for JSON parsing
    const size_t NUM_THREADS = 8;
    vector<thread> threads;
    mutex mtx;
    condition_variable cv;
    size_t num_inputs = 0;
    size_t num_processed = 0;
    bool all_inputs_processed = false;

    // set up function for parsing input files
    auto parse_file = [&](const string& filename) {
        ifstream file(filename);
        if (!file.is_open()) {
            throw runtime_error("failed to open input file " + filename);
        }
        string line;
        while (getline(file, line)) {
            if (line == "") continue;
            json j = parser.parse(line);
            // process JSON object here, for example:
            // ...
            num_processed++;
            cv.notify_one();
        }
    };

    // set up function for monitoring memory usage
    auto monitor_memory = [&]() {
        // check for memory consumption and trigger garbage collection if necessary
        const size_t MAX_MEMORY = 1024 * 1024 * 500; // 500 MB
        if (get_process_memory() > MAX_MEMORY) {
            logger->info("triggering garbage collection...");
            gc();
        }
    };

    // start monitoring memory usage
    thread monitor(monitor_memory);

    // loop over input files
    for (int i = 1; i < argc; i++) {
        string filename = argv[i];
        threads.push_back(thread(parse_file, filename));
    }

    // wait for all input files to be processed
    while (!all_inputs_processed) {
        unique_lock<mutex> lck(mtx);
        cv.wait(lck, [&]() { return num_processed == num_inputs; });
        all_inputs_processed = true;
    }

    // stop monitoring memory usage
    monitor.join();

    // print summary of processing time and number of input files processed
    logger->info("finished processing {} input files", argc - 1);
    return 0;
}
