// Define the structure for an item in the list
typedef struct {
  char* name;
  float value;
  struct item* next;
} item_t;

// Define the global list of items
item_t* items = NULL;

// Mutex to protect access to the list
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the list with data from an array
void init_list(const item_data_t* items) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&list_mutex);

  // Iterate over the input array and create a new item for each element
  for (int i = 0; i < items.length; i++) {
    const item_data_t* current = &items[i];

    // Allocate memory for the name field of the new item
    char* name = malloc(strlen(current->name) + 1);
    strcpy(name, current->name);

    // Create a new item with the allocated name and value fields
    item_t* new_item = malloc(sizeof(item_t));
    new_item->name = name;
    new_item->value = current->value;

    // Add the new item to the end of the list
    if (items == NULL) {
      items = new_item;
    } else {
      struct item* temp = items;
      while (temp->next != NULL) {
        temp = temp->next;
      }
      temp->next = new_item;
    }
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&list_mutex);
}

// Function to add a new item to the list
void add_item(const char* name, float value) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&list_mutex);

  // Allocate memory for the name field of the new item
