  strcpy(name, name);

  // Create a new item with the allocated name and value fields
  item_t* new_item = malloc(sizeof(item_t));
  new_item->name = name;
  new_item->value = value;

  // Add the new item to the end of the list
  if (items == NULL) {
    items = new_item;
  } else {
    struct item* temp = items;
    while (temp->next != NULL) {
      temp = temp->next;
    }
    temp->next = new_item;
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&list_mutex);
}

// Function to remove an item from the list by its name
void remove_item(const char* name) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&list_mutex);

  // Iterate over the list and find the item with the matching name
  struct item* temp = items;
  while (temp != NULL) {
    if (strcmp(temp->name, name) == 0) {
      // Found the item, remove it from the list
      if (temp == items) {
        items = temp->next;
      } else {
        struct item* previous = temp;
        while (previous->next != temp) {
          previous = previous->next;
        }
        previous->next = temp->next;
      }

      // Free the memory for the name and value fields of the removed item
      free(temp->name);
      free(temp->value);

      // Free the memory for the item structure itself
      free(temp);

      break;
    }
    temp = temp->next;
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&list_mutex);
}
```
This implementation uses a mutex to protect access to the list, which ensures thread safety and prevents concurrent modifications. The `init_list` function initializes the list with data from an array of `item_data_t` structures, while the `add_item` function adds a new item to the end of the list. The `remove_item` function removes an item from the list by its name.

