// Define a struct to represent a session
struct Session {
    std::string id;
    std::set<std::string> roles;
    bool is_active = true;
};

// Define a map to store all active sessions
std::unordered_map<std::string, Session> sessions;

// Mutex for synchronizing access to the session map
std::mutex session_map_mtx;

// Condition variable for signaling new sessions
std::condition_variable new_session_cv;

// Condition variable for signaling session invalidation
std::condition_variable invalidate_session_cv;

// Function to create a new session
void createSession(const std::string& id, const std::set<std::string>& roles) {
    // Acquire the lock on the session map
    std::unique_lock<std::mutex> lock(session_map_mtx);

    // Check if a session with the given ID already exists
    if (sessions.find(id) != sessions.end()) {
        // If it does, invalidate the existing session and wait for it to be invalidated
        Session& session = sessions[id];
        session.is_active = false;
        invalidate_session_cv.wait(lock);
    }

    // Add a new session with the given ID and roles
    Session new_session{ id, roles };
    sessions[id] = std::move(new_session);

    // Signal that a new session has been created
    new_session_cv.notify_all();
}

// Function to get the roles of a session
std::set<std::string> getRoles(const std::string& id) {
    // Acquire the lock on the session map
    std::unique_lock<std::mutex> lock(session_map_mtx);

    // Check if a session with the given ID exists
    auto it = sessions.find(id);
    if (it == sessions.end()) {
        return {};
    }

    // Return the roles of the session
    return it->second.roles;
}

// Function to invalidate a session
void invalidateSession(const std::string& id) {
    // Acquire the lock on the session map
    std::unique_lock<std::mutex> lock(session_map_mtx);

    // Check if a session with the given ID exists
    auto it = sessions.find(id);
    if (it == sessions.end()) {
        return;
    }

    // Set the is_active flag of the session to false
    Session& session = it->second;
    session.is_active = false;

    // Signal that the session has been invalidated
    invalidate_session_cv.notify_all();
}

// Main function to demonstrate how to handle challenges in a realistic engineering scenario
int main() {
    std::vector<std::thread> threads;

    // Create multiple threads to simulate concurrent access to the session management service
    for (int i = 0; i < 10; ++i) {
