    public class DynamicDataSourceAndQueryOrchestrator
    {
        private readonly List<string> _connectionStrings;
        private readonly Dictionary<string, object> _queryParameters;
        private readonly string _sqlCommandString;
        private readonly bool _atomicTransactionsEnabled;

        public DynamicDataSourceAndQueryOrchestrator(List<string> connectionStrings, Dictionary<string, object> queryParameters, string sqlCommandString, bool atomicTransactionsEnabled)
        {
            _connectionStrings = connectionStrings;
            _queryParameters = queryParameters;
            _sqlCommandString = sqlCommandString;
            _atomicTransactionsEnabled = atomicTransactionsEnabled;
        }

        public async Task<IEnumerable<dynamic>> HandleDynamicDataSourcesAndQueries(CancellationToken cancellationToken)
        {
            var results = new List<dynamic>();

            // Validate connection strings and SQL command string for correctness and compatibility
            foreach (var connectionString in _connectionStrings)
            {
                using var conn = new SqlConnection(connectionString);
                await conn.OpenAsync();

                if (_atomicTransactionsEnabled)
                {
                    // Implement atomic transactions to handle potential race conditions
                    using var transaction = conn.BeginTransaction();
                    try
                    {
                        var command = new SqlCommand(_sqlCommandString, conn);
                        foreach (var parameter in _queryParameters)
                        {
                            command.Parameters.Add(parameter.Key, parameter.Value);
                        }

                        var reader = await command.ExecuteReaderAsync();
                        results.AddRange(reader.Select(r => r.ToExpando()));

                        transaction.Commit();
                    }
                    catch (Exception)
                    {
                        transaction.Rollback();
                        throw;
                    }
                }
                else
                {
                    var command = new SqlCommand(_sqlCommandString, conn);
                    foreach (var parameter in _queryParameters)
                    {
                        command.Parameters.Add(parameter.Key, parameter.Value);
                    }

                    var reader = await command.ExecuteReaderAsync();
                    results.AddRange(reader.Select(r => r.ToExpando()));
                }
            }

            return results;
        }

        private static IEnumerable<dynamic> ToExpando(this IDataRecord record)
        {
            var dict = new ExpandoObject() as IDictionary<string, object>;

            for (var i = 0; i < record.FieldCount; i++)
            {
                dict[record.GetName(i)] = record[i];
            }

            return new[] { dict };
        }
    }
}
