    void update_interface(const std::string& old_ip_address, const std::string& new_ip_address, const std::string& new_subnet_mask, const std::string& new_default_gateway);

    // Removes a network interface with the given IP address
    void remove_interface(const std::string& ip_address);

    // Gets all network interfaces currently configured on the system
    std::vector<NetworkInterface> get_interfaces();

private:
    // Mutex to protect access to the network interface map
    std::mutex mtx_;

    // Condition variable to signal changes in the network interface map
    std::condition_variable cv_;

    // Map of IP address to NetworkInterface objects
    std::map<std::string, NetworkInterface> interfaces_;

    // Pointer to an instance of the external configuration service
    std::shared_ptr<ConfigurationService> config_service_;

    // Retry logic for fetching network interface configurations from the external service
    void retry_fetch();

    // Thread-safe method to update the local cache with the latest network interface configurations from the external service
    void update_cache(const std::vector<NetworkInterface>& interfaces);
};

class NetworkInterface {
public:
    // Constructor
    NetworkInterface(const std::string& ip_address, const std::string& subnet_mask, const std::string& default_gateway);

    // Getters for IP address, subnet mask, and default gateway
    std::string get_ip_address();
    std::string get_subnet_mask();
    std::string get_default_gateway();

private:
    // IP address of the network interface
    std::string ip_address_;

    // Subnet mask of the network interface
    std::string subnet_mask_;

    // Default gateway of the network interface
    std::string default_gateway_;
};

// Implementation of the external configuration service interface
class ConfigurationService {
public:
    // Constructor
    ConfigurationService();

    // Gets all network interfaces currently configured on the system
    virtual std::vector<NetworkInterface> get_interfaces() = 0;

    // Adds a new network interface with the given IP address, subnet mask, and default gateway
    virtual void add_interface(const std::string& ip_address, const std::string& subnet_mask, const std::string& default_gateway) = 0;

