#include <chrono>
#include <stdexcept>

class DynamicNetworkConfigManager {
public:
    DynamicNetworkConfigManager(const std::vector<std::string>& configs) :
        configs_(configs), next_index_(0), local_cache_(configs.size()) {}

    // Add a new configuration to the manager
    void addConfiguration(const std::string& config) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (next_index_ >= configs_.size()) {
            throw std::runtime_error("Maximum number of configurations reached");
        }
        configs_.push_back(config);
    }

    // Update a configuration in the manager
    void updateConfiguration(const std::string& config) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (next_index_ >= configs_.size()) {
            throw std::runtime_error("No such configuration exists");
        }
        configs_[next_index_] = config;
    }

    // Remove a configuration from the manager
    void removeConfiguration(const std::string& config) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (next_index_ >= configs_.size()) {
            throw std::runtime_error("No such configuration exists");
        }
        configs_.erase(configs_.begin() + next_index_);
    }

    // Get the current active configuration
    const std::string& getActiveConfiguration() {
        return configs_[next_index_];
    }

    // Switch to the next available configuration
    void switchToNextConfiguration() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (next_index_ >= configs_.size()) {
            throw std::runtime_error("No more configurations");
        }
        const std::string& config = configs_[next_index_];
        local_cache_[config]++;
        next_index_++;
    }

private:
    // Vector of all available configurations
    std::vector<std::string> configs_;

    // Index of the currently active configuration
    size_t next_index_;

    // Local cache of valid configurations and their usage counts
    std::map<std::string, int> local_cache_;

    // Mutex to protect concurrent access to the configuration vector and local cache
    std::mutex mutex_;
};
