// Mutex for protecting against race conditions during modification
pthread_mutex_t mutex;

// Flag to indicate if the function is currently writing to the database
int isWriting = 0;

// Function to create a new node in the linked list
void addNode(NFAPI_CRC_INDICATION_PDU_T data) {
    // Create a new node with the given data
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;

    // Lock the mutex to protect against race conditions during modification
    pthread_mutex_lock(&mutex);

    // If the head pointer is null, set it to the new node
    if (head == NULL) {
        head = newNode;
    } else {
        // Find the last node in the list and insert the new node after it
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

