    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != data.RX_UE_INFORMATION_TAG) {
        current = current->next;
    }
    if (current == NULL) {
        // The node is not found, do nothing
        pthread_mutex_unlock(&mutex);
        return;
    }
    if (current == head) {
        head = current->next;
    } else {
        Node* previous = head;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }

    // Unlock the mutex and free the memory of the removed node
    pthread_mutex_unlock(&mutex);
    free(current);
}

// Function to check if a node with the given data exists in the linked list
int containsNode(NFAPI_CRC_INDICATION_PDU_T data) {
    // Lock the mutex to protect against race conditions during modification
    pthread_mutex_lock(&mutex);

    // Iterate over the nodes in the list and check if one of them has the given data
    Node* current = head;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != data.RX_UE_INFORMATION_TAG) {
        current = current->next;
    }

    // Unlock the mutex and return true if a node with the given data is found, false otherwise
    pthread_mutex_unlock(&mutex);
    return (current != NULL);
}

// Function to retrieve the head pointer of the linked list
Node* getHead() {
    // Lock the mutex to protect against race conditions during modification
    pthread_mutex_lock(&mutex);

    // Return a copy of the head pointer, which can be modified without affecting the original list
    Node* headCopy = malloc(sizeof(Node));
    headCopy->data = head->data;
    headCopy->next = head->next;

    // Unlock the mutex and return the copy of the head pointer
    pthread_mutex_unlock(&mutex);
    return headCopy;
}

// Function to set a new value for the head pointer of the linked list
void setHead(Node* newHead) {
    // Lock the mutex to protect against race conditions during modification
    pthread_mutex_lock(&mutex);

    // Set the new head pointer and free the memory of the old head pointer
    head = newHead;
    free(newHead->next);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to persist the linked list to an external database every 10 minutes
void persistList() {
    // Lock the semaphore to synchronize access to the linked list during write operations
    sem_wait(&sem);

    // If another thread is already writing to the database, wait for it to finish and return
    if (isWriting) {
        sem_post(&sem);
        return;
    }

    // Set a flag indicating that another thread is currently writing to the database
    isWriting = 1;

    // Iterate over the nodes in the linked list and persist each node separately
    Node* current = head;
    while (current != NULL) {
        // Persist the current node to the external database
        persistNode(current->data);

        // Move on to the next node
        current = current->next;
    }

    // Reset the flag indicating that another thread is currently writing to the database
    isWriting = 0;

    // Unlock the semaphore and return
    sem_post(&sem);
}

