import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;

public class UserSessionService {
    // Map to store user session state entities
    private Map<Long, SessionState> sessions;

    // Atomic reference to track the next available session ID
    private AtomicReference<Long> nextId = new AtomicReference<>();

    public UserSessionService() {
        this.sessions = new ConcurrentHashMap<>();
        this.nextId.set(1L);
    }

    // Add a new user session to the service
    public void addUserSession(String userId, long sessionStartTimestamp) {
        SessionState state = new SessionState(userId, sessionStartTimestamp);
        sessions.put(state.getId(), state);
    }

    // Update the last active timestamp of a user session
    public void updateLastActiveTimestamp(Long sessionId, long lastActiveTimestamp) {
        SessionState state = sessions.get(sessionId);
        if (state != null) {
            state.setLastActiveTimestamp(lastActiveTimestamp);
        } else {
            throw new IllegalArgumentException("Session not found");
        }
    }

    // Update the last seen location of a user session
    public void updateLastSeenLocation(Long sessionId, String lastSeenLocation) {
        SessionState state = sessions.get(sessionId);
        if (state != null) {
            state.setLastSeenLocation(lastSeenLocation);
        } else {
            throw new IllegalArgumentException("Session not found");
        }
    }

    // Query for user sessions active within the last hour
    public List<SessionState> queryActiveSessions(long currentTimestamp) {
        long startTime = currentTimestamp - 3600 * 1000;
        return sessions.values().stream()
                .filter(state -> state.getLastActiveTimestamp() >= startTime)
                .collect(Collectors.toList());
    }
}

class SessionState {
    private final Long id;
    private final String userId;
    private long sessionStartTimestamp;
    private long lastActiveTimestamp;
    private String lastSeenLocation;

    public SessionState(String userId, long sessionStartTimestamp) {
        this.id = nextId.getAndIncrement();
        this.userId = userId;
        this.sessionStartTimestamp = sessionStartTimestamp;
        this.lastActiveTimestamp = sessionStartTimestamp;
        this.lastSeenLocation = "";
    }

    public Long getId() {
        return id;
    }

    public String getUserId() {
        return userId;
    }

    public long getSessionStartTimestamp() {
        return sessionStartTimestamp;
    }

    public void setLastActiveTimestamp(long lastActiveTimestamp) {
        this.lastActiveTimestamp = lastActiveTimestamp;
    }

    public long getLastActiveTimestamp() {
        return lastActiveTimestamp;
    }

    public void setLastSeenLocation(String lastSeenLocation) {
        this.lastSeenLocation = lastSeenLocation;
    }

    public String getLastSeenLocation() {
        return lastSeenLocation;
    }
}
