    for (size_t i = 0; i < gs->num_geoips; i++) {
        if (strcmp(gs->geoips[i]->ip, session->ip) == 0) {
            memcpy(&session->lat, &gs->geoips[i]->lat, sizeof(double));
            memcpy(&session->lon, &gs->geoips[i]->lon, sizeof(double));
        }
