}

void geolocation_update(struct geolocation_service *gs, struct session *session) {
    for (size_t i = 0; i < gs->num_geoips; i++) {
        if (strcmp(gs->geoips[i]->ip, session->ip) == 0) {
            memcpy(&gs->geoips[i], session, sizeof(struct geo));
        }
    }
}

void geolocation_remove(struct geolocation_service *gs, struct session *session) {
    for (size_t i = 0; i < gs->num_geoips; i++) {
        if (strcmp(gs->geoips[i]->ip, session->ip) == 0) {
            memcpy(&gs->geoips[i], session, sizeof(struct geo));
