  std::vector<Algorithm> algorithms;   // The encryption and decryption algorithms supported by the service
  std::vector<ImageFormat> formats;   // The image formats supported by the service
  std::unordered_map<std::string, std::string> metadata; // The metadata to extract from the images
  bool useHsm;                        // Whether to use HSMs for key management
  KeyManagementMode hsmMode;          // The mode of operation for the HSMs
  EncryptionMode encryptionMode;      // The mode of operation for the encryption
  LoggingLevel loggingLevel;          // The level of logging to use for the service
