package com.image.to.pdf;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.commons.cli.*;
import com.image.to.pdf.config.ConfigReader;
import com.image.to.pdf.converter.ImageToPdfConverter;
import com.image.to.pdf.util.FileUtil;
import com.image.to.pdf.util.LogUtil;

public class ImageToPdfService {
    private static final String CONFIG_FILE_NAME = "config.properties";
    private static final String OUTPUT_DIRECTORY = "outputDirectory";
    private static final String INPUT_DIRECTORY = "inputDirectory";
    private static final String METADATA_PARAMETERS = "metadataParameters";
    private static final String THIRD_PARTY_TOOLS = "thirdPartyTools";
    private static final String WATERMARK_SETTINGS = "watermarkSettings";
    private static final String CUSTOM_METADATA = "customMetadata";
    private static final String CONCURRENT_CONVERSIONS = "concurrentConversions";

    public static void main(String[] args) {
        Options options = createOptions();
        CommandLineParser parser = new DefaultParser();
        try {
            CommandLine cmd = parser.parse(options, args);
            ConfigReader configReader = new ConfigReader(cmd.getOptionValue(CONFIG_FILE_NAME));
            Map<String, Object> configMap = configReader.readConfig();
            String outputDirectory = (String)configMap.get(OUTPUT_DIRECTORY);
            String inputDirectory = (String)configMap.get(INPUT_DIRECTORY);
            Map<String, String> metadataParameters = (Map<String, String>)configMap.get(METADATA_PARAMETERS);
            Map<String, String> thirdPartyTools = (Map<String, String>)configMap.get(THIRD_PARTY_TOOLS);
            Map<String, String> watermarkSettings = (Map<String, String>)configMap.get(WATERMARK_SETTINGS);
            Map<String, String> customMetadata = (Map<String, String>)configMap.get(CUSTOM_METADATA);
            int concurrentConversions = Integer.parseInt((String)configMap.get(CONCURRENT_CONVERSIONS));
            ImageToPdfConverter converter = new ImageToPdfConverter(outputDirectory, inputDirectory, metadataParameters, thirdPartyTools, watermarkSettings, customMetadata, concurrentConversions);
            ExecutorService executor = Executors.newFixedThreadPool(concurrentConversions);
            File[] imageFiles = FileUtil.listFiles(inputDirectory, new String[] { "jpg", "png", "gif" }, false);
            for (File file : imageFiles) {
                executor.submit(() -> converter.convertImageToPdf(file));
            }
        } catch (ParseException | IOException e) {
            LogUtil.error("Error while parsing command line arguments: " + e.getMessage());
        }
    }

    private static Options createOptions() {
        Options options = new Options();
        Option configFileOption = Option.builder("c").longOpt("config-file").hasArg().argName("FILE").required(true).build();
        Option outputDirectoryOption = Option.builder("o").longOpt("output-directory").hasArg().argName("DIRECTORY").required(true).build();
        Option inputDirectoryOption = Option.builder("i").longOpt("input-directory").hasArg().argName("DIRECTORY").required(true).build();
        Option metadataParametersOption = Option.builder("m").longOpt("metadata-parameters").hasArgs().argName("KEY=VALUE").valueSeparator('=').build();
        Option thirdPartyToolsOption = Option.builder("t").longOpt("third-party-tools").hasArgs().argName("TOOLS").build();
        Option watermarkSettingsOption = Option.builder("w").longOpt("watermark-settings").hasArg().argName("SETTINGS").build();
        Option customMetadataOption = Option.builder("u").longOpt("custom-metadata").hasArgs().argName("KEY=VALUE").valueSeparator('=').build();
        Option concurrentConversionsOption = Option.builder("n").longOpt("concurrent-conversions").hasArg().argName("NUM").type(Number.class).build();
        options.addOption(configFileOption);
        options.addOption(outputDirectoryOption);
        options.addOption(inputDirectoryOption);
        options.addOption(metadataParametersOption);
        options.addOption(thirdPartyToolsOption);
        options.addOption(watermarkSettingsOption);
        options.addOption(customMetadataOption);
        options.addOption(concurrentConversionsOption);
        return options;
    }
}']

