// Function to process a vector of transactions
pair<double, int> processTransactions(vector<Transaction>& transactions) {
    // Create an instance of the ExternalAPI class
    ExternalAPI api("https://api.example.com");

    // Initialize the maximum weighted sum and number of retries
    double max_weighted_sum = 0;
    int num_retries = 0;

    // Iterate over each transaction
    for (const Transaction& t : transactions) {
        // Check if the transaction is from a verified user
        if (!isVerifiedUser(t.id)) {
            continue;
        }

        // Get the weighted sum of the transaction
        double weighted_sum = getWeightedSum(t);

        // Check if the transaction is within the age limit
        if (getTimeSinceLastTransaction(t) > 3000) {
            continue;
        }

        // Get the number of transactions in the past 3 seconds
        int num_transactions = getNumTransactionsInPast3s(t.id);

        // Check if the transaction is within the recent frequency limit
        if (num_transactions > 10) {
            continue;
        }

        // Make a GET request to the API for authentication
        tuple<int, int, double> response = api.get_request("/auth/" + t.id);

        // Check if the response is valid
        if (get<0>(response) != 200 || get<1>(response) != 200) {
            continue;
        }

        // Make a GET request to the API for transaction validation
        response = api.get_request("/validate/" + t.id);

        // Check if the response is valid
        if (get<0>(response) != 200 || get<1>(response) != 200) {
            continue;
        }

        // Make a GET request to the API for historical data
        response = api.get_request("/historical/" + t.id);

        // Check if the response is valid
        if (get<0>(response) != 200 || get<1>(response) != 200) {
            continue;
        }

        // Update the maximum weighted sum and number of retries
        max_weighted_sum = max(max_weighted_sum, weighted_sum);
        num_retries++;
    }

    // Return the maximum weighted sum and number of retries
    return make_pair(max_weighted_sum, num_retries);
}

