    struct nfa_crc_indication_list *next;
} NFA_CRC_INDICATION_LIST_T;

// Define the function to dynamically construct and populate the linked list
int processAndPersistCrcIndications(NFA_CRC_INDICATION_LIST_T **list, uint32_t N) {
    // Validate the input parameter N
    if (N < 1 || N > 1000000) {
        return -EINVAL;
    }

    // Initialize the linked list
    *list = NULL;

    // Iterate over the given range of N and construct a new element for each iteration
    for (uint32_t i = 1; i <= N; i++) {
        // Allocate memory for the new element
        NFA_CRC_INDICATION_LIST_T *new_element = malloc(sizeof(NFA_CRC_INDICATION_LIST_T));
        if (!new_element) {
            return -ENOMEM;
        }

        // Set the new element's data fields
        new_element->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_element->data) {
            free(new_element);
            return -ENOMEM;
        }
        new_element->data->RX_UE_INFORMATION_TAG = i;
        new_element->data->RNTI = i + 10000;
        new_element->data->CRC_INDICATION_REL8_TAG = i % 2;
        new_element->data->CRCFLAG = (i % 3) == 0;

        // Insert the new element into the linked list
        if (*list) {
            new_element->next = *list;
        } else {
            new_element->next = NULL;
        }
        *list = new_element;
    }

    return 0;
}
