    client: String,
}

impl Service for CompilerService {
    fn call(&self, request: &Request) -> Result<Response, Error> {
        // Call the LLVM compiler API with the provided request
        let response = self.client.post(request).await?;

        // Return the response or an error if one occurred
        Ok(response)
    }
}

