using namespace std;

const int PBKDF_ITERATIONS = 10000; // adjustable iteration count for PBKDF

// Struct to store user account information
struct User {
    string username;
    string password;
};

// Struct to store encrypted data
struct EncryptedData {
    vector<unsigned char> ciphertext;
    vector<unsigned char> iv;
};

// Function to derive encryption keys and initialization vectors from user passwords using PBKDF
void pbkdf(const string& password, int iterations, vector<unsigned char>& key, vector<unsigned char>& iv) {
    // Initialize HMAC-SHA256 context
    HMAC_CTX ctx;
    HMAC_Init_ex(&ctx, (void*)password.c_str(), password.size(), EVP_sha256(), NULL);

    // Derive encryption key and initialization vector using PBKDF
    for (int i = 0; i < iterations; i++) {
        HMAC_Update(&ctx, (void*)password.c_str(), password.size());
        HMAC_Final(&ctx, key.data(), iv.data());
    }

    // Clean up
    HMAC_CTX_cleanup(&ctx);
}

// Function to encrypt data using AES-256-GCM
void encrypt(const vector<unsigned char>& plaintext, const vector<unsigned char>& key, const vector<unsigned char>& iv, vector<unsigned char>& ciphertext) {
    // Initialize AES-256-GCM context
    EVP_CIPHER_CTX ctx;
    EVP_EncryptInit_ex(&ctx, EVP_aes_256_gcm(), NULL, key.data(), iv.data());

    // Set encryption mode and padding
    EVP_CIPHER_CTX_set_padding(&ctx, 0);
    EVP_EncryptInit_ex(&ctx, NULL, NULL, NULL, NULL);

    // Encrypt data using AES-256-GCM
    int len = plaintext.size();
    unsigned char* inp = (unsigned char*)plaintext.data();
    unsigned char* out = (unsigned char*)ciphertext.data();
    EVP_EncryptUpdate(&ctx, out, &len, inp, len);

    // Finalize encryption and get ciphertext length
    int fin_len = 0;
    EVP_EncryptFinal_ex(&ctx, NULL, &fin_len);

    // Clean up
    EVP_CIPHER_CTX_cleanup(&ctx);
}

// Function to decrypt data using AES-256-GCM
void decrypt(const vector<unsigned char>& ciphertext, const vector<unsigned char>& key, const vector<unsigned char>& iv, vector<unsigned char>& plaintext) {
    // Initialize AES-256-GCM context
    EVP_CIPHER_CTX ctx;
    EVP_DecryptInit_ex(&ctx, EVP_aes_256_gcm(), NULL, key.data(), iv.data());

    // Set encryption mode and padding
    EVP_CIPHER_CTX_set_padding(&ctx, 0);
    EVP_DecryptInit_ex(&ctx, NULL, NULL, NULL, NULL);

    // Decrypt data using AES-256-GCM
    int len = ciphertext.size();
    unsigned char* inp = (unsigned char*)ciphertext.data();
    unsigned char* out = (unsigned char*)plaintext.data();
    EVP_DecryptUpdate(&ctx, out, &len, inp, len);

    // Finalize decryption and get plaintext length
    int fin_len = 0;
    EVP_DecryptFinal_ex(&ctx, NULL, &fin_len);

    // Clean up
    EVP_CIPHER_CTX_cleanup(&ctx);
}

// Function to store encrypted data for a user account
void storeEncryptedData(const User& user, const EncryptedData& data) {
    // Create directory for user if it doesn't exist
    string dir = "data/" + user.username;
    mkdir(dir.c_str(), 0755);

    // Write encrypted data to file
    ofstream file(dir + "/encryptedData", ios::out | ios::binary);
    file.write((char*)&data, sizeof(EncryptedData));
    file.close();
}

// Function to retrieve encrypted data for a user account
void retrieveEncryptedData(const User& user, EncryptedData& data) {
    // Read encrypted data from file
    string dir = "data/" + user.username;
    ifstream file(dir + "/encryptedData", ios::in | ios::binary);
    file.read((char*)&data, sizeof(EncryptedData));
    file.close();
}

// Function to update encrypted data for a user account
void updateEncryptedData(const User& user, const EncryptedData& new_data) {
    // Read current encrypted data from file
    string dir = "data/" + user.username;
    ifstream file(dir + "/encryptedData", ios::in | ios::binary);
    EncryptedData curr_data;
    file.read((char*)&curr_data, sizeof(EncryptedData));
    file.close();

    // Decrypt current data using user's password
    vector<unsigned char> key, iv;
    pbkdf(user.password, PBKDF_ITERATIONS, key, iv);
    vector<unsigned char> plaintext = curr_data.ciphertext;
    decrypt(plaintext, key, iv, plaintext);

    // Encrypt new data using user's password
    plaintext = new_data.ciphertext;
    encrypt(plaintext, key, iv, plaintext);

    // Update encrypted data in file
    ofstream file(dir + "/encryptedData", ios::out | ios::binary);
    file.write((char*)&new_data, sizeof(EncryptedData));
    file.close();
}

// Function to handle user input and perform actions based on user's request
void handleUserInput() {
    // Get user input
    string command;
    cout << "Enter a command (add/update/retrieve): ";
    cin >> command;

    // Parse user input and perform action
