from PIL import Image
from io import BytesIO
from concurrent.futures import ThreadPoolExecutor

class ImageProcessingMicroservice:
    def __init__(self):
        self.log = logging.getLogger(__name__)
        self.storage_url = "https://example.com/api/v1/images"
        self.cdn_url = "https://example-cdn.com/images/"
        self.thumbnail_size = (200, 200)
        self.image_formats = ["jpeg", "png", "gif"]
        self.quality_levels = [50, 75, 90]
        self.compression_ratios = [10, 50, 80]

    def process_image(self, image):
        # Determine the optimal format and quality level based on the image size and aspect ratio
        format, quality = self.determine_format_and_quality(image)

        # Resize the image to the desired thumbnail size
        resized_image = Image.open(BytesIO(image))
        resized_image.thumbnail(self.thumbnail_size, Image.ANTIALIAS)

        # Convert the image to the optimal format and quality level
        converted_image = resized_image.convert("RGB")
        converted_image.save(BytesIO(), format=format, quality=quality)

        # Compress the image using the optimal compression ratio
        compressed_image = BytesIO()
        converted_image.save(compressed_image, format=format, quality=quality, optimize=True)

        return converted_image

    def determine_format_and_quality(self, image):
        # Determine the optimal format based on the file extension and aspect ratio
        if image.width / image.height >= 1:
            format = "landscape"
        else:
            format = "portrait"

        # Determine the optimal quality level based on the image size and aspect ratio
        width, height = image.size
        if width > height:
            quality = self.quality_levels[0]
        elif width < height:
            quality = self.quality_levels[2]
        else:
            quality = self.quality_levels[1]

        return format, quality

    def upload_image(self, image):
        # Upload the processed image to the cloud storage system
        response = requests.post(self.storage_url, files={"file": image})
        if not response.ok:
            self.log.error("Failed to upload image to cloud storage")
            return None

        return json.loads(response.text)["image"]

    def compress_image(self, image):
        # Compress the processed image using the optimal compression ratio
        compressed_image = BytesIO()
        image.save(compressed_image, format=image.format, quality=image.quality, optimize=True)

        return compressed_image

    def resize_image(self, image):
        # Resize the processed image to the desired thumbnail size
        resized_image = Image.open(BytesIO(image))
        resized_image.thumbnail(self.thumbnail_size, Image.ANTIALIAS)

        return resized_image

    def crop_image(self, image):
        # Crop the processed image to the desired thumbnail size
        width, height = self.thumbnail_size
        left = (image.width - width) / 2
        top = (image.height - height) / 2
        right = left + width
        bottom = top + height

        return image.crop((left, top, right, bottom))

    def rotate_image(self, image):
        # Rotate the processed image to match the aspect ratio of the thumbnail size
        if image.width / image.height >= 1:
            angle = 90
        else:
            angle = -90

        return image.rotate(angle)

    def optimize_image(self, image):
        # Optimize the processed image for web use
        optimized_image = Image.open(BytesIO(image))
        optimized_image.save(BytesIO(), format=optimized_image.format, quality=80, optimize=True)

        return optimized_image

    def handle_uploaded_file(self, file):
        # Process the uploaded image using multiple threads for performance and scalability
        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = [executor.submit(self.process_image, file.read())]
            responses = [future.result() for future in futures]

        return responses[0]

    def handle_upload_error(self, error):
        # Handle errors during image upload and processing gracefully
        self.log.exception("Failed to process uploaded image")
        return None

    def handle_response_error(self, response):
        # Handle errors during storage or CDN integration gracefully
        self.log.error("Error encountered while interacting with the storage system or CDN")
        return None

    def handle_file_upload(self, request):
        # Process uploaded images and return the processed image URL or None on error
        try:
            file = request.files["image"]
            response = self.handle_uploaded_file(file)
            if not response:
                raise ValueError("Failed to process uploaded image")

            return self.upload_image(response)
        except Exception as e:
            return self.handle_upload_error(e)

    def handle_file_download(self, request):
        # Handle file download requests and return the downloaded image or None on error
        try:
            response = request.args["image"]
            if not response:
                raise ValueError("Failed to process uploaded image")

            return self.crop_image(self.resize_image(self.rotate_image(self.optimize_image(self.download_image(response)))))
        except Exception as e:
            return self.handle_file_error(e)

    def handle_file_delete(self, request):
        # Handle file delete requests and return the deleted image or None on error
        try:
            response = request.args["image"]
            if not response:
                raise ValueError("Failed to process uploaded image")

            return self.delete_image(response)
        except Exception as e:
            return self.handle_file_error(e)
