    EVP_EncryptUpdate(ctx->ctx, output, strlen(input), (uint8_t*)input, strlen(input));
}

// Function to decrypt data using AES-256-CBC encryption with cipher context
void decrypt(const uint8_t* input, char* output, const CipherContext* ctx) {
