    EVP_DecryptUpdate(ctx->ctx, (uint8_t*)output, strlen(input), input, strlen(input));
}

// Function to generate a linked list of CRC indication PDUs from NFAPI_CRC_INDICATION_PDU_T structures
void process_crc_indications(const char* input, LinkedList** list) {
    // Initialize linked list of CRC indication PDUs
    *list = malloc(sizeof(LinkedList));
    (*list)->head = NULL;
    (*list)->tail = NULL;

    // Split input data into separate NFAPI_CRC_INDICATION_PDU_T structures
    char* token = strtok((char*)input, ",");
    while (token != NULL) {
        // Allocate memory for CRC indication PDU structure
        (*list)->head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Populate CRC indication PDU structure with token data
        (*list)->head->RX_UE_INFORMATION_TAG = atoi(token);
        token = strtok(NULL, ",");
        (*list)->head->RNTI = atoi(token);
        token = strtok(NULL, ",");
        (*list)->head->CRC_INDICATION_REL8_TAG = atoi(token);
        token = strtok(NULL, ",");
        (*list)->head->CRCFLAG = atoi(token);

        // Update linked list tail pointer
        if ((*list)->tail == NULL) {
            (*list)->tail = (*list)->head;
        } else {
            (*list)->tail = malloc(sizeof(LinkedList));
            (*list)->tail->head = NULL;
            (*list)->tail->tail = NULL;
        }
    }
}

// Function to handle memory allocation failures during processing
