```c
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

// Define the AES-256-GCM cipher structure
typedef struct {
  uint8_t key[32]; // Derived encryption key from PBKDF2
  uint8_t iv[16]; // Secure initialization vector (IV)
  EVP_CIPHER_CTX *ctx; // Context for encrypting/decrypting data
} aes_gcm_cipher_t;

// Define the authentication structure for storing user information
typedef struct {
  char username[32]; // Username of the authenticated user
  uint8_t password_hash[64]; // Hashed password of the user
} auth_info_t;

// Function to initialize and manage the AES-256-GCM cipher
bool init_aes_gcm(const char *password, const char *salt, uint8_t iteration_count, aes_gcm_cipher_t *cipher) {
  // Generate a secure initialization vector (IV) using OpenSSL's RAND_bytes() function
  if (!RAND_bytes(iv, 16)) {
    return false;
  }

  // Derive an encryption key from the user-provided password and salt using PBKDF2 with SHA-256
  int key_len = 32;
  if (!PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), salt, strlen(salt), iteration_count, key_len, cipher->key)) {
    return false;
  }

  // Set up the AES-256-GCM cipher using OpenSSL's EVP_CIPHER_CTX_new() and EVP_EncryptInit_ex() functions
  if (!(cipher->ctx = EVP_CIPHER_CTX_new())) {
    return false;
  }

  if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_gcm(), NULL, cipher->key, cipher->iv)) {
    return false;
  }

  return true;
}

// Function to encrypt data using the AES-256-GCM cipher
bool encrypt(const uint8_t *plaintext, const int plaintext_len, aes_gcm_cipher_t *cipher, uint8_t *encrypted) {
  // Check that the input plaintext length is divisible by the block size of the AES-256-GCM cipher (16 bytes)
  if (plaintext_len % 16 != 0) {
    return false;
  }

  // Initialize the encryption process using OpenSSL's EVP_EncryptUpdate() function
  int len = plaintext_len;
  if (1 != EVP_EncryptUpdate(cipher->ctx, encrypted, &len, plaintext, plaintext_len)) {
    return false;
  }

  // Finalize the encryption process using OpenSSL's EVP_EncryptFinal_ex() function
  len = 0;
  if (1 != EVP_EncryptFinal_ex(cipher->ctx, encrypted + len, &len)) {
    return false;
  }

  // Set the authentication tag for the encrypted data using OpenSSL's EVP_CIPHER_CTX_set_padding() function
  if (1 != EVP_CIPHER_CTX_set_padding(cipher->ctx, 0)) {
    return false;
  }

  return true;
}

// Function to decrypt data using the AES-256-GCM cipher
bool decrypt(const uint8_t *encrypted, const int encrypted_len, aes_gcm_cipher_t *cipher, uint8_t *plaintext) {
  // Check that the input encrypted length is divisible by the block size of the AES-256-GCM cipher (16 bytes)
  if (encrypted_len % 16 != 0) {
    return false;
  }

  // Initialize the decryption process using OpenSSL's EVP_DecryptUpdate() function
  int len = encrypted_len;
  if (1 != EVP_DecryptUpdate(cipher->ctx, plaintext, &len, encrypted, encrypted_len)) {
    return false;
  }

  // Finalize the decryption process using OpenSSL's EVP_DecryptFinal_ex() function
  len = 0;
  if (1 != EVP_DecryptFinal_ex(cipher->ctx, plaintext + len, &len)) {
    return false;
  }

  return true;
}

// Function to handle external authentication failures gracefully
bool auth_failure_handler(const char *username, const uint8_t *password_hash) {
  // Check if the password hash for the user matches the stored hash
  if (strcmp(password_hash, auth_info.password_hash) != 0) {
    return false;
  }

  // If the password is correct, update the authentication information with the new username and salt
  strcpy(auth_info.username, username);

  return true;
}

// Function to handle encryption failures gracefully
bool encrypt_failure_handler(const uint8_t *plaintext, const int plaintext_len, aes_gcm_cipher_t *cipher) {
  // Check if the cipher has been properly initialized and the input plaintext length is divisible by the block size of the AES-256-GCM cipher (16 bytes)
  if (!cipher->ctx || plaintext_len % 16 != 0) {
    return false;
  }

  // Encrypt the input plaintext using the AES-256-GCM cipher
  int len = plaintext_len;
  uint8_t *encrypted = malloc(len);
  if (!encrypt(plaintext, len, cipher, encrypted)) {
    free(encrypted);
    return false;
  }

  // Return the encrypted data
  memcpy(plaintext, encrypted, len);
  free(encrypted);

  return true;
}

// Function to handle decryption failures gracefully
bool decrypt_failure_handler(const uint8_t *encrypted, const int encrypted_len, aes_gcm_cipher_t *cipher) {
  // Check if the cipher has been properly initialized and the input encrypted length is divisible by the block size of the AES-256-GCM cipher (16 bytes)
  if (!cipher->ctx || encrypted_len % 16 != 0) {
    return false;
  }

  // Decrypt the input encrypted data using the AES-256-GCM cipher
  int len = encrypted_len;
  uint8_t *plaintext = malloc(len);
  if (!decrypt(encrypted, len, cipher, plaintext)) {
    free(plaintext);
    return false;
  }

  // Return the decrypted data
  memcpy(encrypted, plaintext, len);
  free(plaintext);

  return true;
}
```

