import java.io.IOException;
import java.lang.reflect.Type;

public class DeserializationService {
    private static final int MAX_RETRIES = 5;
    private static final long RETRY_INTERVAL = 1000; // in milliseconds

    private Map<String, Class<?>> typeMap;
    private Map<Class<?>, ConcurrentHashMap<Object, Object>> deserializationCache;

    public DeserializationService(Map<String, Class<?>> typeMap) {
        this.typeMap = new HashMap<>(typeMap);
        this.deserializationCache = new ConcurrentHashMap<>();
    }

    public <T> T deserialize(byte[] data, String typeId) throws IOException, ClassNotFoundException {
        if (data == null || typeId == null) {
            throw new IllegalArgumentException("Data and type ID must not be null");
        }

        // Retry initialization if necessary
        int retries = 0;
        while (retries < MAX_RETRIES) {
            try {
                initialize();
                break;
            } catch (IOException | ClassNotFoundException e) {
                Thread.sleep(RETRY_INTERVAL);
                retries++;
            }
        }

        // Deserialize object
        Type type = typeMap.get(typeId);
        if (type == null) {
            throw new IllegalStateException("Type ID not found in type map");
        }

        ByteArrayInputStream byteStream = new ByteArrayInputStream(data);
        ObjectInputStream objStream = new ObjectInputStream(byteStream);
        T object = (T) objStream.readObject();

        // Add object to cache if successful
        deserializationCache.putIfAbsent(type, new ConcurrentHashMap<>());
        deserializationCache.get(type).put(object, object);

        return object;
