Here is an example of a modular C library that manages a dynamic list of `item` structures, with thread safety and performance optimization in mind:
```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure for a list item
typedef struct item {
    char* name;
    float value;
    struct item* next;
} item_t;

// Structure for the list itself
typedef struct list {
    pthread_mutex_t lock;
    size_t size;
    item_t* head;
    item_t* tail;
} list_t;

// Initialize a new list instance with items from an array of `item_data`
list_t* init_list(const item_data_t* data, size_t len) {
    // Allocate memory for the list and its head/tail pointers
    list_t* list = malloc(sizeof(list_t));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Iterate through the `data` array and add each item to the list
    for (size_t i = 0; i < len; i++) {
        const item_data_t* curr = data + i;
        item_t* item = malloc(sizeof(item_t));
        if (!item) {
            free_list(list);
            return NULL;
        }
        item->name = strdup(curr->name);
        item->value = curr->value;
        item->next = NULL;
        if (list->head == NULL) {
            list->head = item;
            list->tail = item;
        } else {
            list->tail->next = item;
            list->tail = item;
        }
        list->size++;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Add an item to the end of the list
bool add_item(list_t* list, const char* name, float value) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->lock);

    // Allocate memory for the new item and initialize it
    item_t* item = malloc(sizeof(item_t));
    if (!item) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    item->name = strdup(name);
    item->value = value;
    item->next = NULL;

    // Add the new item to the end of the list
    if (list->head == NULL) {
        list->head = item;
        list->tail = item;
    } else {
        list->tail->next = item;
        list->tail = item;
    }
    list->size++;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&list->lock);
    return true;
}

// Remove an item from the end of the list
bool remove_item(list_t* list, const char* name) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->lock);

    // Find the item to be removed and its previous node
    item_t* prev = NULL;
    item_t* curr = list->head;
    while (curr != NULL) {
        if (strcmp(curr->name, name) == 0) {
            break;
        }
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    // Remove the item from the list
    if (prev != NULL) {
        prev->next = curr->next;
    } else {
        list->head = curr->next;
    }
    if (curr == list->tail) {
        list->tail = prev;
    }
    list->size--;

    // Free the memory for the removed item and its fields
    free(curr->name);
    free(curr);

    // Unlock the mutex and return success
    pthread_mutex_unlock(&list->lock);
    return true;
}

// Free all allocated memory for a list instance
void free_list(list_t* list) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->lock);

    // Iterate through the list and free each item
    item_t* curr = list->head;
    while (curr != NULL) {
        item_t* next = curr->next;
        free(curr->name);
        free(curr);
        curr = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&list->lock);
}
```
This implementation includes a `list_t` structure that maintains the head and tail pointers of the list, as well as a mutex for thread safety. The `init_list` function takes an array of `item_data_t` structures as input and initializes a new list instance with those items. The `add_item` function adds an item to the end of the list, while the `remove_item` function removes an item from the end of the list by searching for it using the given name. Finally, the `free_list` function frees all allocated memory for a list instance.']

