#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <assert.h>

#define BUFFER_SIZE 1024
#define MAX_LINE_LENGTH 8192
#define NUM_THREADS 4
#define DEFAULT_FILENAME "input.txt"
#define DEFAULT_OUTPUT_FILENAME "output.txt"

// Struct to hold file data and statistics
typedef struct {
    char* filename;
    size_t num_lines;
    size_t total_length;
} FileData;

// Function prototypes
void parseOptions(int argc, char** argv);
void processFile(char* filepath);
void printUsage();
void printManPage();
void cleanup(FileData* filedata);
void* thread_func(void* args);

// Global variables
char* filename = DEFAULT_FILENAME;
char* output_filename = DEFAULT_OUTPUT_FILENAME;
int count_only = 0;
int skip_empty = 0;
int url = 0;
int sockfd = -1;
pthread_t threads[NUM_THREADS];
FileData filedata;
struct sockaddr_in server_addr;

int main(int argc, char** argv) {
    // Parse command-line options
    parseOptions(argc, argv);

    // Set up socket for URL processing
    if (url) {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        assert(sockfd >= 0);
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(80); // hardcoded for HTTP
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    }

    // Process file
    processFile(filename);

    return 0;
}

void parseOptions(int argc, char** argv) {
    int c;
    while ((c = getopt(argc, argv, "hvmco:su:")) != -1) {
        switch (c) {
            case 'h': // help
                printUsage();
                exit(0);
            case 'v': // version
                printf("Version 1.0\n");
                exit(0);
            case 'm': // manpage
                printManPage();
                exit(0);
            case 'c': // count-only
                count_only = 1;
                break;
            case 'o': // output-file
                output_filename = optarg;
                break;
            case 's': // skip-empty
                skip_empty = 1;
                break;
            case 'u': // url
                url = 1;
                filename = optarg;
                break;
        }
    }
}

void processFile(char* filepath) {
    int fd;
    char buffer[BUFFER_SIZE];
    size_t num_lines = 0;
    size_t total_length = 0;
    struct stat st;

    // Open the file and obtain its metadata
    if (url) {
        fd = sockfd;
        if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
            perror("Error connecting to server");
            exit(1);
        }
    } else {
        if ((fd = open(filepath, O_RDONLY)) == -1) {
            perror("Error opening file");
            exit(1);
        }
    }
    if (fstat(fd, &st) < 0) {
        perror("Error obtaining metadata");
        exit(1);
    }
    assert(st.st_size > 0);

    // Allocate memory for the file data structure
    filedata.filename = malloc(strlen(filepath) + 1);
    strcpy(filedata.filename, filepath);
    filedata.num_lines = 0;
    filedata.total_length = 0;

    // Split the file into chunks for concurrent processing
    size_t chunk_size = st.st_size / NUM_THREADS;
    size_t remaining_bytes = st.st_size % NUM_THREADS;
    size_t offset = 0;
    for (int i = 0; i < NUM_THREADS; i++) {
        if (i == NUM_THREADS - 1) { // last thread processes remaining bytes
            chunk_size += remaining_bytes;
        }
        pthread_create(&threads[i], NULL, thread_func, (void*)offset);
        offset += chunk_size;
    }

    // Wait for all threads to complete and collect statistics
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    printf("Processed %zu lines with %zu bytes\n", filedata.num_lines, filedata.total_length);

    // Print metrics and write output to disk (if requested)
    if (!count_only && strcmp(output_filename, DEFAULT_OUTPUT_FILENAME)) {
        printf("Writing results to %s\n", output_filename);
        FILE* f = fopen(output_filename, "w");
        if (f == NULL) {
            perror("Error opening file for writing");
            exit(1);
        }
        fprintf(f, "%zu,%zu\n", filedata.num_lines, filedata.total_length);
        fclose(f);
    }
}

void* thread_func(void* offset) {
    int fd = sockfd; // for URL processing
    char buffer[BUFFER_SIZE];
    size_t num_lines = 0;
    size_t total_length = 0;
    struct stat st;

    // Process chunk of file concurrently
    if (url) {
        int bytes_read = 0;
        while ((bytes_read = read(fd, buffer, BUFFER_SIZE)) > 0) {
            num_lines++;
            total_length += bytes_read;
        }
        if (bytes_read < 0) {
            perror("Error reading from socket");
            exit(1);
        }
    } else {
        size_t current_offset = (size_t)offset;
        while (current_offset < st.st_size) {
            ssize_t bytes_read = pread(fd, buffer, BUFFER_SIZE, current_offset);
            if (bytes_read < 0) {
                perror("Error reading from file");
                exit(1);
            } else if (bytes_read == 0) { // EOF reached
                break;
            }
            num_lines++;
            total_length += bytes_read;
            current_offset += BUFFER_SIZE;
        }
    }

    // Update file data structure
    pthread_mutex_lock(&filedata.mutex);
    filedata.num_lines += num_lines;
    filedata.total_length += total_length;
    pthread_mutex_unlock(&filedata.mutex);
}

void printUsage() {
    printf("Usage: %s [options]\n", argv[0]);
    printf("Options:\n");
    printf("\t-h\tPrint help message and exit\n");
    printf("\t-v\tPrint version number and exit\n");
    printf("\t-m\tPrint man page for %s\n", argv[0]);
    printf("\t-c\tPrint only the number of lines and bytes in the input file\n");
    printf("\t-o <output_file>\tWrite output to <output_file>\n");
    printf("\t-s\tSkip empty lines\n");
    printf("\t-u <url>\tProcess a URL instead of a file\n");
}

void printManPage() {
    // Man page for the program
    printf("NAME\n");
    printf("\t%s - Process files in parallel\n", argv[0]);
    printf("SYNOPSIS\n");
    printf("\t%s [options]\n", argv[0]);
    printf("DESCRIPTION\n");
    printf("\tThis program processes a file or URL in parallel by dividing it into chunks and processing each chunk concurrently.\n");
    printf("\tThe output is written to the console unless the -o option is specified.\n");
    printf("\tOptions:\n");
    printUsage();
}']

