['Here is a sample implementation of the DNS resolution service in C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>

// Configurable parameters
const int NUM_THREADS = 10; // Number of worker threads for concurrent resolution
const int DNS_PORT = 53; // Port number for DNS queries
const char* DNS_SERVERS[] = {"8.8.8.8", "8.8.4.4"}; // External DNS servers with priorities
const int NUM_DNS_SERVERS = sizeof(DNS_SERVERS) / sizeof(char*); // Number of DNS servers in the list
const int RESOLUTION_TIMEOUT = 10; // Timeout for DNS resolution in seconds

// Thread pool for concurrent resolution
struct thread_pool {
    pthread_t threads[NUM_THREADS];
    int num_threads;
} tp;

// DNS server status struct
struct dns_server {
    char* hostname; // Hostname of the DNS server
    int port; // Port number for the DNS server
    bool is_up; // Flag indicating if the DNS server is up and responding
    int error_count; // Count of recent errors encountered when resolving with this DNS server
};

// Priority list of DNS servers based on their availability and response time
struct dns_server_priority {
    struct dns_server* servers[NUM_DNS_SERVERS];
    int num_servers; // Number of DNS servers in the priority list
};

// Global variables for caching
char** cached_hostnames = NULL; // Array of cached hostnames
int* cached_ips = NULL; // Array of cached IP addresses
int num_cached_hostnames = 0; // Number of cached hostnames
int max_num_cached_hostnames = NUM_THREADS * 10; // Maximum number of cached hostnames
int next_cache_index = 0; // Index of the next cache slot to use

// Function to initialize the DNS server status struct
void init_dns_server(struct dns_server* server) {
    server->hostname = NULL;
    server->port = DNS_PORT;
    server->is_up = false;
    server->error_count = 0;
}

// Function to initialize the priority list of DNS servers
void init_dns_server_priority(struct dns_server_priority* priority) {
    for (int i = 0; i < NUM_DNS_SERVERS; ++i) {
        struct dns_server* server = &(priority->servers[i]);
        init_dns_server(server);
        server->hostname = DNS_SERVERS[i];
    }
    priority->num_servers = NUM_DNS_SERVERS;
}

// Function to initialize the thread pool
void init_thread_pool() {
    tp.num_threads = 0;
}

// Function to add a new DNS server to the priority list
void add_dns_server(struct dns_server* server) {
    // Add the new DNS server to the priority list
    struct dns_server_priority* priority = &(tp.priorities[tp.num_threads]);
    if (priority->num_servers >= NUM_DNS_SERVERS) {
        return;
    }
    for (int i = 0; i < priority->num_servers; ++i) {
        struct dns_server* existing_server = &(priority->servers[i]);
        if (strcmp(existing_server->hostname, server->hostname) == 0 && existing_server->port == server->port) {
            // The new DNS server is already in the priority list, so return
            return;
        }
    }
    priority->servers[priority->num_servers++] = *server;
}

// Function to remove a DNS server from the priority list
void remove_dns_server(struct dns_server* server) {
    // Remove the DNS server from the priority list
    struct dns_server_priority* priority = &(tp.priorities[tp.num_threads]);
    for (int i = 0; i < priority->num_servers; ++i) {
        struct dns_server* existing_server = &(priority->servers[i]);
        if (strcmp(existing_server->hostname, server->hostname) == 0 && existing_server->port == server->port) {
            // Move the last DNS server in the list to the removed position and decrease the number of servers by one
            priority->servers[i] = priority->servers[priority->num_servers - 1];
            --(priority->num_servers);
            return;
        }
    }
}

// Function to resolve a hostname using the DNS resolution service
int dns_resolve(const char* hostname) {
    // Check if the hostname is already cached
    int i = 0;
    while (i < num_cached_hostnames && strcmp(hostname, cached_hostnames[i]) != 0) {
        ++i;
    }
    if (i < num_cached_hostnames) {
        return cached_ips[i];
    }

    // Check the DNS server status for each priority level and resolve with the first available server
    struct dns_server* server = NULL;
    int try_count = 0;
    while (try_count < NUM_DNS_SERVERS) {
        // Get the next priority level
        int priority_level = tp.num_threads + try_count;
        if (priority_level >= NUM_THREADS) {
            break;
        }

        // Check if there are any available DNS servers in this priority level
        struct dns_server_priority* priority = &(tp.priorities[priority_level]);
        for (int i = 0; i < priority->num_servers; ++i) {
            server = &(priority->servers[i]);
            if (server->is_up && !server->error_count) {
                break;
            }
        }
        if (server) {
            break;
        }
    }
    if (!server) {
        // All DNS servers are down, so return an error
        printf("DNS resolution failed: all servers are down\n");
        return -1;
    }

    // Perform the DNS resolution using the selected server
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket == -1) {
        printf("DNS resolution failed: unable to create socket\n");
        return -1;
    }
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(struct sockaddr_in));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(53);
    if (inet_pton(AF_INET, server->hostname, &server_address.sin_addr) == -1) {
        printf("DNS resolution failed: unable to convert hostname to IP address\n");
        return -1;
    }
    if (connect(socket, (struct sockaddr*)&server_address, sizeof(struct sockaddr)) == -1) {
        printf("DNS resolution failed: unable to connect to server\n");
        return -1;
    }
    char request[256];
    memset(&request, 0, sizeof(char)*256);
    snprintf(request, sizeof(request), "GET /%s HTTP/1.1\r\nHost: %s\r\n\r\n", hostname, hostname);
    send(socket, request, strlen(request), 0);
    char response[256];
    memset(&response, 0, sizeof(char)*256);
    recv(socket, response, sizeof(response), 0);
    if (strncmp(response, "HTTP/1.1 200 OK", 13) != 0) {
        printf("DNS resolution failed: unable to retrieve IP address\n");
        return -1;
    }
    char* ip_address = strtok(response + 13, "\r\n");
    if (!ip_address) {
        printf("DNS resolution failed: unable to retrieve IP address\n");
        return -1;
    }

    // Update the cache and return the IP address
    int ip_address_int = inet_addr(ip_address);
    if (i >= num_cached_hostnames) {
        cached_hostnames[i] = hostname;
        cached_ips[i] = ip_address_int;
        ++num_cached_hostnames;
    } else {
        cached_hostnames[i] = hostname;
        cached_ips[i] = ip_address_int;
    }
    return ip_address_int;
}

// Function to perform a DNS lookup using the DNS resolution service
void dns_lookup(const char* hostname) {
    // Check if the hostname is already cached
    int i = 0;
    while (i < num_cached_hostnames && strcmp(hostname, cached_hostnames[i]) != 0) {
        ++i;
    }
    if (i < num_cached_hostnames) {
        printf("DNS lookup: %s resolved to %d.%d.%d.%d\n", hostname, (cached_ips[i] >> 24) & 0xFF, (cached_ips[i] >> 16) & 0xFF, (cached_ips[i] >> 8) & 0xFF, cached_ips[i] & 0xFF);
        return;
    }

    // Resolve the hostname using the DNS resolution service
    int ip_address = dns_resolve(hostname);
    if (ip_address == -1) {
        printf("DNS lookup failed: unable to resolve %s\n", hostname);
        return;
    }

    // Print the IP address and update the cache
    char ip_address_str[256];
    memset(&ip_address_str, 0, sizeof(char)*256);
    snprintf(ip_address_str, sizeof(ip_address_str), "%d.%d.%d.%d", (ip_address >> 24) & 0xFF, (ip_address >> 16) & 0xFF, (ip_address >> 8) & 0xFF, ip_address & 0xFF);
    printf("DNS lookup: %s resolved to %s\n", hostname, ip_address_str);
}

// Main function
int main() {
    // Initialize the DNS resolution service and the thread pool
    init_thread_pool();
    struct dns_resolution_service* service = create_dns_resolution_service();

    // Perform a DNS lookup for "example.com" using the DNS resolution service
    char* hostname = "example.com";
    dns_lookup(hostname);

    // Update the status of the DNS resolution service
    update_status(service);

    // Shutdown the DNS resolution service and the thread pool
    shutdown_dns_resolution_service(service);
    destroy_thread_pool();

    return 0;
}']

