    sqlite3_close(db);
}

// Resolve a hostname to an IP address using DNS
in_addr_t dns_resolve(const char *hostname) {
    // Check if the hostname is cached
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            cache_hit++;
            return dns_cache[i].ip_address;
        }
    }

    // Check the rate limit for this IP address
    struct in_addr addr;
    if (inet_pton(AF_INET, hostname, &addr) == 1) {
        // Check if the IP address is already in the rate limit table
        for (int i = 0; i < MAX_DNS_REQUESTS; i++) {
            if (rate_limits[i].count > 0 &&
                rate_limits[i].timestamp + TTL_PERIOD >= time(NULL) &&
                strcmp(rate_limits[i].ip, hostname) == 0) {
                    return -1;
            }
        }

        // Add the IP address to the rate limit table if it's not there already
        for (int i = 0; i < MAX_DNS_REQUESTS; i++) {
            if (rate_limits[i].count == 0) {
                strcpy(rate_limits[i].ip, hostname);
                rate_limits[i].timestamp = time(NULL);
                break;
            }
        }
    }

    // Make a DNS query to resolve the hostname
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
        // Add the resolved IP address to the cache and return it
        for (int i = 0; i < CACHE_SIZE; i++) {
            if (strcmp(dns_cache[i].hostname, hostname) == 0) {
                strcpy(dns_cache[i].ip_address, res->ai_addr->sa_data);
                break;
            }
        }
        freeaddrinfo(res);
    } else {
        // Log the DNS resolution failure and return an error code
        printf("Error resolving hostname %s\n", hostname);
        return -1;
    }
}

// Set the cache TTL period in seconds
void set_cache_ttl(int ttl) {
    // Update the TTL period for cached DNS resolutions
    TTL_PERIOD = ttl;
}

// Set the rate limit threshold in queries per minute
void set_rate_limit(int limit) {
    // Update the rate limit threshold for this IP address
    RATE_LIMIT = limit;
}

// Enable or disable caching of DNS resolutions
void enable_caching() {
    // Disable logging if caching is enabled
    logging_count = 0;
}

// Enable or disable rate limiting of DNS requests
void enable_rate_limiting() {
    // Disable logging if rate limiting is enabled
    logging_count = 0;
}

// Log a successful DNS resolution
void log_success(const char *hostname, in_addr_t ip) {
    // Insert a record into the logging table for this DNS resolution
    sqlite3_exec(db, "INSERT INTO dns_resolutions (hostname, ip) VALUES ('%s', '%d')", NULL, hostname, ip);
}

// Log a failed DNS resolution attempt
void log_failure(const char *hostname) {
    // Insert a record into the logging table for this DNS resolution failure
    sqlite3_exec(db, "INSERT INTO dns_resolutions (hostname, ip) VALUES ('%s', -1)", NULL, hostname);
}

// Print a summary of DNS resolution statistics
void print_stats() {
    // Print the cache hit rate and the number of DNS resolution attempts made
    printf("Cache hit rate: %d%%\n", (cache_hit * 100) / (cache_hit + cache_miss));
    printf("Total DNS resolution attempts: %d\n", cache_hit + cache_miss);
}
```

This code defines a `DNSResolver` class that manages the caching of DNS resolutions and the rate limiting of DNS requests. The constructor initializes the cache and rate limit tables, and the destructor clears them. The `resolve()` method takes a hostname as input and returns its IP address if it's in the cache or can be resolved using DNS. If the hostname is not cached and the rate limit threshold has been reached, the method returns an error code. The `set_cache_ttl()` and `set_rate_limit()` methods allow the administrator to set the TTL period for cached DNS resolutions and the rate limit threshold in queries per minute, respectively. The `enable_caching()` and `enable_rate_limiting()` methods disable logging if caching or rate limiting is enabled, respectively. Finally, the `log_success()` and `log_failure()` methods insert records into the logging table for successful DNS resolutions and failed attempts, respectively.']

