using namespace std;

// Struct representing a script object
struct Script {
  string dataKey;
  string innerHTML;
};

// Function that renders an array of script objects as a footer of a web page
string renderScripts(const vector<Script>& scripts) {
  // Initialize the HTML string with the opening tag
  string html = "<footer>";

  // Iterate over the script objects and add them to the HTML string
  for (const Script& script : scripts) {
    html += "<script data-key=\"" + script.dataKey + "\" innerHTML=\"" + script.innerHTML + "\">";
  }

  // Close the footer tag and return the rendered HTML string
  html += "</footer>";
  return html;
}
