void list_remove(List *list, char *name) {
    // Acquire lock on the list
    pthread_mutex_lock(&list->lock);

    // Find the node with the given name
    Node *node = list->head;
    while (node != NULL && strcmp(node->name, name) != 0) {
        node = node->next;
    }

    // If the node is found, remove it from the list
    if (node != NULL) {
        Node *prev_node = node->prev;
        prev_node->next = node->next;
        free(node);
    }

    // Release lock on the list
    pthread_mutex_unlock(&list->lock);
}

/* ---------------------------- LOCK-FREE APPROACH ---------------------------- */

void list_add_lockfree(List *list, char *name, float value) {
    // Create a new node with the given name and value
    Node *new_node = malloc(sizeof(Node));
    strcpy(new_node->name, name);
    new_node->value = value;

