    Node *node = list->head;
    while (node != NULL && strcmp(node->name, name) != 0) {
        node = node->next;
    }

    // If the node is found, remove it from the list
    if (node != NULL) {
        Node *prev_node = node->prev;
        prev_node->next = node->next;
        free(node);
    }
}

/* ------------------------------ MULTI-VERSION CONTROL ------------------------- */

void list_add_versioned(List *list, char *name, float value) {
    // Create a new node with the given name and value
    Node *new_node = malloc(sizeof(Node));
    strcpy(new_node->name, name);
    new_node->value = value;

    // Add the new node to the front of the list
    new_node->next = list->head;
    list->head = new_node;

    // Increment the version number for each node in the list
    Node *node = list->head;
    while (node != NULL) {
        node->version++;
        node = node->next;
    }
}

void list_remove_versioned(List *list, char *name) {
    // Find the node with the given name and version number
    Node *node = list->head;
    while (node != NULL && strcmp(node->name, name) != 0) {
        node = node->next;
    }

    // If the node is found, remove it from the list
    if (node != NULL) {
        Node *prev_node = node->prev;
        prev_node->next = node->next;
        free(node);

        // Decrement the version number for each node in the list
        node = list->head;
        while (node != NULL) {
            node->version--;
            node = node->next;
        }
    }
}

/* ------------------------------ GARBAGE COLLECTION ---------------------------- */

void list_gc(List *list) {
    // Acquire lock on the list
    pthread_mutex_lock(&list->lock);

    // Find the node with the lowest version number
    Node *node = list->head;
    while (node != NULL && node->next != NULL) {
        if (node->version < node->next->version) {
            break;
        }
        node = node->next;
    }

    // If the node is found, remove it from the list
    if (node != NULL) {
        Node *prev_node = node->prev;
        prev_node->next = node->next;
        free(node);
    }

    // Release lock on the list
    pthread_mutex_unlock(&list->lock);
}

/* ------------------------------ NOTIFICATIONS ---------------------------- */

void list_notify(List *list, char *name) {
    // Acquire lock on the list
    pthread_mutex_lock(&list->lock);

    // Find the node with the given name and version number
    Node *node = list->head;
    while (node != NULL && strcmp(node->name, name) != 0) {
        node = node->next;
    }

    // If the node is found, notify any clients subscribed to it
    if (node != NULL) {
        Node *client = list->clients;
        while (client != NULL && client->version <= node->version) {
            client->last_seen = time(NULL);
            client = client->next;
        }
    }

    // Release lock on the list
    pthread_mutex_unlock(&list->lock);
}

/* ------------------------------ WEB SERVER ---------------------------- */

void list_server(List *list) {
