    WebServer *server = webserver_init();

    // Set up the HTTP handlers for the list
    webserver_add_handler(server, "/", list_handler);
    webserver_add_handler(server, "/index.html", list_handler);
    webserver_add_handler(server, "/add", list_add_handler);
    webserver_add_handler(server, "/remove", list_remove_handler);
    webserver_add_handler(server, "/notify", list_notify_handler);

    // Start the web server
    webserver_start(server);
}
