Here is an example of a modular C library for implementing an encryption service that integrates with a microservices architecture using a distributed caching system with Time-to-Live (TTL) policies:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the encryption algorithms to be used
#define ALGO_AES_256_GCM "AES-256-GCM"
#define ALGO_CHACHA20_POLY1305 "ChaCha20-Poly1305"

// Define the TTL policies for the cache
#define CACHE_TTL 300 // seconds
#define CACHE_MAX_SIZE 1000000 // bytes

// Struct to store encryption context information
struct EncryptionContext {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    size_t key_len;
};

// Function to create a new encryption context
int create_encryption_context(const char *algorithm, struct EncryptionContext **ctx) {
    EVP_CIPHER_CTX *new_ctx = NULL;

    // Initialize the OpenSSL library
    SSL_library_init();

    // Set up the encryption algorithm and key length
    int algo_nid = OBJ_txt2nid(algorithm);
    if (algo_nid == NID_undef) {
        fprintf(stderr, "Unknown encryption algorithm: %s\n", algorithm);
        return -1;
    }
    int key_len = EVP_CIPHER_key_length(EVP_get_cipherbynid(algo_nid));

    // Allocate memory for the encryption context
    new_ctx = malloc(sizeof(EVP_CIPHER_CTX));
    if (new_ctx == NULL) {
        fprintf(stderr, "Error allocating memory for encryption context\n");
        return -1;
    }

    // Initialize the encryption context with the algorithm and key length
    EVP_CIPHER_CTX_init(new_ctx);
    if (EVP_EncryptInit_ex(new_ctx, EVP_get_cipherbynid(algo_nid), NULL, NULL, NULL) != 1) {
        fprintf(stderr, "Error initializing encryption context\n");
        EVP_CIPHER_CTX_cleanup(new_ctx);
        free(new_ctx);
        return -1;
    }

    // Set the key length and generate a random key
    if (EVP_CIPHER_CTX_key_length(new_ctx) != key_len) {
        fprintf(stderr, "Error setting key length for encryption context\n");
        EVP_CIPHER_CTX_cleanup(new_ctx);
        free(new_ctx);
        return -1;
    }
    unsigned char *key = malloc(sizeof(unsigned char) * key_len);
    if (key == NULL) {
        fprintf(stderr, "Error allocating memory for encryption key\n");
        EVP_CIPHER_CTX_cleanup(new_ctx);
        free(new_ctx);
        return -1;
    }
    RAND_bytes(key, key_len);

    // Set the encryption context with the generated key
    if (EVP_EncryptInit_ex(new_ctx, NULL, NULL, key, NULL) != 1) {
        fprintf(stderr, "Error setting encryption key\n");
        free(key);
        EVP_CIPHER_CTX_cleanup(new_ctx);
        free(new_ctx);
        return -1;
    }

    // Store the context in the provided pointer and return success
    *ctx = new_ctx;
    return 0;
}

// Function to encrypt data using the encryption context
int encrypt_data(struct EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext) {
    // Allocate memory for the ciphertext
    *ciphertext = malloc(sizeof(unsigned char) * (plaintext_len + 16));
    if (*ciphertext == NULL) {
        fprintf(stderr, "Error allocating memory for ciphertext\n");
        return -1;
    }

    // Encrypt the plaintext using the encryption context
    size_t ciphertext_len = 0;
    if (EVP_EncryptUpdate(ctx, *ciphertext, &ciphertext_len, plaintext, plaintext_len) != 1) {
        fprintf(stderr, "Error encrypting data\n");
        free(*ciphertext);
        return -1;
    }

    // Set the length of the ciphertext and return success
    *ciphertext_len = ciphertext_len;
    return 0;
}

// Function to decrypt data using the encryption context
int decrypt_data(struct EncryptionContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext) {
    // Allocate memory for the plaintext
    *plaintext = malloc(sizeof(unsigned char) * (ciphertext_len));
    if (*plaintext == NULL) {
        fprintf(stderr, "Error allocating memory for plaintext\n");
        return -1;
    }

    // Decrypt the ciphertext using the encryption context
    size_t plaintext_len = 0;
    if (EVP_DecryptUpdate(ctx, *plaintext, &plaintext_len, ciphertext, ciphertext_len) != 1) {
        fprintf(stderr, "Error decrypting data\n");
        free(*plaintext);
        return -1;
    }

    // Set the length of the plaintext and return success
    *plaintext_len = plaintext_len;
    return 0;
}

// Function to clean up the encryption context
void destroy_encryption_context(struct EncryptionContext *ctx) {
    EVP_CIPHER_CTX_cleanup(ctx);
    free(ctx);
}
```

This implementation provides a `create_encryption_context` function that creates an encryption context with the specified algorithm and key length. It also provides `encrypt_data` and `decrypt_data` functions that encrypt and decrypt data using the provided encryption context. Finally, it includes a `destroy_encryption_context` function to clean up the encryption context when it is no longer needed.

Here are some examples of how you might use this implementation:
