  void connect();               // Connect to all WebSocket connections
  void disconnect();            // Disconnect from all WebSocket connections

  void sendMessage(std::string message, std::function<void(const WSMessage&)> callback);
                                // Send a message to all open WebSocket connections

  void receiveMessage(std::function<void(const WSMessage&)> callback);
                                // Receive a message from any of the open WebSocket connections

