#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/hmac.h>
#include <openssl/err.h>

#define ERR_EXIT(message) \
    fprintf(stderr, "%s\n", message); \
    exit(1);

typedef struct {
    AES_KEY aes_key;
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} cipher_context_t;

static const int IV_LENGTH = 16; // length of initialization vector (IV) in bytes

// generates a cryptographically secure random number using OpenSSL's RAND_bytes() function
int generate_random_number(unsigned char *buf, size_t buflen);

// derives encryption key from password using PBKDF2 with HMAC-SHA256
int derive_encryption_key(const unsigned char *password, const unsigned char *salt, size_t pw_len, size_t salt_len, unsigned char *key);

// initializes cipher context and generates a new initialization vector (IV) for each encryption operation
int init_cipher_context(cipher_context_t *ctx, const unsigned char *password);

// encrypts data using AES-256-CBC with the given IV and encryption key
int encrypt_data(const unsigned char *iv, const unsigned char *key, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext);

// decrypts data using AES-256-CBC with the given IV and encryption key
int decrypt_data(const unsigned char *iv, const unsigned char *key, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext);

// cleans up cipher context and frees allocated memory
void cleanup_cipher_context(cipher_context_t *ctx);

int generate_random_number(unsigned char *buf, size_t buflen) {
    int ret = RAND_bytes(buf, buflen);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }
    return 0;
}

int derive_encryption_key(const unsigned char *password, const unsigned char *salt, size_t pw_len, size_t salt_len, unsigned char *key) {
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
    if (md_ctx == NULL) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    int ret = PBKDF2_HMAC(EVP_sha256(), password, pw_len, salt, salt_len, 32768, key, 32);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    EVP_MD_CTX_free(md_ctx);
    return 0;
}

int init_cipher_context(cipher_context_t *ctx, const unsigned char *password) {
    if (generate_random_number(ctx->iv, IV_LENGTH) != 0) {
        return -1;
    }

    int ret = derive_encryption_key(password, ctx->iv, IV_LENGTH, IV_LENGTH, &ctx->aes_key);
    if (ret != 0) {
        return ret;
    }

    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    if (ctx->cipher_ctx == NULL) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    ret = EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, &ctx->aes_key, ctx->iv);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    return 0;
}

int encrypt_data(const unsigned char *iv, const unsigned char *key, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    cipher_context_t ctx;

    int ret = init_cipher_context(&ctx, key);
    if (ret != 0) {
        return ret;
    }

    int len;
    size_t ciphertext_len = plaintext_len + AES_BLOCK_SIZE - (plaintext_len % AES_BLOCK_SIZE);
    unsigned char *tmp_ciphertext = (unsigned char *)malloc(ciphertext_len);
    if (tmp_ciphertext == NULL) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    ret = EVP_EncryptUpdate(ctx.cipher_ctx, tmp_ciphertext, &len, plaintext, plaintext_len);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    memcpy(ciphertext, tmp_ciphertext, len);
    free(tmp_ciphertext);

    ret = EVP_EncryptFinal_ex(ctx.cipher_ctx, ciphertext + len, &len);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    cleanup_cipher_context(&ctx);
    return len;
}

int decrypt_data(const unsigned char *iv, const unsigned char *key, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    cipher_context_t ctx;

    int ret = init_cipher_context(&ctx, key);
    if (ret != 0) {
        return ret;
    }

    int len;
    size_t plaintext_len = ciphertext_len - AES_BLOCK_SIZE + 1;
    unsigned char *tmp_plaintext = (unsigned char *)malloc(plaintext_len);
    if (tmp_plaintext == NULL) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    ret = EVP_DecryptUpdate(ctx.cipher_ctx, tmp_plaintext, &len, ciphertext, plaintext_len);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    memcpy(plaintext, tmp_plaintext, len);
    free(tmp_plaintext);

    ret = EVP_DecryptFinal_ex(ctx.cipher_ctx, plaintext + len, &len);
    if (ret != 1) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    cleanup_cipher_context(&ctx);
    return len;
}

int main() {
    unsigned char key[32] = "my_secret_key";
    unsigned char iv[IV_LENGTH];
    memcpy(iv, ctx->iv, IV_LENGTH);

    unsigned char plaintext[] = "this is my secret message";
    size_t plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[256] = {0};
    int len;

    EVP_CIPHER_CTX *ctx = NULL;
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        ERR_error_string_n(ERR_get_error(), NULL, 0);
        return -1;
    }

    len = encrypt_data(iv, key, plaintext, plaintext_len, ciphertext);
    if (len < 0) {
        return -1;
    }

    // Do something with the encrypted data...

    len = decrypt_data(iv, key, ciphertext, len, plaintext);
    if (len < 0) {
        return -1;
    }

    printf("Plaintext: %s\n", plaintext);
}
```

This is the basic idea of encrypting a message using AES-256 in CBC mode. The `encrypt_data` function takes as input the IV, key and the message to be encrypted and returns the encrypted data. The `decrypt_data` function does the opposite and takes the encrypted data as input and returns the original message.

The `main` function creates a new EVP context using `EVP_CIPHER_CTX_new()` and initializes it with the IV, key and message to be encrypted. It then calls the `encrypt_data` function to encrypt the data.

Note that this is just an example code and you should handle errors and exceptions properly in your actual implementation.

Also, keep in mind that this is a basic example of how to use AES-256 in CBC mode with OpenSSL, there are many other things you can do with this library such as:

* Generating keys using `RSA_generate_key()` and `DH_generate_parameters()`.
* Creating self signed certificates using `X509_new()`.
* Signing data using `EVP_SignFinal()`.
* Verifying signatures using `EVP_VerifyFinal()`.

You can find more information about these functions in the OpenSSL documentation.']

