        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code != 200) {
            handle_failure("Failed to decrypt the data from the KMS");
        }

        // Get the response data from the KMS
        char *response = malloc(sizeof(char*) * 4096);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            handle_failure("Failed to get the response data from the KMS");
        }
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        free(post_data);

        // Decrypt the ciphertext using the initialized cipher
        char *decrypted = malloc(sizeof(char*) * (plaintext_len + AES_BLOCK_SIZE));
        decrypt(worker_ctx, response, decrypted);

        // Print the plaintext
        printf("%s\n", decrypted);

        // Update the KMS response time monitor
        kms_response_time = (int64_t) ((double) get_tick() / 1000.0);

        // Remove the derived key and IV from the cache
        remove_from_cache(key);

        // Free the memory
        free(password);
        free(key);
        free(iv);
        free(plaintext);
        free(ciphertext);
        free(decrypted);
    }

    return 0;
}
