void derive_keys(const char *password, size_t password_len, AES_KEY **encrypt_key, AES_KEY **decrypt_key) {
  // Allocate memory for the encryption and decryption keys
  *encrypt_key = (AES_KEY *) malloc(sizeof(AES_KEY));
