void gen_iv_threadsafe(struct iv *iv) {
  // Generate a cryptographically secure random IV using OpenSSL's RAND_bytes() function
  if (!RAND_bytes(iv->iv, sizeof(uint8_t) * AES_BLOCK_SIZE)) {
    printf("Error: Failed to generate IV\n");
    exit(1);
  }
}

// Define a function to implement a secure, thread-safe cipher context management system that supports password updates without reinitializing the entire context
void init_cipher_context(struct cipher_context *ctx) {
  // Initialize the encryption and decryption keys using PBKDF2 with HMAC-SHA256
  derive_keys(NULL, 0, &ctx->encrypt_key, &ctx->decrypt_key);

  // Generate a cryptographically secure random IV using OpenSSL's RAND_bytes() function
  gen_iv(&ctx->iv);

  // Set the block size to AES-256-GCM
  ctx->block_size = AES_BLOCK_SIZE;
}

// Define a function to update the encryption and decryption keys using PBKDF2 with HMAC-SHA256
void update_keys(struct cipher_context *ctx, const char *password) {
  // Derive the new encryption and decryption keys from the password using PBKDF2 with HMAC-SHA256
  derive_keys(password, strlen(password), &ctx->encrypt_key, &ctx->decrypt_key);
}

// Define a function to encrypt data using AES-256-GCM
void encrypt(struct cipher_context *ctx, const uint8_t *plaintext, size_t plaintext_len, uint8_t **ciphertext) {
  // Initialize the encryption key and IV for the current thread
  AES_KEY aes_encrypt_key;
  struct iv iv;

  // Generate a cryptographically secure random IV for the current thread using OpenSSL's RAND_bytes() function
  gen_iv_threadsafe(&iv);

  // Initialize the encryption key using PBKDF2 with HMAC-SHA256
  if (!PBKDF2((const uint8_t *) password, strlen(password), 0, 0, &aes_encrypt_key)) {
    printf("Error: Failed to initialize encryption key\n");
    exit(1);
  }

  // Encrypt the plaintext using AES-256-GCM
  *ciphertext = (uint8_t *) malloc(sizeof(uint8_t) * (plaintext_len + AES_BLOCK_SIZE));
  int len = AES_encrypt(plaintext, *ciphertext, &aes_encrypt_key, iv.iv, NULL);

  // Free the memory allocated for the encryption key and IV
  free(aes_encrypt_key);
  free(iv.iv);
}

// Define a function to decrypt data using AES-256-GCM
void decrypt(struct cipher_context *ctx, const uint8_t *ciphertext, size_t ciphertext_len, uint8_t **plaintext) {
  // Initialize the decryption key and IV for the current thread
  AES_KEY aes_decrypt_key;
  struct iv iv;

  // Generate a cryptographically secure random IV for the current thread using OpenSSL's RAND_bytes() function
  gen_iv_threadsafe(&iv);

  // Initialize the decryption key using PBKDF2 with HMAC-SHA256
  if (!PBKDF2((const uint8_t *) password, strlen(password), 0, 0, &aes_decrypt_key)) {
    printf("Error: Failed to initialize decryption key\n");
    exit(1);
  }

  // Decrypt the ciphertext using AES-256-GCM
  *plaintext = (uint8_t *) malloc(sizeof(uint8_t) * (ciphertext_len + AES_BLOCK_SIZE));
  int len = AES_decrypt(ciphertext, *plaintext, &aes_decrypt_key, iv.iv, NULL);

  // Free the memory allocated for the decryption key and IV
  free(aes_decrypt_key);
  free(iv.iv);
}

// Define a function to process data using the cipher context
void process(struct cipher_context *ctx, const uint8_t *data, size_t data_len) {
  // Encrypt the data using AES-256-GCM
  uint8_t *ciphertext;
  encrypt(ctx, data, data_len, &ciphertext);

  // Decrypt the ciphertext using AES-256-GCM
  uint8_t *plaintext;
  decrypt(ctx, ciphertext, data_len, &plaintext);

  // Free the memory allocated for the ciphertext and plaintext
  free(ciphertext);
  free(plaintext);
}

int main() {
  // Initialize the cipher context
  struct cipher_context ctx;
  init_cipher_context(&ctx);

  // Process data using the cipher context
  process(&ctx, NULL, 0);

  // Update the encryption and decryption keys using PBKDF2 with HMAC-SHA256
  update_keys(&ctx, "new_password");

  // Process data again using the updated cipher context
  process(&ctx, NULL, 0);

  return 0;
}
