public class AsyncStateObjectService {
    private static final int DEFAULT_THREAD_POOL_SIZE = 10;
    private static final String DEFAULT_CONFIG_PATH = "config/state-object-service.conf";

    private final ExecutorService executor;
    private final StateObjectCache cache;
    private final ConfigurationManager configManager;

    public AsyncStateObjectService() {
        this(DEFAULT_THREAD_POOL_SIZE);
    }

    public AsyncStateObjectService(int threadPoolSize) {
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
        this.cache = new StateObjectCache();
        this.configManager = new ConfigurationManager(DEFAULT_CONFIG_PATH);
    }

    public void start() throws Exception {
        configManager.loadConfigs();

        List<String> stateObjectFiles = configManager.getStateObjectFiles();
        for (String file : stateObjectFiles) {
            executor.execute(() -> cache.load(file));
        }

        executor.shutdown();
    }

    public StateObject getStateObject(String versionTag, String filePath) throws Exception {
        return cache.get(versionTag, filePath);
    }

    private class ConfigurationManager {
        private final Map<String, String> configs;

        public ConfigurationManager(String configPath) {
            this.configs = new HashMap<>();
            loadConfigs(configPath);
        }

        public List<String> getStateObjectFiles() {
            return configs.get("state-object-files").split(",")
                    .stream().map(String::trim).collect(Collectors.toList());
        }

        private void loadConfigs(String configPath) throws IOException {
            try (InputStream inputStream = new FileInputStream(configPath)) {
                Properties properties = new Properties();
                properties.load(inputStream);
                for (Map.Entry<Object, Object> entry : properties.entrySet()) {
                    String key = (String) entry.getKey();
                    String value = (String) entry.getValue();
                    configs.put(key, value);
                }
            } catch (IOException e) {
                throw new IOException("Failed to load configs from file", e);
            }
        }
    }

    private class StateObjectCache {
        private final Map<String, StateObject> cache;

        public StateObjectCache() {
            this.cache = new HashMap<>();
        }

        public void load(String filePath) throws Exception {
            // Load state objects from file and add them to the cache
        }

        public StateObject get(String versionTag, String filePath) throws Exception {
            // Get state object from cache based on version tag and file path
        }
    }
}
