}

// Define the function for encrypting data using an algorithm
int encrypt(AlgorithmInfo *info, unsigned char *data, size_t data_len, unsigned char **ciphertext, size_t *ciphertext_len) {
    int ret = 0;
    if (info->algorithm_type == 0) { // Symmetric algorithm
        ret = info->encrypt(data, data_len, ciphertext, ciphertext_len);
        if (ret != 0) {
            handle_error("Encryption failed");
            return ret;
        } else {
            printf("Encrypted %d bytes of data using algorithm %s\n", data_len, info->name);
            return *ciphertext_len;
        }
    } else if (info->algorithm_type == 1) { // Asymmetric algorithm
        ret = info->encrypt(data, data_len, ciphertext, ciphertext_len);
        if (ret != 0) {
            handle_error("Encryption failed");
            return ret;
        } else {
            printf("Encrypted %d bytes of data using algorithm %s\n", data_len, info->name);
            return *ciphertext_len;
        }
    }
}

// Define the function for decrypting data using an algorithm
int decrypt(AlgorithmInfo *info, unsigned char *data, size_t data_len, unsigned char **plaintext, size_t *plaintext_len) {
    int ret = 0;
    if (info->algorithm_type == 0) { // Symmetric algorithm
        ret = info->decrypt(data, data_len, plaintext, plaintext_len);
        if (ret != 0) {
            handle_error("Decryption failed");
            return ret;
        } else {
            printf("Decrypted %d bytes of data using algorithm %s\n", data_len, info->name);
            return *plaintext_len;
        }
    } else if (info->algorithm_type == 1) { // Asymmetric algorithm
        ret = info->decrypt(data, data_len, plaintext, plaintext_len);
        if (ret != 0) {
            handle_error("Decryption failed");
            return ret;
        } else {
            printf("Decrypted %d bytes of data using algorithm %s\n", data_len, info->name);
            return *plaintext_len;
        }
    }
}

